    [481090314] = {
        ["english"] = { [1] = "Your skills are out of my league, stranger.Talk to Hgarth at the Sun Rock Retreat in the Stonetalon Mountains. He will provide you with more knowledge than I can. " },
        ["text"] = "Твої вміння вже перевищили мої, чужинцю. Поговори з Гґартом у Притулку Сонячної Скелі в Кам'янистих горах. Він дасть тобі більше знань, ніж можу я.",
