    },
    [2559391543] = {
        ["english"] = { [1] = "Your preparations are complete.  All that now stands before you and your dreadsteed is the ritual for the Circle of Greater Summoning, and the binding of the dreadsteed's spirit..." },
        ["text"] = "Приготування завершено. Тепер між тобою, твоїм жахоконем і метою лишилися ритуал Кола Великого Виклику та прив'язування духу жахоконя...",
