    [1218156705] = {
        ["english"] = { [1] = "You will find Sildinair at the Warrior's Terrace among the guards, her keen eyes scanning the forest for enemies that might dare to enter our fair city.  " },
        ["text"] = "Сілдінаїр знайдеш на Терасі Воїнів серед вартових; її гострий погляд прочісує ліс у пошуках ворогів, що насміляться наблизитися до нашого прекрасного міста.",
