        ["roles"] = { ["greeting"] = true },
    },
    [4065061364] = {
        ["english"] = { [1] = "You are welcome here, friend and ally of the Dragonflights. Take your rest here in our halls." },
        ["text"] = "Тобі тут раді, друже й союзнику драконячих зграй. Відпочинь у наших залах.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
