    [3488372736] = {
        ["english"] = { [1] = "You need to be stronger, $c before you can help us in Alterac Valley." },
        ["text"] = "Тобі треба стати сильнішим, $c, перш ніж зможеш допомогти нам в Альтерацькій долині.",
        ["npcs"] = { [1] = 15106 },
        ["roles"] = { ["greeting"] = true },
    },
    [3355943341] = {
        ["english"] = { [1] = "Yeah, you're a real brainiac.  Just how smart do you think you are, Slip'kik?" },
        ["text"] = "Ого, та ти справжній геній. І наскільки ж розумним ти себе вважаєш, Сліп'кіку?",
        ["npcs"] = { [1] = 14323 },
        ["roles"] = { ["reply"] = true },
    },
    [439146306] = {
        ["english"] = { [1] = "You got questions, but they be too big for me to answer, $N. You be needin' to have words with the orc Yelmak in the Drag of Orgrimmar. He'll help you out." },
        ["text"] = "Маєш питання, але вони для мене завеликі, $N. Треба поговорити з орком Єлмаком у Хитрому провулку Орґріммара. Він тобі допоможе.",
        ["npcs"] = { [1] = 3184 },
        ["roles"] = { ["greeting"] = true },
    },
    [894511233] = {
        ["english"] = { [1] = "You will have to excuse me, Lorax, I do not speak 'crazy.'" },
        ["text"] = "Вибач, Лораксе, але я не розмовляю мовою «божевільних».",
        ["npcs"] = { [1] = 10918 },
        ["roles"] = { ["reply"] = true },
    },
    [2082994785] = {
        ["english"] = { [1] = "You sure we be goin' da right way, mon?" },
        ["text"] = "Ти впевнений, що ми йдемо правильним шляхом, чолов'яга?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2779947298] = {
        ["english"] = { [1] = "You're a hunter?  Well anyway, you'll find Thotar hiding from the sun inside the burrow at the southwest corner of town." },
        ["text"] = "Ти мисливець? Ну гаразд, Тотара знайдеш у норі в південно-західному кутку міста, де він ховається від сонця.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [2583512886] = {
        ["english"] = { [1] = "Yes, young one, you need not convince me of such things, the Warchief and I have much history. Your dedication, however, is noted.$B$BAs I was saying, Rend had found a new home for his people, and I was among those who would wearily follow.$B$BFrom one conflict arose others... countless others. It was in those battles for Blackrock Spire between the Blackrock clan and the Dark Iron dwarves that my sons were both slain. It was then that I realized my time among the Blackrock clan had come to an end." },
        ["text"] = "Так, юначе, мене не треба в цьому переконувати — нас із Вождем пов'язує довга історія. Проте твою відданість я помітив.$B$BЯк я й казав, Ренд знайшов новий дім для свого народу, і я був серед тих, хто втомлено пішов за ним.$B$BОдин конфлікт породжував інший... і так без кінця. Саме в боях за Чорнокамінний Шпиль між кланом Чорного Каменю та дворфами Темного Заліза загинули обидва мої сини. Тоді я й зрозумів, що моєму часу серед клану Чорного Каменю настав кінець.",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["greeting"] = true },
    },
    [3424297151] = {
        ["english"] = { [1] = "Yes, $c? Are you reporting in?" },
        ["text"] = "Так, $c? Доповідаєш?",
        ["npcs"] = { [1] = 12863 },
        ["roles"] = { ["greeting"] = true },
    },
    [89718168] = {
        ["english"] = { [1] = "You like the rug? I killed and skinned the beast myself. May all the centaur fall as easily." },
        ["text"] = "Подобається килим? Я сам убив і оббілував цього звіра. Нехай усі кентаври падають так само легко.",
        ["npcs"] = { [1] = 5811 },
        ["roles"] = { ["greeting"] = true },
    },
    [2646357831] = {
        ["english"] = { [1] = "Yes, yes. I see you.$B$BBe on your way. You may have earned the trust of a few, but it will take more than that to prove it to me!" },
        ["text"] = "Так-так. Я тебе бачу.$B$BІди своєю дорогою. Може, ти й заслужив довіру кількох із нас, але щоб переконати мене, цього замало!",
        ["npcs"] = { [1] = 11555 },
        ["roles"] = { ["greeting"] = true },
    },
    [919607489] = {
        ["english"] = { [1] = "You look like you might be needing passage across the Great Sea. Well you have come to the right place, this here is the berth of the Maiden's Fancy, finest passenger ship to travel these waters. When she arrives, just climb aboard and the next thing you know you will find yourself basking on the sandy beaches of Stranglethorn." },
        ["text"] = "Схоже, тобі потрібен прохід через Велике море. Тоді ти в правильному місці: це причал «Примхи Діви», найкращого пасажирського судна в цих водах. Коли вона прибуде, просто заходь на борт — і не встигнеш озирнутися, як уже грітимешся на піщаних пляжах Тернистої долини.",
        ["npcs"] = { [1] = 9558 },
        ["roles"] = { ["greeting"] = true },
    },
    [1635936643] = {
        ["english"] = { [1] = "Yeah?" },
        ["text"] = "Так?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2730888328] = {
        ["english"] = { [1] = "Zul'Drak belongs to da Drakkari, mon. Always will!" },
        ["text"] = "Зул'Драк належить Драккарі, чолов'яга. І завжди належатиме!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3439806869] = {
        ["english"] = { [1] = "Yo. I'm Vixton Pinchwhistle, official Arena Vendor for the Steamwheedle Fighting Circuit. If you've got the rep, I've got the goods that'll make your mouth water." },
        ["text"] = "Йо. Я Вікстон Пінчвістл, офіційний торговець арени Бойового турніру Паровиманів. Якщо репутація в тебе є, то в мене є товар, від якого слинки потечуть.",
        ["npcs"] = { [1] = 8214 },
        ["roles"] = { ["greeting"] = true },
    },
    [2722352418] = {
        ["english"] = { [1] = "You've already bested one of our riders today, so I cannot accept your challenge." },
        ["text"] = "Сьогодні ти вже переміг одного з наших вершників, тож я не можу прийняти твій виклик.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [54102439] = {
        ["english"] = { [1] = "You will need to find Nat Pagle in Dustwallow Marsh to get any better than you are currently." },
        ["text"] = "Щоб стати кращим, ніж ти є зараз, тобі треба знайти Ната Пеґла в Бруднолипкій трясовині.",
        ["npcs"] = { [1] = 1651, [2] = 1680, [3] = 1683, [4] = 1700, [5] = 2367, [6] = 2834, [7] = 3028, [8] = 3179, [9] = 3332, [10] = 3607, [11] = 4156, [12] = 4573, [13] = 5161, [14] = 5493, [15] = 5690, [16] = 5938, [17] = 5941, [18] = 7946, [19] = 12032, [20] = 12961, [21] = 14740 },
        ["roles"] = { ["greeting"] = true },
