    [4140306122] = {
        ["english"] = { [1] = "Zippik would drive us straight into the Bluff if I wasn't here. Moron." },
        ["text"] = "Зіппік загнав би нас просто в Бескид, якби не я. Ідіот.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3248149869] = {
        ["english"] = { [1] = "You want me to take part in the Hyldsmeet to end the war?" },
        ["text"] = "Ти хочеш, щоб я взяла участь у Гільдсміті й поклала край війні?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2891754065] = {
        ["english"] = { [1] = "You are dutiful to inquire, $c, but all Horde collections have been completed. We now wait for the Alliance hegemony to finish theirs, and then all will be transported to Silithus in the vicinity of Cenarion Hold." },
        ["text"] = "Сумлінно, що питаєш, $c, але Орда вже завершила всі збори. Тепер ми чекаємо, доки верховоди Альянсу завершать свої, а тоді все буде перевезено до Силітуса, в околиці Кенарійської цитаделі.",
        ["npcs"] = { [1] = 15512 },
        ["roles"] = { ["greeting"] = true },
    },
    [1316384194] = {
        ["english"] = { [1] = "Yes, I am one of the 'Broken'.  I trust that this does not bother you?  Broken or draenei, we must endure the ridicule that some in our society may throw at us.  A better understanding and communication with the elements of this world is all that matters." },
        ["text"] = "Так, я один зі Зломлених. Сподіваюся, це тебе не бентежить? Зломлені ми чи дренеї — нам доводиться зносити глузування тих, хто є в нашому суспільстві. Насправді важливе лише краще розуміння стихій цього світу та спілкування з ними.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [376581717] = {
        ["english"] = { [1] = "You can find the gryphon master on the northeast rampart overlooking the Valley of Heroes." },
        ["text"] = "Майстра грифонів знайдеш на північно-східному бастіоні, звідки видно Долину Героїв.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3676215022] = {
        ["english"] = { [1] = "Yes.  Give me the spell to summon the avatar." },
        ["text"] = "Так. Дай мені закляття, щоб викликати аватара.",
        ["npcs"] = { [1] = 8579 },
        ["roles"] = { ["reply"] = true },
    },
    [3525251937] = {
        ["english"] = { [1] = "You're Astor Hadren, right?" },
        ["text"] = "Ти Астор Гадрен, так?",
        ["npcs"] = { [1] = 6497 },
        ["roles"] = { ["reply"] = true },
    },
    [1309574089] = {
        ["english"] = { [1] = "You've got my attention." },
        ["text"] = "Ти привернув мою увагу.",
        ["npcs"] = { [1] = 12944 },
        ["roles"] = { ["reply"] = true },
    },
    [2685938753] = {
