        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [136158317] = {
        ["english"] = { [1] = "You'd better not be causing trouble, $N!" },
        ["text"] = "Краще не влаштовуй проблем, $N!",
        ["npcs"] = { [1] = 16418 },
        ["roles"] = { ["greeting"] = true },
    },
    [4113291787] = {
        ["english"] = { [1] = "You will find mailboxes within or just outside the Aldor and Scryers banks and inns." },
        ["text"] = "Поштові скриньки знайдеш у банках і заїздах Алдорів та Провидців або просто біля них.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2459647070] = {
        ["english"] = { [1] = "You are kind to seek me out, but your skills are beyond my own. Have a word with Sylvanna Forestmoon, just over there. She's been looking for another student." },
        ["text"] = "Люб'язно з твого боку шукати мене, але твої вміння вже перевищують мої. Поговори із Сильванною Лісовим Місяцем, вона он там. Якраз шукає ще одного учня.",
        ["npcs"] = { [1] = 11041 },
        ["roles"] = { ["greeting"] = true },
    },
    [3699921018] = {
        ["english"] = { [1] = "You are an exceptional enchanter. Beyond my talents as a teacher, I fear. Seek out Kitta Firewind at the Tower of Azora. Only she can qualify as your instructor now." },
        ["text"] = "Ти винятковий заклинач. Боюся, моїх талантів учителя вже недостатньо. Шукай Кітту Вогневію у Вежі Азори. Тепер лише вона гідна бути твоєю наставницею.",
        ["npcs"] = { [1] = 4213 },
        ["roles"] = { ["greeting"] = true },
    },
    [1362244285] = {
        ["english"] = { [1] = "You're better at this gig than I am! You want someone with even more experience than I've got. That'd be Doctor Herbert Halsey, an undead who works in the Apothecarium of the Undercity." },
        ["text"] = "Ти в цій справі кращий за мене! Тобі потрібен хтось іще досвідченіший. Це доктор Герберт Галсі, невмерлий, який працює в Аптекаріумі Підміста.",
        ["npcs"] = { [1] = 2837 },
        ["roles"] = { ["greeting"] = true },
    },
    [3521916979] = {
        ["english"] = { [1] = "Zul'Farrak" },
        ["text"] = "Зул'Фаррак",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2327668826] = {
        ["english"] = { [1] = "You came along just as they were about to throw me to the fiends below - for that, I thank you. Perhaps, I - rather - we, of the blue flight, can assist you further?$B$BYou have come this far, $r, risked much. Will you go a ways further to battle Nefarian and his legion of Blackrock? " },
        ["text"] = "Ти прийшов саме тоді, коли мене вже збиралися кинути потворам унизу — за це дякую. Можливо, я... тобто ми, із Синьої зграї, ще зможемо тобі допомогти?$B$BТи вже зайшов так далеко, $r, і багато чим ризикував. Чи підеш іще трохи далі — битися з Нефаріаном та його легіоном Чорного Каменю?",
        ["npcs"] = { [1] = 10740 },
        ["roles"] = { ["greeting"] = true },
    },
    [4016020869] = {
        ["english"] = { [1] = "Yes. $N. I have located the Forest Lord. We must redouble our efforts! More crystals are needed!" },
        ["text"] = "Так. $N. Я знайшов Володаря Лісу. Нам треба подвоїти зусилля! Потрібно ще більше кристалів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2207676047] = {
        ["english"] = { [1] = "You have learned all that I am able to teach you at this time, Doctor $N. Return to me when your practice has expanded and I shall train you in the ways of the more advanced medicinal arts." },
        ["text"] = "Ти вивчив усе, чого я наразі здатен навчити, докторе $N. Повернися, коли твоя практика розшириться, і я навчу тебе складніших лікарських мистецтв.",
        ["npcs"] = { [1] = 12920, [2] = 12939 },
        ["roles"] = { ["greeting"] = true },
    },
    [209796945] = {
        ["english"] = { [1] = "You seek to lower our global defenses in order to appease a paranoid magistrate and an encampment of riff-raff that are most probably suffering from heat stroke." },
        ["text"] = "Ти хочеш послабити наш загальний захист, щоб задовольнити параноїдального магістрата й табір різношерстого наброду, який, найімовірніше, просто перегрівся на сонці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2111227611] = {
        ["english"] = { [1] = "You're the champion now, buddy! Do you think you have what it takes to defend your title?" },
        ["text"] = "Тепер ти чемпіон, друже! Думаєш, зможеш захистити титул?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2832307577] = {
        ["english"] = { [1] = "Yes, please." },
        ["text"] = "Так, будь ласка.",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["reply"] = true },
    },
    [1781206791] = {
        ["english"] = { [1] = "You look for Martha Alliestar.  She on inner ring of The Apothecarium." },
        ["text"] = "Шукаєш Марту Аллістар. Вона на внутрішньому кільці Аптекаріуму.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [194964475] = {
        ["english"] = { [1] = "You'll find plenty to do here, $N." },
        ["text"] = "Тут для тебе роботи вистачить, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [572165038] = {
        ["english"] = { [1] = "Your skill displays an enduring affection for our art, but I would see further evidence of your commitment. I shall charge you with a task. Fulfill it, and I will be content." },
        ["text"] = "Твоя майстерність свідчить про щиру любов до нашого мистецтва, але я хочу побачити ще один доказ відданості. Я дам тобі завдання. Виконай його — і я буду задоволений.",
        ["npcs"] = { [1] = 7948 },
        ["roles"] = { ["greeting"] = true },
    },
    [1290758090] = {
        ["english"] = { [1] = "You're not a druid!" },
        ["text"] = "Ти не друїд!",
        ["npcs"] = { [1] = 11798, [2] = 11800 },
        ["roles"] = { ["greeting"] = true },
    },
    [2797660620] = {
        ["english"] = { [1] = "You can sleep in the barracks, if you'd like. Just don't wake my men, or I'll throw you out in the snow myself." },
        ["text"] = "Можеш спати в казармах, якщо хочеш. Тільки не буди моїх людей, інакше власноруч викину тебе в сніг.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [165127665] = {
        ["english"] = { [1] = "You ought to feel safe here; we've stepped up security at this facility after the attacks on Manaforge Duro." },
        ["text"] = "Тут можеш почуватися безпечно; після нападів на манакузню Дуро ми посилили охорону цього об'єкта.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [301166208] = {
        ["english"] = { [1] = "Yes, I think you have potential. Maybe I can show you a thing or two." },
        ["text"] = "Так, думаю, в тобі є потенціал. Може, я зможу показати тобі дещо.",
        ["npcs"] = { [1] = 11048 },
        ["roles"] = { ["greeting"] = true },
    },
    [1448839220] = {
        ["english"] = { [1] = "Your choice was bold! I respect your desire for glory and honor! Die well, $N!" },
        ["text"] = "Сміливий вибір! Я поважаю твоє прагнення слави й честі! Помри гідно, $N!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2356080633] = {
        ["english"] = { [1] = "You'll need to prove your worthiness before I go giving away my secrets! I've got just the test for you..." },
        ["text"] = "Перш ніж я розкриватиму свої таємниці, доведи, що гідний! Я якраз маю для тебе випробування...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2944735303] = {
        ["english"] = { [1] = "You have done well, traveler. I am proud to call you my student!" },
        ["text"] = "Ти добре впорався, мандрівнику. Я пишаюся, що можу називати тебе своїм учнем!",
        ["npcs"] = { [1] = 4159 },
        ["roles"] = { ["greeting"] = true },
    },
    [1499177996] = {
        ["english"] = { [1] = "You act like this is the best junk I've ever seen. Sure it's ok, but I see stuff this 'OK' every day. Tell you what, you find a way to wow me, and I'll teach you things that make dwarves smile in their sleep." },
        ["text"] = "Поводишся так, ніби це найкращий мотлох, який я коли-небудь бачив. Та воно непогане, але таке «непогане» я бачу щодня. Ось що: знайди спосіб справді мене вразити — і я навчу тебе такого, від чого дворфи усміхатимуться уві сні.",
        ["npcs"] = { [1] = 2836 },
        ["roles"] = { ["greeting"] = true },
    },
    [3027402915] = {
        ["english"] = { [1] = "You brought the green to my land for a short time.  It is enough.  I am at peace.  I am ready for my long sleep." },
        ["text"] = "Ти ненадовго повернув зелень на мою землю. Цього досить. Я спокійний. Я готовий до довгого сну.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [165590088] = {
        ["english"] = { [1] = "You're talking to the wrong orc. I don't train novices. Talk to young Whuut over there... and use small words." },
        ["text"] = "Ти говориш не з тим орком. Я не навчаю новачків. Поговори з молодим Вуутом он там... і говори простими словами.",
        ["npcs"] = { [1] = 3347 },
        ["roles"] = { ["greeting"] = true },
    },
    [3505924474] = {
        ["english"] = { [1] = "Your errand must mean much, $c, to draw you so deep into the marsh..." },
        ["text"] = "Твоя справа, мабуть, дуже важлива, $c, якщо завела тебе так глибоко в трясовину...",
        ["npcs"] = { [1] = 6546 },
        ["roles"] = { ["greeting"] = true },
    },
    [468385817] = {
        ["english"] = { [1] = "Yes I checked, I'm missing the top piece!" },
        ["text"] = "Так, я перевірив — у мене бракує верхньої частини!",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["reply"] = true },
    },
    [1250951153] = {
        ["english"] = { [1] = "You have gone to great lengths, stranger, and you have my appreciation. I promised to further your training, and now I shall keep that promise." },
        ["text"] = "Ти пройшов великий шлях, чужинцю, і маєш мою вдячність. Я обіцяв продовжити твоє навчання — і тепер дотримаю слова.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2867697286] = {
        ["english"] = { [1] = "You can learn to sew up in Orgrimmar.  That's to the north.  Maybe one of the Orgrimmar Grunts can help you." },
        ["text"] = "Шити можна навчитися в Орґріммарі. Це на півночі. Може, хтось із орґріммарських рубак підкаже тобі дорогу.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [4108330307] = {
        ["english"] = { [1] = "Your jormungar can only move if you've submerged beneath the snow, but it cannot attack while submerged. Once your jormungar emerges, it can use its powerful acid attack to wear through the armor of the Iron Colossus. Be ready to submerge to escape from the Iron Colossus's most devastating attacks." },
        ["text"] = "Твій йормунґар може рухатися лише тоді, коли занурений під сніг, але атакувати під ним не здатен. Коли йормунґар вирине, скористайся його потужною кислотною атакою, щоб роз'їсти броню Залізного Колоса. Будь готовий знову пірнути, щоб урятуватися від найруйнівніших атак Колоса.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4130810733] = {
        ["english"] = { [1] = "You best head up to Stormwind in the Dwarven District if you want to learn to mine.  Surely one of the dwarves there can teach you the profession." },
        ["text"] = "Якщо хочеш навчитися гірництва, рушай до Штормовію, в Дворфівський район. Напевно, хтось із тамтешніх дворфів навчить тебе ремесла.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [578757299] = {
        ["english"] = { [1] = "You stand before a master of the Arcane. One would be unwise to challenge me. Many corpses have been left ablaze in my wake." },
        ["text"] = "Перед тобою майстер Аркани. Кидати мені виклик було б нерозумно. За мною лишилося чимало обвуглених тіл.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1421863773] = {
        ["english"] = { [1] = "You were right, Fairbanks. That is tragic." },
        ["text"] = "Ти мав рацію, Феєрбенксе. Це трагедія.",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [3440903634] = {
        ["english"] = { [1] = "You'll find Innkeeper Renee inside the Gallows' End Tavern at the southeast end of the street running through town." },
        ["text"] = "Господиню заїзду Рене знайдеш у таверні «Кінець Шибеника» в південно-східному кінці головної вулиці міста.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [3374702242] = {
        ["english"] = { [1] = "You're insane." },
        ["text"] = "Ти божевільний.",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["reply"] = true },
    },
    [1536860238] = {
        ["english"] = { [1] = "Ysera is my answer." },
        ["text"] = "Ізера — моя відповідь.",
        ["npcs"] = { [1] = 4489 },
        ["roles"] = { ["reply"] = true },
    },
    [3185440085] = {
        ["english"] = { [1] = "Yes, but you'll find it more rewarding if you have skill in herbalism!  You will be required to nurture and cultivate special seeds -- not to swing an axe blindly or gesticulate wildly at passing shadows.  While the Evergreen Pouch you'll receive allows even the simplest brute to grow something, those who show some aptitude will have more bountiful results." },
        ["text"] = "Так, але тобі буде значно легше, якщо володієш травництвом! Тобі доведеться плекати й вирощувати особливе насіння — а не бездумно махати сокирою чи розмахувати руками на тіні. Вічнозелена торбинка, яку ти отримаєш, дасть змогу виростити щось навіть найпростішому громилі, але знавці травництва матимуть щедріший урожай.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1452868872] = {
        ["english"] = { [1] = "You have come to learn in the art of warfare, $r? You have come to the wrong place." },
        ["text"] = "Ти прийшов навчатися мистецтва війни, $r? Тоді прийшов не туди.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [577458108] = {
        ["english"] = { [1] = "You honor the spirits of the animals you must slay by not letting them go to waste.  Aska Mistrunner will show you how.  She has a kitchen on the high rise." },
        ["text"] = "Ти вшановуєш духів тварин, яких мусиш убивати, не дозволяючи їхнім тілам пропадати намарно. Аска Туманна Бігунка покаже тобі як. У неї кухня на верхньому уступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [813299507] = {
        ["english"] = { [1] = "Yo! Have you heard about the Steamwheedle Fighting Circuit?You can find Arena Organizers selling the arena team charters in Gadgetzan and outside the arenas in Nagrand and the Blade's Edge Mountains." },
        ["text"] = "Йо! Чув про Бойовий турнір Паровиманів? Організаторів арени, які продають хартії команд, можна знайти в Пристробляску та біля арен у Награнді й Лезокраїх горах.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [579599250] = {
        ["english"] = { [1] = "Your talent is beyond my own, friend. Speak with Tarn here; his knowledge of leather is much greater than mine. I'm sure he would welcome another student." },
        ["text"] = "Твій талант перевищує мій, друже. Поговори з Тарном, він тут; його знання про шкіру значно глибші за мої. Упевнений, він буде радий новому учневі.",
        ["npcs"] = { [1] = 3008 },
        ["roles"] = { ["greeting"] = true },
    },
    [963878971] = {
        ["english"] = { [1] = "You may have what it takes. Let's find out!" },
        ["text"] = "Може, в тебе й є потрібні здібності. Перевірмо!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3187147483] = {
        ["english"] = { [1] = "You think you have what it takes to destroy The League of Arathor, $c?  I hope so.  What is it that you want, or are you simply here to waste my time?" },
        ["text"] = "Думаєш, у тебе вистачить духу знищити Лігу Аратора, $c? Сподіваюся. Чого тобі треба, чи ти просто прийшов марнувати мій час?",
        ["npcs"] = { [1] = 12198 },
        ["roles"] = { ["greeting"] = true },
    },
    [3473697968] = {
        ["english"] = { [1] = "You're kidding, right? Ok, ok, don't panic. Luckily when I was imbueing it with the component that you retrieved, I attuned myself to it as well. I should be able to locate and summon it from wherever it is that you left it.$B$BAre you sure that you've lost it? You looked in all of your bags and the bank?" },
        ["text"] = "Ти жартуєш, так? Гаразд, гаразд, без паніки. На щастя, коли я насичував його компонентом, який ти приніс, я також налаштувався на нього. Маю змогу відшукати й викликати його звідти, де ти його залишив.$B$BТи точно його загубив? Перевірив усі сумки й банк?",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [1644089067] = {
        ["english"] = { [1] = "You should try the springpaw appetizers, they're to die for!" },
        ["text"] = "Спробуй закуски з веснянолапів — за них і померти не шкода!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [603077108] = {
        ["english"] = { [1] = "Your help with the Shadowpine trolls is proving invaluable, $c. Keep this up and maybe we'll be able to turn our attention back to dealing with the Scourge." },
        ["text"] = "Твоя допомога проти тролів Тіньової Сосни безцінна, $c. Продовжуй у тому ж дусі, і, можливо, ми знову зможемо зосередитися на Скверні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [394569254] = {
        ["english"] = { [1] = "Yet? Yet what??" },
        ["text"] = "Ще? Ще що??",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [430700592] = {
        ["english"] = { [1] = "You are looking for Uthan Stillwater.  You will find him west of the village, fishing at Stonebull Lake." },
        ["text"] = "Тобі потрібен Утан Тиховод. Знайдеш його на захід від селища, він рибалить на озері Кам'яного Бика.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [2531877121] = {
        ["english"] = { [1] = "You ask of the Sons of Cenarius, Remulos and Zaetar.$B$BMy father, Remulos, was strong and beautiful, and my uncle, Zaetar, very cunning and slight of build. While they were respected quite equally, Zaetar always felt as if he could never quite compare to the glory and attention he thought Remulos had.$B$BAfter my sisters and I were born, Zaetar, blinded by jealousy, set out to outdo his brother... He was the creator of his own end. The sadness it brings me has never lessened, even as time passes..." },
        ["text"] = "Ти питаєш про синів Кенарія — Ремула та Заетара.$B$BМій батько Ремул був сильним і вродливим, а мій дядько Заетар — дуже хитрим і худорлявим. Їх поважали майже однаково, але Заетарові завжди здавалося, що він ніколи не зрівняється зі славою та увагою, якими, на його думку, користувався Ремул.$B$BПісля того як народилися ми з сестрами, Заетар, засліплений заздрістю, вирішив перевершити брата... І сам наблизив свій кінець. Смуток від цього не меншає навіть із плином часу...",
        ["npcs"] = { [1] = 13716 },
        ["roles"] = { ["greeting"] = true },
    },
    [1369437111] = {
        ["english"] = { [1] = "You need something fixed? Use the Vend-O-Tron D-Luxe." },
        ["text"] = "Треба щось полагодити? Скористайся «Венд-о-троном Де-Люкс».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4006820113] = {
        ["english"] = { [1] = "Yes, I have. Teach me." },
        ["text"] = "Так. Навчи мене.",
        ["npcs"] = { [1] = 6707 },
        ["roles"] = { ["reply"] = true },
    },
    [2006148221] = {
        ["english"] = { [1] = "You've already done me a great service, $N. For that I thank you.$B$BThe least I can do now is tell you what brought me here: My long time friend Trey Lightforge and I came to Jaedenar to investigate the Shadow Council when they caught us unprepared. They took Trey deeper into Shadow Hold and put me in here after taking all of our equipment... I can still hear his screams from below, $N. They were... inhuman. I don't know what they've done to him, but they will pay for it. " },
        ["text"] = "Ти вже зробив мені велику послугу, $N. За це дякую.$B$BНайменше, що можу зробити, — розповісти, що привело мене сюди. Ми з моїм давнім другом Треєм Світлоковачем прийшли до Джеденара розслідувати діяльність Ради Тіней, але вони застали нас зненацька. Трея забрали глибше до Оплоту Тіні, а мене кинули сюди, відібравши все спорядження... Я досі чую його крики знизу, $N. Вони були... нелюдські. Не знаю, що вони з ним зробили, але вони за це заплатять.",
        ["npcs"] = { [1] = 11016 },
        ["roles"] = { ["greeting"] = true },
    },
    [3303733698] = {
        ["english"] = { [1] = "You require the instruction of a true master! Go to Daryl Stack in Tarren Mill and embrace your destiny!" },
        ["text"] = "Тобі потрібні настанови справжнього майстра! Іди до Деріла Стека в Тарренський Млин і прийми свою долю!",
        ["npcs"] = { [1] = 4576 },
        ["roles"] = { ["greeting"] = true },
    },
    [1796872091] = {
        ["english"] = { [1] = "You will find the the battlemasters gathered at the Warrior's Terrace." },
        ["text"] = "Розпорядники бою зібралися на Терасі Воїнів.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3063937386] = {
        ["english"] = { [1] = "You're an alchemist?  So am I.  Perhaps you can teach me what you know..." },
        ["text"] = "Ти алхімік? Я теж. Можливо, навчиш мене тому, що знаєш...",
        ["npcs"] = { [1] = 8696 },
        ["roles"] = { ["reply"] = true },
    },
    [4270585325] = {
        ["english"] = { [1] = "You've made the right decision $c.  You'll find our battlemaster, Glordrum Steelbeard, in the Hall of Arms.  Good luck $N!" },
        ["text"] = "Ти зробив правильний вибір, $c. Нашого розпорядника бою Ґлордрума Сталеборода знайдеш у Залі Зброї. Удачі, $N!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3199438856] = {
        ["english"] = { [1] = "Yes, friends. This man was no wizard of Dalaran. His clothes looked quite foreign, and his accent was unfamiliar. All he could mumble about was time this, time that. You'll have to find that wizard and convince him to release me." },
        ["text"] = "Так, друзі. Цей чоловік не був чарівником Даларана. Одяг на ньому був геть чужоземний, та й акцент незнайомий. Він лише бурмотів щось про час — то одне, то інше. Вам доведеться знайти того чарівника й переконати його звільнити мене.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2773055527] = {
        ["english"] = { [1] = "Yeah, yeah... welcome to my station.$B$BSo, what do you think?  Pretty nifty what we've done here, wouldn't you say?$B$BMakes me glad to be rid of those stuffy elves at Sylvanaar anyway.$B$BMake yourself useful around here; there're plenty of experiments and whatnot to help out with." },
        ["text"] = "Авжеж, авжеж... ласкаво прошу до моєї станції.$B$BНу, що скажеш? Непогано ми тут усе влаштували, еге ж?$B$BПринаймні я радий, що позбувся тих пихатих ельфів із Сильванаару.$B$BНе стій без діла; тут повно дослідів та всілякої роботи, де знадобиться допомога.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2383807098] = {
        ["english"] = { [1] = "You're a $r, right?  I am heartened to see you here!  We can use all of the help that we can get." },
        ["text"] = "Ти $r, так? Радий бачити тебе тут! Нам знадобиться будь-яка допомога.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3315166761] = {
        ["english"] = { [1] = "You need to be exalted with the tauren of Thunder Bluff before I will teach you a riding skill, $c." },
        ["text"] = "Ти маєш бути звеличеним серед тауренів Громового Бескиду, перш ніж я навчу тебе верхової їзди, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3786325784] = {
        ["english"] = { [1] = "You need something? Maybe your armor or weapon repaired? Hmm?" },
        ["text"] = "Щось треба? Може, полагодити обладунок чи зброю? Гм?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2758837884] = {
        ["english"] = { [1] = "You! $R! Come here. <snort>$B$BTime is short, and my end <snort> is near. Mangletooth shall win; you will see. <snort>$B$BMy capture can still aid <snort> my people. The Razormane tribe is more powerful than the Bristlebacks!$B$BThe Horde looks to find out who leads the raids on their people. You <snort> shall aid Mangletooth in return for the information only I know. Mangletooth can help you! <snort> But you must help Mangletooth." },
        ["text"] = "Ти! $R! Іди сюди. <фиркає>$B$BЧасу мало, а мій кінець <фиркає> близько. Кривозуб переможе; побачиш. <фиркає>$B$BМій полон усе ще може допомогти <фиркає> моєму народу. Плем'я Гострогривих сильніше за Щетиношкурих!$B$BОрда хоче дізнатися, хто очолює набіги на їхній народ. Ти <фиркає> допоможеш Кривозубу в обмін на відомості, які знаю лише я. Кривозуб може допомогти тобі! <фиркає> Але ти мусиш допомогти Кривозубу.",
        ["npcs"] = { [1] = 3430 },
        ["roles"] = { ["greeting"] = true },
    },
    [2785317220] = {
        ["english"] = { [1] = "Your talents in cooking are a little too low.  Maybe with some practice I can teach you what I know." },
        ["text"] = "Твої кулінарні вміння поки трохи замалі. Попрактикуйся — і, можливо, я зможу навчити тебе того, що знаю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [469139856] = {
        ["english"] = { [1] = "Your skill exceeds mine, though  I've heard that Old Man Heming in Booty Bay has copies of \"The Bass and You\".  That is sure to help you increase your skill." },
        ["text"] = "Твоя майстерність перевищує мою, але чув, що Старий Гемінґ у Бухті Наживи має примірники «Окунь і ти». Це точно допоможе тобі покращити вміння.",
        ["npcs"] = { [1] = 1651, [2] = 1680, [3] = 1683, [4] = 1700, [5] = 2367, [6] = 2834, [7] = 3028, [8] = 3179, [9] = 3332, [10] = 3607, [11] = 4156, [12] = 4573, [13] = 5161, [14] = 5493, [15] = 5690, [16] = 5938, [17] = 5941, [18] = 7946, [19] = 12032, [20] = 12961, [21] = 14740 },
        ["roles"] = { ["greeting"] = true },
    },
    [3006639184] = {
        ["english"] = { [1] = "You can pick up your love letters outside the bank in the middle of the Valley of Strength." },
        ["text"] = "Любовні листи можна забрати біля банку посеред Долини Сили.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [2209594311] = {
        ["english"] = { [1] = "You'll want to learn from Zamja.  Head to Borstan's Firepit on the upper level of The Drag by taking the stairs on the left as you enter from the Valley of Strength." },
        ["text"] = "Тобі варто вчитися в Замджі. Іди до Вогнища Борстана на верхньому рівні Хитрого провулка: коли ввійдеш із Долини Сили, піднімися сходами ліворуч.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1314908179] = {
        ["english"] = { [1] = "You can see me? Do you know how much I'm ignored up here just because no one can see me? How refreshing to finally have someone to talk to!$B$BSo, you must have been sent by some living member of my former mercenary company, am I right? Of course I am!$B$BBut enough idle chit-chat, there's a great deal of work for you and I if you're going to put things right and return Lord Valthalak's spirit to him!" },
        ["text"] = "Ти мене бачиш? Уявляєш, як мене тут ігнорують лише тому, що ніхто не може побачити? Яка ж радість нарешті з кимось поговорити!$B$BОтже, тебе прислав хтось із живих членів моєї колишньої компанії найманців, так? Авжеж, так!$B$BАле досить балачок. Якщо ми хочемо все виправити й повернути дух лорда Валталака, на нас із тобою чекає чимало роботи!",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [738360727] = {
        ["english"] = { [1] = "You have to get out of here before it gets to you, too!" },
        ["text"] = "Тобі треба забиратися звідси, поки воно й до тебе не дісталося!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [506703401] = {
        ["english"] = { [1] = "You're better at this gig than I am! You want someone with even more experience than I've got. That'd be Ainethil, a night elf lady who lives in the Craftsmen's Terrace of Darnassus." },
        ["text"] = "Ти в цій справі кращий за мене! Тобі потрібен хтось іще досвідченіший. Це Айнетіль, нічна ельфійка, яка живе на Ремісничій терасі в Дарнасі.",
        ["npcs"] = { [1] = 2837 },
        ["roles"] = { ["greeting"] = true },
    },
    [3759031140] = {
        ["english"] = { [1] = "Yes?  Darn it all, now I'll have to start over from scratch!" },
        ["text"] = "Так? От халепа, тепер доведеться починати все з самого початку!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1701516254] = {
        ["english"] = { [1] = "You probably weren't expecting to find me in this cave, were you?$B$BMy name's J.D., and I really can't tell you much about how I got here, but what I can tell you is that this cave is my home now!$B$BI spend my time studying the strange crystals that can be found all over the crater." },
        ["text"] = "Мабуть, не сподівався знайти мене в цій печері, еге ж?$B$BМене звати Дж. Д., і я не можу багато розповісти, як тут опинився, але можу сказати одне: тепер ця печера — мій дім!$B$BЯ проводжу час, вивчаючи дивні кристали, що трапляються по всьому кратеру.",
        ["npcs"] = { [1] = 9117 },
        ["roles"] = { ["greeting"] = true },
    },
    [4204740990] = {
        ["english"] = { [1] = "Yes, but you'll find it more rewarding if you have skill in herbalism!  You'll be nurturing and cultivating special seeds.  While the Evergreen Pouch you'll receive allows even a novice to grow something, those who show some aptitude in herbalism will have more bountiful results." },
        ["text"] = "Так, але тобі буде значно легше, якщо володієш травництвом! Ти плекатимеш і вирощуватимеш особливе насіння. Вічнозелена торбинка, яку ти отримаєш, дасть змогу виростити щось навіть новачкові, але знавці травництва матимуть щедріший урожай.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2947375784] = {
        ["english"] = { [1] = "You'll find Elder Grimtotem at the Lariss Pavilion in Feralas." },
        ["text"] = "Старійшину Похмурого Тотема знайдеш у павільйоні Ларісс у Фераласі.",
        ["npcs"] = { [1] = 15556, [2] = 15587, [3] = 15604 },
        ["roles"] = { ["greeting"] = true },
    },
    [1177390394] = {
        ["english"] = { [1] = "You need to be exalted with the trolls of the Darkspear tribe before I will teach you a riding skill, $c." },
        ["text"] = "Ти маєш бути звеличеним серед тролів племені Темносписа, перш ніж я навчу тебе верхової їзди, $c.",
        ["npcs"] = { [1] = 7953 },
        ["roles"] = { ["greeting"] = true },
    },
    [90511207] = {
        ["english"] = { [1] = "Yes, yes, calm down, $c, there's nothing to worry about. As luck would have it, when you first gave the left piece to me, I attuned myself to it, so summoning it back from wherever you 'misplaced' it is really not a problem.$B$BHere, and this time try to take better care of it." },
        ["text"] = "Так-так, заспокойся, $c, нема про що хвилюватися. На щастя, коли ти вперше передав мені ліву частину, я налаштувався на неї, тож викликати її назад із того місця, де ти її «загубив», зовсім не складно.$B$BОсь. І цього разу постарайся краще про неї дбати.",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [1730367932] = {
        ["english"] = { [1] = "You are ready for greater things! See Franklin Lloyd, to my right. He will guide you from now on." },
        ["text"] = "Ти готовий до більшого! Звернися до Франкліна Ллойда, він праворуч від мене. Відтепер він буде твоїм наставником.",
        ["npcs"] = { [1] = 4586 },
        ["roles"] = { ["greeting"] = true },
    },
    [4182276944] = {
        ["english"] = { [1] = "You may seek out Martin Lindsey inside the Pools of Vision, underneath the Spirit Rise.  He will assist you on your way to Arathi Basin." },
        ["text"] = "Знайди Мартіна Ліндсі в Озерах Видіння під Верхів'ям Духів. Він допоможе тобі на шляху до Низини Араті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2781189445] = {
        ["english"] = { [1] = "Yes, please!" },
        ["text"] = "Так, будь ласка!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2229053840] = {
        ["english"] = { [1] = "You are going to love this story, $r. See, here is the thing. As soon as Malygos charged me with protecting the scepter shard, I knew I was in for an eternity of headache and pain.$B$BAll I want to do is study these magic rich shorelines and take in what artifacts might remain from the Sundering. You know, there was once a thriving Highborne civilization here! You don't have to tell me that there is going to be some solid magical items around here, $r. I can smell it!" },
        ["text"] = "Тобі сподобається ця історія, $r. Ось у чому річ. Щойно Маліґос доручив мені охороняти уламок скіпетра, я зрозумів, що на мене чекає вічність головного болю й страждань.$B$BА я лише хочу досліджувати ці насичені магією узбережжя й вивчати артефакти, що могли лишитися після Розколу. Знаєш, колись тут процвітала цивілізація Високородних! І не треба казати мені, що тут мають бути справжні магічні скарби, $r. Я їх чую нутром!",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [2354405103] = {
        ["english"] = { [1] = "Your continued service to the Blood Elves is paramount to our survival!  We must all pitch in and pull ourselves out of the mire we all find ourselves in.$B$BIf you're ready to work, then let's get started." },
        ["text"] = "Твоє подальше служіння ельфам крові життєво важливе для нашого виживання! Ми всі мусимо докласти зусиль, щоб вибратися з цієї трясовини.$B$BЯкщо готовий працювати — починаймо.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2485488233] = {
        ["english"] = { [1] = "Yes, please summon it back!" },
        ["text"] = "Так, будь ласка, виклич його назад!",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["reply"] = true },
    },
    [1434355734] = {
        ["english"] = { [1] = "Your capacity for learning has outstripped mine. You will need to talk to Bena Winterhoof over there for further instruction. Please don't take too much of her time, though. She needs her rest." },
        ["text"] = "Твоя здатність до навчання перевершила мою. Для подальших настанов поговори з Беною Зимовим Копитом, он там. Тільки не забирай у неї надто багато часу — їй треба відпочивати.",
        ["npcs"] = { [1] = 11047 },
        ["roles"] = { ["greeting"] = true },
    },
    [3449014088] = {
        ["english"] = { [1] = "Yes my $g son : daughter;? What can I assist you with?" },
        ["text"] = "Так, $g мій синку : моя доню;? Чим можу допомогти?",
        ["npcs"] = { [1] = 2327 },
        ["roles"] = { ["greeting"] = true },
    },
    [145923047] = {
        ["english"] = { [1] = "You better wake up real quick, rookie.  This isn't our cushy backyard outside of Skettis; this is the Blade's Edge Mountains!  One false move and it's crash and burn!" },
        ["text"] = "Краще швидко прокинься, новобранцю. Це не наш затишний дворик біля Скеттіса — це Лезокраї гори! Один хибний рух — і летиш униз палаючим уламком!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2337954253] = {
        ["english"] = { [1] = "Yep, I've been stuck here for as long as I can remember.$B$BIn my former life, I was an armorer. Perhaps I can fix something for you?" },
        ["text"] = "Еге ж, я стирчу тут, відколи себе пам'ятаю.$B$BУ минулому житті я був бронником. Може, полагодити тобі щось?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1912289069] = {
        ["english"] = { [1] = "You got me good boss!  How you get by Slip'kik??  I smart though, I watch next time!  Har har!$B$BNobody get by Slip'kik no more. Slip'kik promise!" },
        ["text"] = "Добре мене провів, бос! Як ти пройшов повз Сліп'кіка?? Але я розумний, наступного разу дивитимусь краще! Хар-хар!$B$BБільше ніхто не пройде повз Сліп'кіка. Сліп'кік обіцяє!",
        ["npcs"] = { [1] = 14323 },
        ["roles"] = { ["greeting"] = true },
    },
    [174541479] = {
        ["english"] = { [1] = "Yes, I expected that you would be back. I sent Korra out earlier and she came across Dartol's Rod, abandoned in the forest.$B$BWe worked so hard to recover it, $N. Please take care to see that you do not handle it so carelessly in the future." },
        ["text"] = "Так, я очікував твого повернення. Раніше я послав Корру, і вона знайшла жезл Дартола, покинутий у лісі.$B$BМи так тяжко працювали, щоб повернути його, $N. Будь ласка, надалі не поводься з ним так недбало.",
        ["npcs"] = { [1] = 3691 },
        ["roles"] = { ["greeting"] = true },
    },
    [2809497927] = {
        ["english"] = { [1] = "You've convinced me of your intentions, $N, and you have my thanks for being willing to help out the members of my former mercenary company, The Veiled Blade.$B$BNow let's see, what's next on our list of things to do?" },
        ["text"] = "Ти переконав мене у своїх намірах, $N, і я вдячний, що готовий допомогти членам моєї колишньої компанії найманців — Завуальованого Клинка.$B$BОтже, що там у нас далі за списком?",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [2812712194] = {
        ["english"] = { [1] = "Yes, I have seen the shaman you seek. Last I saw her, she was to the west of here. She hides in the hills above the Razormane tribe. If you're clever, you'll be able to find a path to her hut in the hills. It is not too far north of here. That path should allow you to find her without fighting through the quilboar." },
        ["text"] = "Так, я бачила шаманку, яку ти шукаєш. Востаннє вона була на захід звідси. Вона ховається на пагорбах над племенем Гострогривих. Якщо маєш кмітливість, знайдеш стежку до її хатини в пагорбах. Це недалеко на північ звідси. Так ти зможеш дістатися до неї, не прориваючись крізь свинобразів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2016324087] = {
        ["english"] = { [1] = "You look for Josef Gregorian.  He in Magic Quarter on inner ring side of green canal." },
        ["text"] = "Шукаєш Йозефа Ґреґоріана. Він у Кварталі магів, на внутрішньому кільці біля зеленого каналу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2142311653] = {
        ["english"] = { [1] = "You will not be disappointed, traveler. Tailoring is a joyous endeavor." },
        ["text"] = "Не розчаруєшся, мандрівнику. Кравецтво — радісне ремесло.",
        ["npcs"] = { [1] = 11050 },
        ["roles"] = { ["greeting"] = true },
    },
    [139956926] = {
        ["english"] = { [1] = "You're looking for Mishiki.  She has a hut to the south in Sen'jin Village." },
        ["text"] = "Шукаєш Мішікі. У неї хатина на півдні в селищі Сен'джин.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [1428687315] = {
        ["english"] = { [1] = "You'll have to give me a moment, $c, the naga are attacking us right now. I'll speak to you as soon as the attack is done!" },
        ["text"] = "Дай мені хвилинку, $c, наґи саме зараз на нас нападають. Поговорю з тобою, щойно напад скінчиться!",
        ["npcs"] = { [1] = 8380 },
        ["roles"] = { ["greeting"] = true },
    },
    [534228289] = {
        ["english"] = { [1] = "You may find storage for your worldly goods at the bank of Darnassus, which lies in the center of our wondrous city." },
        ["text"] = "Свої пожитки можеш залишити на зберігання в банку Дарнаса, що стоїть у центрі нашого дивовижного міста.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [246063512] = {
        ["english"] = { [1] = "You can't teach an old dog new tricks.  At least that's what someone once told me.  Lucky for you, I've discovered it to be untrue.$b$bHowever, pets do tend to get resistant to the technique, and I need more food each time to keep them happy.  What that means is that you'll owe me more money the more times I untrain the same pet.$b$bNow then, would you like me to start untraining?" },
        ["text"] = "Старого пса нових трюків не навчиш. Принаймні так мені колись казали. На щастя для тебе, я з'ясував, що це неправда.$b$bУтім, вихованці поступово звикають до цієї процедури, і щоразу мені потрібно більше їжі, щоб вони лишалися задоволені. Тобто що частіше я розучуватиму того самого вихованця, то дорожче це тобі коштуватиме.$b$bНу що, починати розучування?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1773819898] = {
        ["english"] = { [1] = "You will find Pyall Silentstride inside the great tent in the northwest corner of the village.  He can teach you what you crave." },
        ["text"] = "Пайалла Тихоступа знайдеш у великому наметі в північно-західному кутку селища. Він навчить тебе того, чого прагнеш.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [3196227744] = {
        ["english"] = { [1] = "You know, I could run an orc through or slice up a troll.  I could even carve my initials in an ogre's flank, but I just can't stand to skin an animal.  Go figure, eh.  \010\010Well, if you have the stomach for it, then go see Maris Granger at the Protective Hide in Old Town." },
        ["text"] = "Знаєш, я міг би проштрикнути орка чи порізати троля. Навіть вирізати свої ініціали на боці огра. Але здирати шкуру з тварини — терпіти не можу. Дивина, еге ж?\010\010Ну, якщо шлунок у тебе міцний, іди до Маріс Ґрейнджер у «Захисну Шкуру» в Старому місті.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1892425498] = {
        ["english"] = { [1] = "Zug zug, brave $c!  I have the finest bred wolf mounts for you to peruse.  You'll not find another animal with the level of endurance and survival instincts that the wolf has anywhere!  Please, inspect them for yourself." },
        ["text"] = "Зуґ-зуґ, хоробрий $c! Для тебе в мене найкращі породисті вовки. Ніде не знайдеш іншої тварини з такою витривалістю й інстинктами виживання, як у вовка! Оглянь їх сам.",
        ["npcs"] = { [1] = 3362 },
        ["roles"] = { ["greeting"] = true },
    },
    [251706388] = {
        ["english"] = { [1] = "You need to be exalted with the Forsaken of the Undercity before I will teach you a riding skill, $c." },
        ["text"] = "Ти маєш бути звеличеним серед Відречених Підміста, перш ніж я навчу тебе верхової їзди, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3540879518] = {
        ["english"] = { [1] = "Your skills are insufficient to learn what I teach. Try talking to Mak over there instead. He can help you out until you're ready for more advanced lessons." },
        ["text"] = "Твоїх умінь недостатньо, щоб вивчати те, чого я навчаю. Краще поговори з Маком он там. Він допоможе, доки ти не будеш готовий до складніших уроків.",
        ["npcs"] = { [1] = 11084 },
        ["roles"] = { ["greeting"] = true },
    },
    [1809641274] = {
        ["english"] = { [1] = "You looking for plucky?  Well, you didn't hear me say this, but... maybe if you ask Kronkrider up in the tower, he'll tell you..." },
        ["text"] = "Шукаєш Плакі? Ну, ти не від мене це чув, але... може, якщо спитаєш Кронкрайдера у вежі, він тобі скаже...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2733893131] = {
        ["english"] = { [1] = "You want to train? With me? Fantastic! The only thing better than assembling bullets and explosive devices is to share that knowledge with someone else! Let's get started!" },
        ["text"] = "Хочеш тренуватися? Зі мною? Чудово! Єдине, що краще за складання куль і вибухових пристроїв, — ділитися цими знаннями з кимось іншим! Починаймо!",
        ["npcs"] = { [1] = 11037 },
        ["roles"] = { ["greeting"] = true },
    },
    [4069866685] = {
        ["english"] = { [1] = "Yes?  What is it?" },
        ["text"] = "Так? Що таке?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4182080580] = {
        ["english"] = { [1] = "Your skills have surpassed mine, young one. Go see Una who has a shop in Thunder Bluff's central plateau. She can give you the guidance you seek." },
        ["text"] = "Твої навички перевершили мої, юначе. Іди до Уни, в неї крамниця на центральному плато Громового Бескиду. Вона дасть тобі потрібні настанови.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4138379044] = {
        ["english"] = { [1] = "You no make dis your home. Maybe you want eat someting?" },
        ["text"] = "Ти не робити це своїм домом. Може, хочеш щось їсти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4080852686] = {
        ["english"] = { [1] = "You have great potential, but you must achieve understanding first, you must accept the spirits and listen to their calling. Only then will you be prepared for the path you must follow. Go speak with Thrag, I think perhaps you can learn a lot from one another." },
        ["text"] = "У тобі великий потенціал, але спершу треба досягти розуміння: прийняти духів і дослухатися до їхнього поклику. Лише тоді ти будеш готовий до шляху, яким маєш іти. Поговори з Траґом — думаю, ви багато чому навчитеся один від одного.",
        ["npcs"] = { [1] = 2998 },
        ["roles"] = { ["greeting"] = true },
    },
    [2594345715] = {
        ["english"] = { [1] = "Yep." },
        ["text"] = "Так.",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["greeting"] = true },
    },
    [2691722017] = {
        ["english"] = { [1] = "You seek the scepter shard charged to the protection of the Blue Flight?$B$B<Azuregos appears to be smiling.>" },
        ["text"] = "Ти шукаєш уламок скіпетра, доручений захисту Синьої зграї?$B$B<Азуреґос, схоже, усміхається.>",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [611381956] = {
        ["english"] = { [1] = "You couldn't handle a lone night elf priestess?" },
        ["text"] = "Ти не впорався з однією-єдиною жрицею нічних ельфів?",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["reply"] = true },
    },
    [3307719426] = {
        ["english"] = { [1] = "You said you would have it back. What does that mean?" },
        ["text"] = "Ти казав, що повернеш це. Що це означає?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2288256962] = {
        ["english"] = { [1] = "You're here to help with the heavy leather for the Ahn'Qiraj war effort, are you, $c? Good, good. As you can see I've collected $2066w, but we're going to need $2067w in total. That's a lot of skinning my friend, so I hope that your knife is sharp. The leather will go to all sorts of uses for making our war materiel and ensuring our success." },
        ["text"] = "Ти тут, щоб допомогти з грубою шкірою для воєнних потреб Ан'Кіражу, $c? Добре, добре. Як бачиш, я вже зібрав $2066w, але загалом потрібно $2067w. Це багато роботи зі шкурництвом, друже, тож сподіваюся, твій ніж гострий. Шкіра піде на всілякі речі для наших військових припасів і допоможе забезпечити перемогу.",
        ["npcs"] = { [1] = 15515 },
        ["roles"] = { ["greeting"] = true },
    },
    [1027921987] = {
        ["english"] = { [1] = "You must find a way to show that you both are fighting for the same side. Although the Timbermaw may attack you now, if you are diligent, you will find a way.$B$BYou must remember that any attacks on the Timbermaw furbolg directly will greatly hinder your chances of gaining them as an ally.$B$BA good place to start would be the Deadwood furbolg found in many parts of Felwood. These furbolg are the enemy of the Timbermaw tribe, and slaying them would greatly improve your standing with the Timbermaw." },
        ["text"] = "Ти мусиш знайти спосіб показати, що ви воюєте на одному боці. Хоча фурболґи Деревопащі зараз можуть нападати на тебе, якщо будеш наполегливим, вихід знайдеться.$B$BПам'ятай: будь-які напади безпосередньо на фурболґів Деревопащі сильно зашкодять шансам зробити їх союзниками.$B$BДобре почати з фурболґів Мертвого Лісу, яких можна знайти в багатьох місцях Сквернолісся. Вони вороги племені Деревопащі, і їхнє винищення значно покращить твоє становище серед Деревопащі.",
        ["npcs"] = { [1] = 11554 },
        ["roles"] = { ["greeting"] = true },
    },
    [1956589118] = {
        ["english"] = { [1] = "You have a message for me?" },
        ["text"] = "У тебе для мене повідомлення?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [754656189] = {
        ["english"] = { [1] = "You've bagged them all: Bach'lor, Banthar, Gutripper, and even the mighty Tusker!  You're truly the finest big game hunter that I know!" },
        ["text"] = "Ти вполював усіх: Бах'лора, Бантара, Нутроріза й навіть могутнього Бивняра! Ти справді найкращий мисливець на велику дичину з усіх, кого я знаю!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1890793852] = {
        ["english"] = { [1] = "You mentioned two results when the Earthen destabilize.  What is the second?" },
        ["text"] = "Ти згадував два наслідки, коли земельники дестабілізуються. Який другий?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [81269510] = {
        ["english"] = { [1] = "Yes.", [2] = "Yes.\010" },
        ["text"] = "Так.",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["reply"] = true },
    },
    [3804876982] = {
        ["english"] = { [1] = "Your greatest challenge lies ahead.  Ley-Guardian Eregos is a Blue dragon of immense power. You will find him flying above the uppermost ring. $B$BThe full power of your drakes has been unlocked.  Use their power to defeat Eregos!" },
        ["text"] = "Найбільше випробування ще попереду. Лей-вартовий Ереґос — синій дракон неймовірної могутності. Знайдеш його в польоті над найвищим кільцем.$B$BПовну силу твоїх драконів розблоковано. Скористайся нею, щоб перемогти Ереґоса!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [201461785] = {
        ["english"] = { [1] = "You need something fixed? Use the Vend-O-Tron." },
        ["text"] = "Треба щось полагодити? Скористайся «Венд-о-троном».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1239642083] = {
        ["english"] = { [1] = "You!  $N!  What are you doing wandering around the village like this?  There are Alliance foes in Alterac!  We must drive them out!$B$BOur supplies are too low to launch a large ground assault, so speak with our quatermaster.  He'll tell you how you can increase our supply base." },
        ["text"] = "Ти! $N! Чого тиняєшся селом? В Альтераку вороги Альянсу! Ми мусимо їх вибити!$B$BЗапасів надто мало для великого наземного наступу, тож поговори з нашим інтендантом. Він скаже, як збільшити наші запаси.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3420288323] = {
        ["english"] = { [1] = "You've caught me at a critical time in my research!  No worries, you're welcome to join me in quiet contemplation... emphasis on \"quiet\", if you don't mind though.", [2] = "You've caught me at a critical time in my research! No worries, you're welcome to join me in quiet contemplation... emphasis on \"quiet\", if you don't mind though." },
        ["text"] = "Ти застав мене в критичний момент дослідження! Та нічого, можеш приєднатися до мене в тихому спогляданні... наголос на слові «тихому», якщо не заперечуєш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1990694928] = {
        ["english"] = { [1] = "You are truly a determined student. I will be happy to provide you with instruction!" },
        ["text"] = "Ти справді наполегливий учень. Із радістю навчатиму тебе!",
        ["npcs"] = { [1] = 3004 },
        ["roles"] = { ["greeting"] = true },
    },
    [3591961024] = {
        ["english"] = { [1] = "Yer looking for an Alchemy trainer are ye?  Just came from there, I did.  Ye'll find Ms. Berryfizz over in Tinker Town where the gnomes gather.  \010\010::sigh:: ...why o' why didn't I take the blue potion." },
        ["text"] = "Шукаєш учителя алхімії, еге ж? Я саме звідти. Пані Берріфіз знайдеш у Місті Механіків, там, де збираються гноми.\010\010::зітхання:: ...і чому, ну чому я не випив синє зілля.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [130832849] = {
        ["english"] = { [1] = "You can find Radnaal practicing his craft outside his home on the road to Darnassus.  You should stop by and see what he can teach you." },
        ["text"] = "Раднаала знайдеш за ремеслом біля його дому на дорозі до Дарнаса. Варто зазирнути й подивитися, чого він може тебе навчити.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [3549910616] = {
        ["english"] = { [1] = "You'll find Elder Starglade outside the gates to Zul'Gurub in Stranglethorn Vale." },
        ["text"] = "Старійшину Зоряної Галявини знайдеш біля брам Зул'Ґуруба в Тернистій долині.",
        ["npcs"] = { [1] = 15576, [2] = 15593 },
        ["roles"] = { ["greeting"] = true },
    },
    [1031931153] = {
        ["english"] = { [1] = "Your talents excel! You are truly inspired. To continue your pursuit of knowledge, speak with Georgio Bolero in Stormwind. He is held in high regard, and will be able to further your instruction." },
        ["text"] = "Твої таланти розквітають! Ти справді натхненний. Щоб продовжити шлях знань, поговори з Джорджіо Болеро в Штормовії. Його дуже поважають, і він зможе навчати тебе далі.",
        ["npcs"] = { [1] = 4159 },
        ["roles"] = { ["greeting"] = true },
    },
    [2621028666] = {
        ["english"] = { [1] = "You have worked your way up, time to see the boss. Go to Josef and tell him you are ready." },
        ["text"] = "Ти вже піднявся достатньо — час до начальства. Іди до Йозефа й скажи, що готовий.",
        ["npcs"] = { [1] = 11049 },
        ["roles"] = { ["greeting"] = true },
    },
    [591076470] = {
        ["english"] = { [1] = "You having a good time here with us in Ogri'la?$B$BWe have a lot of stuff that our ogres are making, day and night.  We save the best to sell to our coolest guests like you!$B$BSo, as you're out there doing your thing, and making the mountains a safer place, stop by from time to time to see what we have.$B$BGood luck out there, $g man : chicky;." },
        ["text"] = "Подобається в нас в Оґрілі?$B$BНаші огри день і ніч роблять купу всякого. Найкраще ми бережемо для найкрутіших гостей — таких, як ти!$B$BТож коли там, назовні, займаєшся своїми справами й робиш гори безпечнішими, час від часу зазирай до нас, подивишся, що маємо.$B$BУдачі там, $g хлопче : дівчино;.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2900583881] = {
        ["english"] = { [1] = "Your next choice awaits.$B$BYou alone have defeated a terrible beast that has been ravaging the countryside, taking its ear as a trophy.  You later learn that your liege had offered a reward for the beast's death, and that a kind but destitute knight who you know is trying to support a family by meager means claims the beast's kill as his own.  You have no real need for money yourself, but you know that the destitute knight is lying for his own personal gain.$B$BMake your choice.\010\010" },
        ["text"] = "На тебе чекає наступний вибір.$B$BТи самотужки переміг жахливого звіра, що спустошував околиці, й узяв його вухо як трофей. Згодом ти дізнаєшся, що твій сюзерен призначив нагороду за смерть звіра, а добрий, але злиденний лицар, якого ти знаєш і який ледве утримує сім'ю, приписав перемогу собі. Тобі самому гроші не надто потрібні, але ти знаєш, що злиденний лицар бреше заради власної вигоди.$B$BЗроби свій вибір.\010\010",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["greeting"] = true },
    },
    [1816423827] = {
        ["english"] = { [1] = "You have come to learn of battles won and lost on this field? There are no winners here..." },
        ["text"] = "Ти прийшов дізнатися про битви, виграні й програні на цьому полі? Тут немає переможців...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3774921525] = {
        ["english"] = { [1] = "Yes $g sir : ma'am;! I've been ordered to report that the Alliance has collected all war materiel necessary. It has been relayed to me that we are simply waiting on the Horde to finish their part and then everything will be shipped to Silithus. Thank you $g sir : ma'am;!" },
        ["text"] = "Так, $g пане : пані;! Мені наказано доповісти, що Альянс зібрав усі необхідні військові припаси. Мені передали, що тепер ми лише чекаємо, доки Орда завершить свою частину, після чого все буде відправлено до Силітуса. Дякую, $g пане : пані;!",
        ["npcs"] = { [1] = 15448 },
        ["roles"] = { ["greeting"] = true },
    },
    [846030583] = {
        ["english"] = { [1] = "You need to learn from someone who knows more than I do. Go talk to Josef Gregorian in Undercity. Well, what are you still doing here?" },
        ["text"] = "Тобі треба вчитися в того, хто знає більше за мене. Поговори з Йозефом Ґреґоріаном у Підмісті. Ну, чого ти ще тут стоїш?",
        ["npcs"] = { [1] = 2627, [2] = 3363 },
        ["roles"] = { ["greeting"] = true },
    },
    [2132476616] = {
        ["english"] = { [1] = "Yes, $N. The elements are stirring. Soon, we will unleash their might upon our enemies. They shall reel from the blows!" },
        ["text"] = "Так, $N. Стихії пробуджуються. Незабаром ми обрушимо їхню міць на наших ворогів. Вони захитаються від ударів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1912929564] = {
        ["english"] = { [1] = "You freed Kirith from his suffering? Inconceivable -- and now Trebor has sent you here to learn of demons and their minions?$B$B<Loramus laughs.>$B$BBe thankful the arcane pangs have finally dissipated, $r." },
        ["text"] = "Ти звільнив Кіріта від страждань? Немислимо — а тепер Требор прислав тебе сюди вивчати демонів та їхніх прислужників?$B$B<Лорамус сміється.>$B$BРадій, що арканічні муки нарешті минули, $r.",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["greeting"] = true },
    },
    [816743123] = {
        ["english"] = { [1] = "You da strong one now!  All hail to da new king of da Gordok!" },
        ["text"] = "Ти тепер найсильніший! Слава новому королю Ґордока!",
        ["npcs"] = { [1] = 14325 },
        ["roles"] = { ["greeting"] = true },
    },
    [1021891452] = {
        ["english"] = { [1] = "You have shown me your desire, and have payed with precious stone.  I will teach you..." },
        ["text"] = "Ти показав своє прагнення й заплатив дорогоцінним каменем. Я навчу тебе...",
        ["npcs"] = { [1] = 3442, [2] = 9037 },
        ["roles"] = { ["greeting"] = true },
    },
    [1587315829] = {
        ["english"] = { [1] = "You know about the Violet Eye then?  Maybe I'll have time for you later.$B$BI have to get back to my work." },
        ["text"] = "То ти знаєш про Фіолетове Око? Може, пізніше матиму на тебе час.$B$BА зараз мені треба повертатися до роботи.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [52343204] = {
        ["english"] = { [1] = "You want what?! I've heard something about one of those odd draenei creatures in the Valley of Heroes. Maybe she knows; I don't." },
        ["text"] = "Ти хочеш що?! Чув щось про одну з тих дивних дренейських істот у Долині Героїв. Може, вона знає; я — ні.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [1820500498] = {
        ["english"] = { [1] = "You'll find no finer rat kabob this side of Khaz Modan!" },
        ["text"] = "Кращого шашлику з пацюка по цей бік Каз-Модана не знайдеш!",
        ["npcs"] = { [1] = 13018 },
        ["roles"] = { ["greeting"] = true },
    },
    [3539882175] = {
        ["english"] = { [1] = "You don't look like a student..." },
        ["text"] = "На учня ти не схожий...",
        ["npcs"] = { [1] = 10433 },
        ["roles"] = { ["greeting"] = true },
    },
    [1595203165] = {
        ["english"] = { [1] = "You are beyond my level of expertise. Georgio Bolero, the master of Duncan's Textiles around the corner could help you advance your skills." },
        ["text"] = "Твої навички вже перевищили мій рівень. Джорджіо Болеро, майстер «Тканин Дункана» за рогом, допоможе тобі розвинути їх далі.",
        ["npcs"] = { [1] = 5567 },
        ["roles"] = { ["greeting"] = true },
    },
    [1558082588] = {
        ["english"] = { [1] = "You come in search of training, hunter?" },
        ["text"] = "Прийшов по навчання, мисливцю?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3990392964] = {
        ["english"] = { [1] = "Zanza can create the ancient troll enchantments with the right components. This magic will help you in defeating Hakkar and his minions.$B$BI only ask that you bring me two items." },
        ["text"] = "Занза може створити прадавні трольські зачарування, якщо матиме потрібні складники. Ця магія допоможе тобі перемогти Гаккара та його прислужників.$B$BЯ прошу принести лише два предмети.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3920536391] = {
        ["english"] = { [1] = "You, $c! We require your aid! The brutish Warsong orcs are destroying the wonder and beauty of Ashenvale, and we need your strength to meet them on the field of battle. Return with us to Azeroth and fight for the honor of the Silverwing Sentinels! Will you join us?" },
        ["text"] = "Ти, $c! Нам потрібна твоя допомога! Грубі орки Пісні Війни нищать красу й диво Ясенедолу, і нам потрібна твоя сила на полі бою. Повертайся з нами до Азероту й бийся за честь Вартових Срібного Крила! Приєднаєшся?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3605258022] = {
        ["english"] = { [1] = "You are astute to ask, young $c.  Scribes are capable of inscribing tarot cards of great power, although even they do not have full control of what they make.  The fates decide for them.$b$bIf you manage to obtain a completed deck, please bring it to me for a magnificent reward." },
        ["text"] = "Мудро, що питаєш, юний $c. Писарі здатні створювати карти таро величезної сили, хоча навіть вони не мають повного контролю над тим, що вийде. За них вирішує доля.$b$bЯкщо тобі вдасться зібрати повну колоду, принеси її мені — і отримаєш чудову винагороду.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [661037426] = {
        ["english"] = { [1] = "You are welcome among us, $c.  At least for the time being." },
        ["text"] = "Ласкаво просимо до нас, $c. Принаймні поки що.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1477205242] = {
        ["english"] = { [1] = "You expect me to remember all that off the top of my head? Look. They didn't pay me enough to put up with this, and the contract only asked for my silence. So I'm just gonna drop my ledger on the floor here, and you're going to take it and leave me alone.$b$bGot it?" },
        ["text"] = "Ти серйозно думаєш, що я все це пам'ятаю напам'ять? Послухай. Мені недостатньо платили, щоб терпіти таке, а контракт вимагав лише мовчати. Тож я просто кину бухгалтерську книгу на підлогу, а ти її підбереш і залишиш мене в спокої.$b$bЗрозуміло?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2547083197] = {
        ["english"] = { [1] = "You may speak frankly, Neeru..." },
        ["text"] = "Можеш говорити відверто, Ніру...",
        ["npcs"] = { [1] = 3216 },
        ["roles"] = { ["reply"] = true },
    },
    [151479086] = {
        ["english"] = { [1] = "You've impressed everyone here today with your skills in the arena.  It is now time to be recognized before all as a champion of the tournament." },
        ["text"] = "Сьогодні ти вразив усіх своїми вміннями на арені. Настав час, щоб усі визнали тебе чемпіоном турніру.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [681505618] = {
        ["english"] = { [1] = "You made it $g lad:lass;! I thought you were a goner for sure!" },
        ["text"] = "Ти дістався, $g хлопче:дівчино;! Я вже думав, тобі кінець!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [590741990] = {
        ["english"] = { [1] = "You are da king of the Gordok!  You're A-number-one!" },
        ["text"] = "Ти король Ґордока! Ти най-най-най!",
        ["npcs"] = { [1] = 14326 },
        ["roles"] = { ["greeting"] = true },
    },
    [3542637137] = {
        ["english"] = { [1] = "Your next choice awaits.$B$BYour brother seeks to join the ranks of the prestigious military order you are already a part of.  While you are sure of his commitment and loyalty, his talent and ability to perform the arduous tasks of the order is what you question.  While you are not certain he will be able to rise to the challenge of the order - putting you and others in danger - you are certain that your word alone would allow him in or keep him out.$B$BMake your choice.\010\010" },
        ["text"] = "На тебе чекає наступний вибір.$B$BТвій брат прагне вступити до престижного військового ордену, членом якого ти вже є. У його відданості й вірності ти не сумніваєшся, але сумніваєшся в таланті та здатності виконувати важкі завдання ордену. Ти не певен, що він витримає випробування — і може наразити на небезпеку тебе та інших, — але точно знаєш, що одного твого слова вистачить, щоб прийняти його або відмовити.$B$BЗроби свій вибір.\010\010",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["greeting"] = true },
    },
    [815748798] = {
        ["english"] = { [1] = "You seek a rogue?  I believe Jannok would fit that description.  Why don't you go talk to him over at the Inn in Dolanaar." },
        ["text"] = "Шукаєш розбійника? Думаю, Яннок підходить під опис. Поговори з ним у заїзді Доланаара.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [1199904737] = {
        ["english"] = { [1] = "You seek Grol'dar and the Darkfire Enclave?  Find them in the underground cavern called the Cleft of Shadow.  There are two tunnels leading down into that cave, one just south of the Valley of Wisdom and the other from The Drag." },
        ["text"] = "Шукаєш Ґрол'дара й Анклав Темного Вогню? Знайдеш їх у підземній печері, що зветься Розколиною Тіні. До неї ведуть два тунелі: один просто на південь від Долини Мудрості, другий — з Хитрого провулка.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1625042058] = {
        ["english"] = { [1] = "You are talking nonsense, mage. " },
        ["text"] = "Ти верзеш нісенітниці, магу.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2469449788] = {
        ["english"] = { [1] = "You da man now, dog!" },
        ["text"] = "Ти тепер крутий, друже!",
        ["npcs"] = { [1] = 14321 },
        ["roles"] = { ["greeting"] = true },
    },
    [3622670529] = {
        ["english"] = { [1] = "You have not yet learned the basics, wanderer. Have you spoken to my assistant, Lalina Summermoon? Perhaps you should." },
        ["text"] = "Ти ще не опанував основ, мандрівнику. Ти говорив із моєю помічницею Лаліною Літній Місяць? Мабуть, варто.",
        ["npcs"] = { [1] = 4213 },
        ["roles"] = { ["greeting"] = true },
    },
    [2889497684] = {
        ["english"] = { [1] = "You seek to harm me, $r?" },
        ["text"] = "Ти хочеш завдати мені шкоди, $r?",
        ["npcs"] = { [1] = 6109 },
        ["roles"] = { ["greeting"] = true },
    },
    [3091573945] = {
        ["english"] = { [1] = "You should be sticking close to Arthas right now!" },
        ["text"] = "Тобі зараз варто триматися ближче до Артаса!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1769201181] = {
        ["english"] = { [1] = "You go to Royal Quarter. They all there, in circle around room." },
        ["text"] = "Іди до Королівського кварталу. Вони всі там, колом у кімнаті.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2591811855] = {
        ["english"] = { [1] = "You can understand me? I can understand you!" },
        ["text"] = "Ти мене розумієш? І я тебе розумію!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [294993743] = {
        ["english"] = { [1] = "Your path does not match mine. You must seek training elsewhere, $c." },
        ["text"] = "Твій шлях не збігається з моїм. Шукай навчання деінде, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3134489835] = {
        ["english"] = { [1] = "Your skills are beyond my reach. It is time for you to face new challenges. Taladan will help you prepare. He is standing by the table there." },
        ["text"] = "Твої вміння вже поза межами моїх знань. Час прийняти нові виклики. Таладан допоможе підготуватися. Він стоїть он біля столу.",
        ["npcs"] = { [1] = 11070 },
        ["roles"] = { ["greeting"] = true },
    },
    [1667247995] = {
        ["english"] = { [1] = "You have wrested control of the Oculus from the forces of Malygos.  The Red Flight is in your debt." },
        ["text"] = "Ти вирвав Окулус із рук сил Маліґоса. Червона зграя в боргу перед тобою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3225964456] = {
        ["english"] = { [1] = "You've come further than many, $N. Respect the elements around you and you shall fare far greater than most." },
        ["text"] = "Ти зайшов далі за багатьох, $N. Шануй стихії навколо себе — і досягнеш значно більшого, ніж більшість.",
        ["npcs"] = { [1] = 5901 },
        ["roles"] = { ["greeting"] = true },
    },
    [4249099494] = {
        ["english"] = { [1] = "You've got something I need, Astor. And I'll be taking it now." },
        ["text"] = "У тебе є те, що мені потрібно, Асторе. І зараз я це заберу.",
        ["npcs"] = { [1] = 6497 },
        ["roles"] = { ["reply"] = true },
    },
    [3004233302] = {
        ["english"] = { [1] = "You waste my time, go talk with my student Basil." },
        ["text"] = "Ти марнуєш мій час. Іди поговори з моїм учнем Базилем.",
        ["npcs"] = { [1] = 4596 },
        ["roles"] = { ["greeting"] = true },
    },
    [2876984380] = {
        ["english"] = { [1] = "You a new recruit? That's not standard issue armor." },
        ["text"] = "Ти новобранець? Це не стандартний обладунок.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2260329189] = {
        ["english"] = { [1] = "You do fine work, but it's a bit rough around the edges. Don't worry about it, it will come with practice. Speaking of which, how about we see what you've been working on?" },
        ["text"] = "Робота в тебе добра, але ще трохи грубувата по краях. Не переймайся, з практикою мине. До речі, чому б нам не поглянути, над чим ти працював?",
        ["npcs"] = { [1] = 3136 },
        ["roles"] = { ["greeting"] = true },
    },
    [2815066286] = {
        ["english"] = { [1] = "You have passed your test, well done! Your training may now continue." },
        ["text"] = "Ти пройшов випробування, молодець! Тепер навчання можна продовжити.",
        ["npcs"] = { [1] = 3412 },
        ["roles"] = { ["greeting"] = true },
    },
    [3702960726] = {
        ["english"] = { [1] = "You look like you've had your heart broken. Come back when you're not so sad." },
        ["text"] = "Схоже, тобі розбили серце. Повернися, коли не будеш таким сумним.",
