 14440, [435] = 14441, [436] = 14442, [437] = 14497, [438] = 16002, [439] = 16004, [440] = 16009, [441] = 16105, [442] = 16106, [443] = 16108, [444] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [3375541394] = {
        ["english"] = { [1] = "Your knowledge is lacking.  Return to me when your skills in smelting have grown!" },
        ["text"] = "Твоїх знань бракує. Повернися, коли краще опануєш плавлення металів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2542275160] = {
        ["english"] = { [1] = "Your education is progressing well. You should be proud of your accomplishments." },
        ["text"] = "Твоє навчання просувається добре. Ти маєш пишатися своїми досягненнями.",
        ["npcs"] = { [1] = 4160 },
        ["roles"] = { ["greeting"] = true },
    },
    [2441663111] = {
        ["english"] = { [1] = "You'll find one of those outside the Bank of Orgrimmar in the middle of the Valley of Strength." },
        ["text"] = "Одну таку знайдеш біля Банку Орґріммара посеред Долини Сили.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1374733447] = {
        ["english"] = { [1] = "You certainly did not disappoint! Now that we've gotten that out of the way, your instruction may begin!" },
        ["text"] = "Ти точно не розчарував! Тепер, коли з цим покінчено, можемо починати навчання!",
        ["npcs"] = { [1] = 5518 },
        ["roles"] = { ["greeting"] = true },
    },
    [363809963] = {
        ["english"] = { [1] = "You have advanced beyond my skill to teach you. Journey now to Aerie Peak in the Hinterlands and speak with the dwarf Drakk Stonehand. His work is magnificent, far better than my own." },
        ["text"] = "Ти вже перевершив усе, чого я можу тебе навчити. Тепер вирушай до Орлиного піку у Внутрішніх землях і поговори з дворфом Дракком Каменеруком. Його робота чудова, значно краща за мою.",
        ["npcs"] = { [1] = 4212 },
        ["roles"] = { ["greeting"] = true },
    },
    [3044617269] = {
        ["english"] = { [1] = "You be watchin' yerself, $c. Respect our ways, or a curse be on you and yours." },
        ["text"] = "Гляди себе, $c. Шануй наші звичаї, інакше прокляття впаде на тебе й твоїх близьких.",
        ["npcs"] = { [1] = 3706, [2] = 3707, [3] = 5994, [4] = 6014, [5] = 6018 },
        ["roles"] = { ["greeting"] = true },
    },
    [489526435] = {
        ["english"] = { [1] = "You must choose a more experienced teacher, for you have surpassed my abilities. I advise you to speak with Lilyssia Nightbreeze here: she has much knowledge to offer." },
        ["text"] = "Тобі потрібен досвідченіший наставник, бо мої вміння ти вже перевершив. Раджу поговорити з Ліліссією Нічним Вітром, вона тут і має багато знань, якими може поділитися.",
        ["npcs"] = { [1] = 5500 },
        ["roles"] = { ["greeting"] = true },
    },
    [3626729846] = {
        ["english"] = { [1] = "You are unfit to train with me, stranger. Spend some time with my assistant Jhag over there." },
        ["text"] = "Ти ще не годишся для тренувань зі мною, чужинцю. Попрацюй трохи з моїм помічником Джаґом, он там.",
        ["npcs"] = { [1] = 3345 },
        ["roles"] = { ["greeting"] = true },
    },
    [527877684] = {
        ["english"] = { [1] = "You do not have enough reputation with or have not pledged allegiance to The Scryers." },
        ["text"] = "Твоя репутація серед Провидців недостатня або ти не присягнув їм на вірність.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1912769050] = {
        ["english"] = { [1] = "You da boss now, yeah?  Long live da new king!$B$BKreeg let you look at Gordok hooch.  Ogre hooch best of all hooch, and Gordok hooch best of all ogre hooch!  Maybe you buy some from me, ya boss?!" },
        ["text"] = "Ти тепер бос, так? Хай живе новий король!$B$BКріґ дозволити тобі дивитися ґордокську бормотуху. Огряча бормотуха найкраща з усієї бормотухи, а ґордокська — найкраща з огрячої! Може, купиш у мене трохи, га, бос?!",
        ["npcs"] = { [1] = 14322 },
        ["roles"] = { ["greeting"] = true },
    },
    [174703304] = {
        ["english"] = { [1] = "You want Zamja at Borstan's Firepit on the upper level of The Drag.  Go up the stairs on the left as you enter The Drag from the Valley of Strength." },
        ["text"] = "Тобі потрібна Замджа біля Вогнища Борстана на верхньому рівні Хитрого провулка. Коли входиш із Долини Сили, піднімися сходами ліворуч.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [342978623] = {
        ["english"] = { [1] = "Yes? What is it?$B$BTime waits for no one!" },
        ["text"] = "Так? Що таке?$B$BЧас нікого не чекає!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4256199149] = {
        ["english"] = { [1] = "You show wisdom beyond your years $c.  Thank you.  You can find our battlemaster, Lylandris, standing at the war table in the Hall of Arms.  She can assist you in traveling to Warsong Gulch." },
        ["text"] = "Ти виявляєш мудрість не за роками, $c. Дякую. Нашу розпорядницю бою Ліандріс знайдеш біля військового столу в Залі Зброї. Вона допоможе тобі дістатися до Ущелини Пісні Війни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2149668241] = {
        ["english"] = { [1] = "You have fought well, spirit.  I ask you to grant me the strength of your body and the stength of your heart." },
        ["text"] = "Ти добре бився, духу. Прошу, даруй мені силу свого тіла й силу свого серця.",
        ["npcs"] = { [1] = 12144 },
        ["roles"] = { ["reply"] = true },
    },
    [4144226687] = {
        ["english"] = { [1] = "Yes, I've been running this shop for some time now. Business has been pretty good lately. A lot of new adventurers coming through..." },
        ["text"] = "Так, я вже певний час тримаю цю крамницю. Останнім часом справи йдуть непогано. Багато нових шукачів пригод проходить повз...",
        ["npcs"] = { [1] = 1346 },
        ["roles"] = { ["greeting"] = true },
    },
    [2695730302] = {
        ["english"] = { [1] = "You wouldn't believe some of the rabble that we've had come through here lately. Most are more trouble than the supposed help that they provide. Nothing at all like you.$B$BYou sure you don't want to sign up with the Farstriders?" },
        ["text"] = "Ти б не повірив, який набрід останнім часом сюди приходить. Від більшості більше клопоту, ніж тієї нібито допомоги, яку вони надають. З тобою зовсім не так.$B$BТочно не хочеш приєднатися до Далекоходців?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3202525529] = {
        ["english"] = { [1] = "You can find a mailbox just outside the Thunder Bluff Bank on the lower rise." },
        ["text"] = "Поштову скриньку знайдеш просто біля Банку Громового Бескиду на нижньому уступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [1885434514] = {
        ["english"] = { [1] = "You've dealt the decisive blow against the Shadowpine trolls, $N. I only hope that we can muster our forces quickly enough to finish them off before they receive reinforcements from Zul'Aman.$B$BIt would be nice if Tranquillien were to reinforce us." },
        ["text"] = "Ти завдав вирішального удару тролям Тіньової Сосни, $N. Сподіваюся лише, що ми встигнемо швидко зібрати сили й добити їх до того, як прибуде підкріплення із Зул'Амана.$B$BБуло б добре, якби Транквілієн надіслав нам підмогу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1947960277] = {
        ["english"] = { [1] = "You have truly accelled in your knowledge of enchanting. There is much more to learn, if you are willing. Speak to Taladan, in the Craftsmen's Terrace in Darnassus." },
        ["text"] = "Ти справді досяг великих успіхів у зачаруванні. Якщо хочеш, є ще багато чого вивчити. Поговори з Таладаном на Ремісничій терасі в Дарнасі.",
        ["npcs"] = { [1] = 3606 },
        ["roles"] = { ["greeting"] = true },
    },
    [3625523759] = {
        ["english"] = { [1] = "Your knowledge of potions has exceeded mine, but you still have much to learn. Go up the stairs to the southeast and see Doctor Marsh. He will teach you true sufferi--ahem. He is a Forsaken who will train you further." },
        ["text"] = "Твої знання про зілля вже перевершили мої, але вчитися ще є чого. Піднімися сходами на південний схід і знайди доктора Марша. Він навчить тебе справжніх стражда... кхм. Він Відречений і продовжить твоє навчання.",
        ["npcs"] = { [1] = 11044 },
        ["roles"] = { ["greeting"] = true },
    },
    [3652478787] = {
        ["english"] = { [1] = "You need go to The Apothecarium on inner ring.  That where Martha Alliestar teach you how to pick flowers." },
        ["text"] = "Тобі треба до Аптекаріуму на внутрішньому кільці. Там Марта Аллістар учить збирати квіти.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3468534182] = {
        ["english"] = { [1] = "You have to be careful lighting fireworks when you can't feel your fingers..." },
        ["text"] = "Треба бути обережним із феєрверками, коли не відчуваєш пальців...",
        ["npcs"] = { [1] = 15907 },
        ["roles"] = { ["greeting"] = true },
    },
    [468711495] = {
        ["english"] = { [1] = "Yes I checked, I'm missing the left piece!" },
        ["text"] = "Так, я перевірив — у мене бракує лівої частини!",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["reply"] = true },
    },
    [2882176169] = {
        ["english"] = { [1] = "You seek Kardris Dreamseeker.  She and the other shaman are in the entrance room to Thrall's Fortress in the Valley of Wisdom." },
        ["text"] = "Шукаєш Кардріс Сношукачу. Вона та інші шамани перебувають у вхідній залі фортеці Тралла в Долині Мудрості.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1320840837] = {
        ["english"] = { [1] = "You are quite inquisitive, though such inquisitiveness belies a general lack of understanding.  I say this because were you to have a definite purpose in being here, the question you ask would seem pointless. $B$BWith that, I bid you good day." },
        ["text"] = "Ти дуже допитливий, але ця допитливість радше видає загальне нерозуміння. Кажу це тому, що якби ти мав чітку мету перебування тут, твоє запитання не мало б сенсу.$B$BНа цьому бажаю тобі доброго дня.",
        ["npcs"] = { [1] = 5353 },
        ["roles"] = { ["greeting"] = true },
    },
    [83174522] = {
        ["english"] = { [1] = "Yes, my $g son : daughter;?" },
        ["text"] = "Так, $g мій синку : моя доню;?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2593553098] = {
        ["english"] = { [1] = "You are eager, that is good. However, you are not yet ready to train with the likes of me." },
        ["text"] = "Запалу тобі не бракує, і це добре. Але ти ще не готовий тренуватися з такими, як я.",
        ["npcs"] = { [1] = 11072 },
        ["roles"] = { ["greeting"] = true },
    },
    [1765062231] = {
        ["english"] = { [1] = "You have the look of a $g man : woman; who seeks knowledge. Perhaps you seek the teachings of the forge, and the hammer. Perhaps I can guide you down that path. But only once you have accepted the spirits, and listened to their calling." },
        ["text"] = "У тебе вигляд $g чоловіка : жінки;, що шукає знань. Можливо, ти прагнеш науки горна й молота. Можливо, я зможу провести тебе цим шляхом. Але лише після того, як ти приймеш духів і почуєш їхній поклик.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2949306471] = {
        ["english"] = { [1] = "You want to punch things, yah? Talk to Sayoc right here. He teach you." },
        ["text"] = "Хочеш когось бити, так? Поговори із Сайоком, він тут. Він тебе навчити.",
        ["npcs"] = { [1] = 2704 },
        ["roles"] = { ["greeting"] = true },
    },
    [808678972] = {
        ["english"] = { [1] = "You are well on your way, $N.  But you still have much to learn.  The southern Barrens may be where your next lesson is found." },
        ["text"] = "Ти вже далеко просунувся, $N. Але вчитися ще є чого. Можливо, наступний урок чекає на тебе в південних Степах.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4251733809] = {
        ["english"] = { [1] = "You challenged us and we have come. Where is this master you speak of?" },
        ["text"] = "Ти кинув нам виклик, і ми прийшли. Де цей майстер, про якого ти говорив?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [4019042231] = {
        ["english"] = { [1] = "You have done a great thing, $N.  You are welcome here at any time." },
        ["text"] = "Ти зробив велику справу, $N. Тобі тут завжди раді.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1271254006] = {
        ["english"] = { [1] = "You have come a long way, traveler. There is one more task for you to perform..." },
        ["text"] = "Ти пройшов довгий шлях, мандрівнику. Залишилося виконати ще одне завдання...",
        ["npcs"] = { [1] = 11052 },
        ["roles"] = { ["greeting"] = true },
    },
    [1960486963] = {
        ["english"] = { [1] = "Zul'Farrak in Tanaris Desert is Elder Wildmane's home." },
        ["text"] = "Зул'Фаррак у пустелі Танаріс — домівка старійшини Дикої Гриви.",
        ["npcs"] = { [1] = 15573, [2] = 15583, [3] = 15584, [4] = 15586 },
        ["roles"] = { ["greeting"] = true },
    },
    [1041698952] = {
        ["english"] = { [1] = "You there!  You look able bodied... we need your aid in defending Southshore!$B$BThe blasted Forsaken are all riled up because it's Hallow's End.  Their \"celebration\" will no doubt be leading them right to our doorstep.  If you've got the time, we really could use your help!" },
        ["text"] = "Гей, ти! Виглядаєш міцним... нам потрібна допомога в обороні Південнобережжя!$B$BТі прокляті Відречені розійшлися через Кінець Покрову. Їхнє «святкування», без сумніву, приведе їх просто до наших дверей. Якщо маєш час, твоя допомога нам справді знадобиться!",
        ["npcs"] = { [1] = 15199 },
        ["roles"] = { ["greeting"] = true },
    },
    [1701799933] = {
        ["english"] = { [1] = "You'll find Greatfather Winter in the center of the Valley of Strength. Just look for the tree." },
        ["text"] = "Дідуся Зиму знайдеш у центрі Долини Сили. Просто шукай ялинку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2181138861] = {
        ["english"] = { [1] = "Yesh, it'sh true, I'm blind as a bat! An' drunk as a ... err, drunk as shomething that getsh drunk.$B$BI'll tell you what, $r. It'sh the drink that keeps me shenses sharp. It'sh common knowledge that when you lose a shense, yer other shenses become more alert. My drunk shense is incredible these days." },
        ["text"] = "Тааа, це правда, я сліпий як кажан! І п'яний як... е-е, як щось, що буває п'яним.$B$BСкажу тобі так, $r. Саме випивка тримає мої чуття гострими. Усі знають: коли втрачаєш одне чуття, решта стають гострішими. Моє п'яне чуття нині просто неймовірне.",
        ["npcs"] = { [1] = 14634 },
        ["roles"] = { ["greeting"] = true },
    },
    [1819476651] = {
        ["english"] = { [1] = "You need to start learning things that are beyond my expertise! Talk to Lilliam Sparkspindle in front of the tent there. He'll set you on the right course!" },
        ["text"] = "Тобі пора вчитися тому, що вже поза межами моїх знань! Поговори з Лілліамом Іскровертом перед наметом. Він направить тебе на правильний шлях!",
        ["npcs"] = { [1] = 11026 },
        ["roles"] = { ["greeting"] = true },
    },
    [2985199482] = {
        ["english"] = { [1] = "You wish to learn the old craft?  You wish to smelt dark iron?$B$BAppease me, $r.  Show me a sacrifice and I will consider it!" },
        ["text"] = "Хочеш опанувати старе ремесло? Хочеш плавити темне залізо?$B$BЗадобри мене, $r. Принеси жертву — і я подумаю!",
        ["npcs"] = { [1] = 9037 },
        ["roles"] = { ["greeting"] = true },
    },
    [3735404257] = {
        ["english"] = { [1] = "You'll find out soon enough. Are you ready for the next challenge?" },
        ["text"] = "Скоро дізнаєшся. Готовий до наступного випробування?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1622060168] = {
        ["english"] = { [1] = "You don't have the stomach for the gryphon ride, huh.  Well lucky for you, we have an alternative where you can keep your feet on the ground... more or less.  It's the gnomish mover of people, the Deeprun Tram.  Conveniently located in the back of the Dwarven District." },
        ["text"] = "Шлунок не витримує польоту на грифоні, еге ж? На щастя, є інший спосіб тримати ноги на землі... більш-менш. Це гномський перевізник людей — Глибокобіжний трамвай. Дуже зручно розташований у глибині Дворфівського району.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3967905561] = {
        ["english"] = { [1] = "Yes, you heard true, $c, all of our collections are complete and the last of the war materiel should arrive in Silithus within a day. I am told that once all is assembled there, and our troops readied, someone from within the ranks of you heroes is going to ring the gong outside of Ahn'Qiraj, already having assembled the Scepter of the Shifting Sands to do so with. I hope that we don't have to wait too long for that to happen." },
        ["text"] = "Так, ти чув правду, $c: усі наші збори завершено, а останні військові припаси мають прибути до Силітуса за день. Кажуть, коли все буде зібрано й війська підготуються, хтось із вас, героїв, ударить у гонг біля Ан'Кіражу, вже зібравши для цього Скіпетр Мінливих Пісків. Сподіваюся, чекати доведеться недовго.",
        ["npcs"] = { [1] = 15529 },
        ["roles"] = { ["greeting"] = true },
    },
    [1451014571] = {
        ["english"] = { [1] = "Years of quality breeding techniques and plenty of care allow me the privilege of showing you these horses!  Please, take your time as you consider them for your mount.  A horse is a companion for the ages, friend.  Don't sell yourself short - get your steed here today!" },
        ["text"] = "Роки добірного розведення та ретельного догляду дають мені честь показати тобі цих коней! Не поспішай, обираючи собі верхову тварину. Кінь — супутник на довгі роки, друже. Не погоджуйся на менше — обирай собі скакуна просто сьогодні!",
        ["npcs"] = { [1] = 384, [2] = 1460, [3] = 2357, [4] = 4885 },
        ["roles"] = { ["greeting"] = true },
    },
    [4251088333] = {
        ["english"] = { [1] = "Yes! I want more of that fabulous Noggenfogger Elixir!" },
        ["text"] = "Так! Хочу ще того чудового еліксиру Ноггенфоггера!",
        ["npcs"] = { [1] = 7564 },
        ["roles"] = { ["reply"] = true },
    },
    [1814817929] = {
        ["english"] = { [1] = "You can find a mailbox right o'er by The Stonefire Tavern.  It's just north of the gates of Ironforge." },
        ["text"] = "Поштову скриньку знайдеш біля таверни «Кам'яний вогонь». Вона просто на північ від брам Залізогарта.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [3023100621] = {
        ["english"] = { [1] = "You are certainly a long way from home, $r." },
        ["text"] = "Ти й справді далеко від дому, $r.",
        ["npcs"] = { [1] = 14463 },
        ["roles"] = { ["greeting"] = true },
    },
    [638128549] = {
        ["english"] = { [1] = "You have lost your mind, Nefarius. You speak in riddles." },
        ["text"] = "Ти збожеволів, Нефарію. Говориш загадками.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1899265560] = {
        ["english"] = { [1] = "You look safe enough... let's do this." },
        ["text"] = "Виглядаєш достатньо надійно... зробімо це.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [242714500] = {
        ["english"] = { [1] = "Yo. Lookin' to get back to the Old World? Fly to Tirisfal Glades in style on the Cloudkisser." },
        ["text"] = "Йо. Хочеш повернутися до Старого Світу? Лети до Тірісфальського узлісся зі шиком — на «Хмароцілуні».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3525207441] = {
        ["english"] = { [1] = "Yes, yes, all of the Horde's and Alliance's war materiel is being shipped over to Silithus and should be there within $2113w days. Do you know what happens then, $c? We hurry up and wait. Hopefully someone is gathering the pieces of the Scepter of the Shifting Sands, because in order to open the gates of Ahn'Qiraj it needs to be rung against the gong on the Scarab Dais." },
        ["text"] = "Так-так, усі військові припаси Орди й Альянсу вже везуть до Силітуса, і вони мають прибути туди за $2113w днів. Знаєш, що буде потім, $c? Будемо поспішати... щоб чекати. Сподіваюся, хтось уже збирає уламки Скіпетра Мінливих Пісків, бо щоб відкрити брами Ан'Кіражу, ним треба вдарити в гонг на Помості Скарабея.",
        ["npcs"] = { [1] = 15533 },
        ["roles"] = { ["greeting"] = true },
    },
    [1403794951] = {
        ["english"] = { [1] = "You look like you might be needing passage across the Great Sea. Well you have come to the right place, this here is the berth of the Maiden's Fancy, finest passanger ship to travel these waters. When she arrives just climb aboard and the next thing you know you will find yourself basking on the sandy beaches of Stranglethorn." },
        ["text"] = "Схоже, тобі потрібен прохід через Велике море. Тоді ти в правильному місці: це причал «Примхи Діви», найкращого пасажирського судна в цих водах. Коли вона прибуде, просто заходь на борт — і не встигнеш озирнутися, як уже грітимешся на піщаних пляжах Тернистої долини.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3008632341] = {
        ["english"] = { [1] = "Yeah, you'll always find Clyde Kellen fishing on the bank of Brightwater Lake just east of Brill.  Just watch out for psychos wearing masks while you're out there.  We had to shut down the kids' summer camp last year." },
        ["text"] = "Авжеж, Клайда Келлена ти завжди знайдеш за риболовлею на березі Ясноводного озера, просто на схід від Брілля. Тільки стережися психів у масках, поки будеш там. Торік через них нам довелося закрити дитячий літній табір.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1700381068] = {
        ["english"] = { [1] = "You desire to shape the bones of the Earth Mother into tools that will aid the Horde.  Good, good.  Follow the path north out of Bloodhoof Village until you come to the elevator leading to the top of Thunder Bluff.  A Bluffwatcher there can give you further assistance." },
        ["text"] = "Ти прагнеш надати кісткам Матері-Землі форми знарядь, що служитимуть Орді. Добре, добре. Іди стежкою на північ від селища Криваве Копито, доки не дістанешся підйомника на вершину Громового Бескиду. Тамтешній вартовий бескиду допоможе тобі далі.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [130583477] = {
        ["english"] = { [1] = "Yer looking to learn how to use a new weapon are ye?  Well, ye should be talking to Bixi or Buliwyf over at the Timberline Arms weapon shop then $glad : lass;.  They know their weapons from axes to... uh... zweihanders." },
        ["text"] = "Хочеш навчитися володіти новою зброєю, еге ж? Тоді тобі треба до Біксі або Булівіфа в крамницю зброї «Лісорубна зброярня», $gхлопче : дівчино;. Вони знаються на всьому — від сокир до... е-е... цвайгендерів.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [821750927] = {
        ["english"] = { [1] = "Yes, you heard true, $c, all of our collections are complete and the last of the war materiel should arrive in Silithus within $2113w days. I am told that once all is assembled there, and our troops readied, someone from within the ranks of you heroes is going to ring the gong outside of Ahn'Qiraj, already having assembled the Scepter of the Shifting Sands to do so with. I hope that we don't have to wait too long for that to happen." },
        ["text"] = "Так, ти чув правду, $c: усі наші збори завершено, а останні військові припаси мають прибути до Силітуса за $2113w днів. Кажуть, коли все буде зібрано й війська підготуються, хтось із вас, героїв, ударить у гонг біля Ан'Кіражу, вже зібравши для цього Скіпетр Мінливих Пісків. Сподіваюся, чекати доведеться недовго.",
        ["npcs"] = { [1] = 15529 },
        ["roles"] = { ["greeting"] = true },
    },
    [3773588784] = {
        ["english"] = { [1] = "You must be exalted with the blood elves before I will teach you a riding skill, $c." },
        ["text"] = "Ти маєш бути звеличеним серед ельфів крові, перш ніж я навчу тебе верхової їзди, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1017055951] = {
        ["english"] = { [1] = "You are no taunka. Why have you come to the sacred burial grounds of our warriors?" },
        ["text"] = "Ти не таунка. Навіщо прийшов на священні поховальні землі наших воїнів?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3464943550] = {
        ["english"] = { [1] = "You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.$B$BThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.$B$BEvery ability, prayer, and spell that you have learned will be tested. May the Light protect you, $N." },
        ["text"] = "Ти мусиш зробити те, чого не зміг я: врятувати селян, яких посікли під час втечі зі Стратгольма.$B$BВони йтимуть до світла, і ти мусиш забезпечити їхнє виживання. Якщо впаде надто багато, наше прокляте існування триватиме — і ти зазнаєш невдачі.$B$BНа випробування підуть усі здібності, молитви й закляття, яких ти навчився. Нехай Світло береже тебе, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1882525212] = {
        ["english"] = { [1] = "You are not trying to kill the anvil with your hammer, you are trying to create a weapon to kill your foes with. Let me show you what you are doing wrong." },
        ["text"] = "Ти ж не намагаєшся вбити ковадло молотом — ти намагаєшся викувати зброю, щоб убивати ворогів. Дозволь покажу, що ти робиш не так.",
        ["npcs"] = { [1] = 4605 },
        ["roles"] = { ["greeting"] = true },
    },
    [3824363353] = {
        ["english"] = { [1] = "You will be ok, Awbee. Your assailants have been terminated." },
        ["text"] = "Усе буде добре, Авбі. Твоїх нападників ліквідовано.",
        ["npcs"] = { [1] = 10740 },
        ["roles"] = { ["reply"] = true },
    },
    [3587523509] = {
        ["english"] = { [1] = "Yellow security card insertion successful.  Dispensing security level chi unit.\010\01001010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001" },
        ["text"] = "Жовту картку безпеки успішно вставлено. Видача модуля рівня безпеки «хі».\010\01001010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [366464791] = {
        ["english"] = { [1] = "Yes?" },
        ["text"] = "Так?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4064154557] = {
        ["english"] = { [1] = "Yes, sir. Thank you, sir!" },
        ["text"] = "Так, сер. Дякую, сер!",
        ["npcs"] = { [1] = 9077 },
        ["roles"] = { ["reply"] = true },
    },
    [4010308953] = {
        ["english"] = { [1] = "Your greatest challenge lies ahead.  Ley-Guardian Eregos is a Blue dragon of immense power. You will find him flying above the uppermost ring." },
        ["text"] = "Найбільше випробування ще попереду. Лей-вартовий Ереґос — синій дракон неймовірної могутності. Знайдеш його в польоті над найвищим кільцем.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4140901045] = {
        ["english"] = { [1] = "You need only face our rivals in any of the Battlegrounds. Win or lose, if you stay for the duration of the battle, you will be mailed a Competitor's Tabard." },
        ["text"] = "Тобі достатньо битися з нашими суперниками на будь-якому Полі бою. Переможеш чи програєш — якщо пробудеш там до кінця битви, тобі поштою надішлють Гербову накидку учасника.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2273594595] = {
        ["english"] = { [1] = "You think you're smart enough? You think you got what it takes? Let's find out!" },
        ["text"] = "Думаєш, достатньо розумний? Думаєш, упораєшся? Перевірмо!",
        ["npcs"] = { [1] = 2857 },
        ["roles"] = { ["greeting"] = true },
    },
    [3049514521] = {
        ["english"] = { [1] = "Yes, I speak a language you understand $r.  We are not animals, yet most of your kind continues to treat us as such!  Our differences though pale to the tragedy that has befallen this land.  Please, put aside your differences with my kind and hear my dying plea.$B$BI came to this land to mend what I could, and now that will be for naught unless you can aid me.  I ask for such aid with my last breaths of life." },
        ["text"] = "Так, я говорю мовою, яку ти розумієш, $r. Ми не тварини, але більшість твого народу й далі ставиться до нас саме так! Та наші відмінності — ніщо поруч із трагедією, що спіткала цю землю. Прошу, відкинь упередження проти мого народу й вислухай моє передсмертне прохання.$B$BЯ прийшов сюди, щоб виправити бодай те, що зможу, але все буде марно, якщо ти мені не допоможеш. Останніми подихами я благаю про цю допомогу.",
        ["npcs"] = { [1] = 10739 },
        ["roles"] = { ["greeting"] = true },
    },
    [2850901120] = {
        ["english"] = { [1] = "You're doing very well in the art of tailoring, I must admit. Now, let's see how good you REALLY are..." },
        ["text"] = "Мушу визнати, у кравецтві ти просуваєшся дуже добре. А тепер подивімося, наскільки ти СПРАВДІ вправний...",
        ["npcs"] = { [1] = 2399 },
        ["roles"] = { ["greeting"] = true },
    },
    [2178135406] = {
        ["english"] = { [1] = "You're free, Dughal! Get out of here!" },
        ["text"] = "Ти вільний, Дуґале! Забирайся звідси!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3705249348] = {
        ["english"] = { [1] = "You have reached the limits of my knowledge, but there is more yet to learn. Across the sea, in the Mage Quarter of Stormwind City, a great tailor dwells. His name is Georgio Bolero, and he will train you now, I think. Go and speak with him." },
        ["text"] = "Ти досяг межі моїх знань, але вчитися ще є чого. За морем, у Кварталі магів Штормовію, живе великий кравець. Його звати Джорджіо Болеро, і, думаю, тепер він тебе навчатиме. Іди й поговори з ним.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2074333645] = {
        ["english"] = { [1] = "You want the Hall of Legends. It's high above the Valley of Strength on the west side. If you're not an officer you can't get in, but you can still talk to Sergeant Ba'sha outside." },
        ["text"] = "Тобі потрібна Зала Легенд. Вона високо над Долиною Сили із західного боку. Якщо ти не офіцер, усередину не пустять, але можеш поговорити із сержантом Ба'шею біля входу.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [525730571] = {
        ["english"] = { [1] = "You know who can really show you some things? Nogg! You go find him in Orgrimmar." },
        ["text"] = "Знаєш, хто справді може багато чого показати? Ноґґ! Іди знайди його в Орґріммарі.",
        ["npcs"] = { [1] = 11025 },
        ["roles"] = { ["greeting"] = true },
    },
    [663708722] = {
        ["english"] = { [1] = "You want to talk to Osborne then. No finer teacher of the stealth arts than him in Stormwind. Look for him over in Old Town." },
        ["text"] = "Тоді тобі до Осборна. У Штормовії немає кращого вчителя мистецтва непомітності. Шукай його в Старому місті.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2116929329] = {
        ["english"] = { [1] = "You go Royal Quarter.  See Sir Malory Wheeler.  Him scary." },
        ["text"] = "Іди Королівський квартал. Шукай сера Мелорі Вілера. Він страшний.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2198438907] = {
        ["english"] = { [1] = "You need to be exalted with the dwarves of Ironforge before I will teach you a riding skill, $c." },
        ["text"] = "Ти маєш бути звеличеним серед дворфів Залізогарта, перш ніж я навчу тебе верхової їзди, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4158040420] = {
        ["english"] = { [1] = "You?$B$B<Lorax laughs.>$B$BThat is doubtful.$B$BI stand in these ruins and dream. Dream of the day that I catch that miserable thief, Goraluk Anvilcrack.$B$BWe had a deal, him and I. A deal that he broke. Betrayed." },
        ["text"] = "Ти?$B$B<Лоракс сміється.>$B$BСумніваюся.$B$BЯ стою серед цих руїн і мрію. Мрію про день, коли спіймаю того жалюгідного злодія, Ґоралука Тріснуте Ковадло.$B$BМи мали угоду, він і я. Угоду, яку він порушив. Зрадив.",
        ["npcs"] = { [1] = 10918 },
        ["roles"] = { ["greeting"] = true },
    },
    [128551860] = {
        ["english"] = { [1] = "You look like you could use some work, $g fella:lady;. You should board the tram and visit my brother, Monty, at the Ironforge Deeprun Tram depot. I'm sure he has something you could do." },
        ["text"] = "Схоже, тобі не завадить робота, $g друже:пані;. Сідай на трамвай і навідай мого брата Монті на станції Глибокобіжного трамвая у Залізогарті. Упевнений, він знайде тобі заняття.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1429908116] = {
        ["english"] = { [1] = "Yes, I am. What's it to you?" },
        ["text"] = "Так, це я. І що з того?",
        ["npcs"] = { [1] = 6497 },
        ["roles"] = { ["greeting"] = true },
    },
    [1307873425] = {
        ["english"] = { [1] = "You're hunting Deathclasp, $N?  Color me impressed.  I lost two of my men to her this week alone.  Let's hope your luck is better than theirs." },
        ["text"] = "Полюєш на Смертехвата, $N? Вражає. Лише цього тижня я втратив через неї двох людей. Сподіваймося, тобі пощастить більше.",
        ["npcs"] = { [1] = 15182 },
        ["roles"] = { ["greeting"] = true },
    },
    [1071780371] = {
        ["english"] = { [1] = "You are not ready. Speak to Betty Quinn, she's standing by the stairs over there. Return to me when you have achieved a higher enlightenment." },
        ["text"] = "Ти ще не готовий. Поговори з Бетті Квінн, вона стоїть он біля сходів. Повернися, коли досягнеш вищого просвітлення.",
        ["npcs"] = { [1] = 1317 },
        ["roles"] = { ["greeting"] = true },
    },
    [3812456709] = {
        ["english"] = { [1] = "You come to wrong place. Talk to the expert Godan over there. You learn more from him." },
        ["text"] = "Ти прийти не туди. Говорити з експертом Ґоданом, он там. У нього більше навчишся.",
        ["npcs"] = { [1] = 11066 },
        ["roles"] = { ["greeting"] = true },
    },
    [1210765157] = {
        ["english"] = { [1] = "You'll find the Mage Trainer, Cain Firesong, upstairs on the landing at the Gallows' End Tavern, which is on the southeast end of Brill.  I guess he checked in too late to get a room." },
        ["text"] = "Наставника магів Кейна Вогнеспіва знайдеш нагорі на майданчику таверни «Кінець Шибеника» в південно-східній частині Брілля. Гадаю, він надто пізно заселився, щоб отримати кімнату.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [184416880] = {
        ["english"] = { [1] = "You are not yet powerful enough, $c.  Move along." },
        ["text"] = "Тобі ще бракує сили, $c. Іди далі.",
        ["npcs"] = { [1] = 14990 },
        ["roles"] = { ["greeting"] = true },
    },
    [1769363057] = {
        ["english"] = { [1] = "You might wanna stand back. Fish guttin' is a dirty job." },
        ["text"] = "Може, відійдеш трохи. Потрошити рибу — брудна справа.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3667695056] = {
        ["english"] = { [1] = "Yes, $c, what is it?" },
        ["text"] = "Так, $c, що таке?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1555459899] = {
        ["english"] = { [1] = "Zim'Torga is able to provide us with a certain level of protection, but she has been greatly weakened by the presence of the Scourge and the actions of the Drakkari.$B$BIt falls to me and Ahunae to see to the rest of our defenses." },
        ["text"] = "Зім'Торґа здатна певною мірою захистити нас, але присутність Скверни й дії Драккарі сильно її послабили.$B$BРешта нашого захисту лежить на мені та Агунае.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3412587502] = {
        ["english"] = { [1] = "You can take a man away from the Sons of Lothar, but you can't take the Sons out of him.$B$B<The smith shrugs.>$B$BIt's hard to explain, but I don't feel like I'm meant to be at Honor Hold right now, is all.$B$BPerhaps I'm meant to be part of something larger." },
        ["text"] = "Можна забрати людину від Синів Лотара, але Синів із людини не забереш.$B$B<Коваль знизує плечима.>$B$BВажко пояснити, але мені просто здається, що зараз моє місце не в Оплоті Честі.$B$BМожливо, я маю стати частиною чогось більшого.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3106029188] = {
        ["english"] = { [1] = "You need to be exalted with the gnomes of the Gnomeregan Exiles before I will teach you how to pilot a Mechanostrider, $c." },
        ["text"] = "Ти маєш бути звеличеним серед гномів-вигнанців Гномреґана, перш ніж я навчу тебе керувати механодолітом, $c.",
        ["npcs"] = { [1] = 7954 },
        ["roles"] = { ["greeting"] = true },
    },
    [4132245502] = {
        ["english"] = { [1] = "You're a fool that should heed my warnings. No one is invulnerable. You would be wise to remember that bit of advice." },
        ["text"] = "Ти дурень, якщо не слухаєш моїх попереджень. Ніхто не невразливий. Було б мудро це запам'ятати.",
        ["npcs"] = { [1] = 3836 },
        ["roles"] = { ["greeting"] = true },
    },
    [1645386725] = {
        ["english"] = { [1] = "You see, all you gotta do is forge the Sulfuron hammer and find yourself the Eye of Sulfuras. Combine the Eye of Sulfuras with the Sulfuron hammer and it will become Sulfuras! Now I'm not going to bog you down with any technical information as to where or how or when you can get an Eye of Sulfuras. I'm sure you'll figure that stuff out. Just sign this here contract so that our agreement is binding and our business will be done." },
        ["text"] = "Розумієш, усе, що треба зробити, — викувати молот Сульфурона й знайти Око Сульфураса. Поєднаєш Око Сульфураса з молотом Сульфурона — і він стане Сульфурасом! Не буду забивати тобі голову технічними подробицями про те, де, як і коли можна дістати Око Сульфураса. Упевнений, сам розберешся. Просто підпиши ось цей контракт, щоб наша угода стала чинною, і справу буде завершено.",
        ["npcs"] = { [1] = 12944 },
        ["roles"] = { ["greeting"] = true },
    },
    [1930238008] = {
        ["english"] = { [1] = "Yes, the Lich King will fall to our might. We will have our final revenge.$B$BBut first, we will see to it that the plague known as the Scarlet Onslaught comes to an end once and for all!" },
        ["text"] = "Так, Король-ліч упаде перед нашою міццю. Ми нарешті помстимося.$B$BАле спершу покладемо край пошесті, відомій як Багряний Натиск, раз і назавжди!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4257636669] = {
        ["english"] = { [1] = "You like candy?  I like candy." },
        ["text"] = "Любиш цукерки? Я люблю цукерки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2470316543] = {
        ["english"] = { [1] = "You'll find Carolai Anise trying to blow up her house at the northwest end of town.  Why don't you go see if you can help her?" },
        ["text"] = "Каролай Аніс знайдеш у північно-західному кінці міста — вона намагається підірвати власний будинок. Чому б тобі не піти й не допомогти їй?",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [2288721768] = {
        ["english"] = { [1] = "You don't. You're not strong enough to participate in ranking matches yet. Still, you can find an Arena Battlemaster and get in some practice rounds. It's never too soon to start training." },
        ["text"] = "Ні. Ти ще недостатньо сильний для рейтингових боїв. Але можеш знайти розпорядника арени й провести кілька тренувальних сутичок. Починати тренування ніколи не рано.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2776118866] = {
        ["english"] = { [1] = "You have outgrown any teachings I could offer. Go with the blessing of the Earth Mother. Seek out the tauren Tarn in the northwestern shops of Thunder Bluff's central plateau. Be guided by his wisdom." },
        ["text"] = "Ти вже переріс усе, чого я міг би навчити. Іди з благословенням Матері-Землі. Знайди таурена Тарна в північно-західних крамницях центрального плато Громового Бескиду. Нехай його мудрість веде тебе.",
        ["npcs"] = { [1] = 3069 },
        ["roles"] = { ["greeting"] = true },
    },
    [820166397] = {
        ["english"] = { [1] = "Yes, $c?" },
        ["text"] = "Так, $c?",
        ["npcs"] = { [1] = 2123, [2] = 2129, [3] = 3044, [4] = 3045, [5] = 3046, [6] = 4606, [7] = 4607, [8] = 4608, [9] = 6122 },
        ["roles"] = { ["greeting"] = true },
    },
    [4224897607] = {
        ["english"] = { [1] = "You have wasted your time and mine by coming to me for training, $N. I have no time to teach basic skills. We're fighting a war here, and this is one of the front lines. Don't return to me until you are more prepared." },
        ["text"] = "Ти змарнував і свій, і мій час, прийшовши до мене по навчання, $N. У мене немає часу вчити основ. Тут війна, і це одна з передових. Не повертайся, доки не будеш краще підготовлений.",
        ["npcs"] = { [1] = 11098 },
        ["roles"] = { ["greeting"] = true },
    },
    [3086106284] = {
        ["english"] = { [1] = "You mean, you don't know? The sword that you carry on your back - it is known as Ashbringer; named after its original owner." },
        ["text"] = "Тобто ти не знаєш? Меч за твоєю спиною відомий як Попелитель — на честь його першого власника.",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [4015651145] = {
        ["english"] = { [1] = "Yes. I have." },
        ["text"] = "Так.",
        ["npcs"] = { [1] = 8141 },
        ["roles"] = { ["reply"] = true },
    },
    [1588249127] = {
        ["english"] = { [1] = "You've served our cause with great loyalty, $N.  Allow me to present you with an unending source of our elemental quintessence." },
        ["text"] = "Ти з великою відданістю служив нашій справі, $N. Дозволь подарувати тобі невичерпне джерело нашої стихійної квінтесенції.",
        ["npcs"] = { [1] = 13278 },
        ["roles"] = { ["greeting"] = true },
    },
    [3234204981] = {
        ["english"] = { [1] = "You may shed yourself of your worldly possessions at the Thunder Bluff Bank on the lower rise." },
        ["text"] = "Позбутися тягаря мирських пожитків можна в Банку Громового Бескиду на нижньому уступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2826128239] = {
        ["english"] = { [1] = "You seem confident. Surely you wouldn't mind a test of your skills?" },
        ["text"] = "Ти виглядаєш упевнено. Напевно, не заперечуватимеш проти перевірки своїх умінь?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2374716191] = {
        ["english"] = { [1] = "Yes, Bonescythe. You see, it was our tenor, an ornery fellow known as Don Julio, who got me started on the whole thing. In his travels throughout Lordaeron, Don Julio picked up many interesting skills, one of them being the ability to take the bones of fallen Scourge and fashion them into a lethal set of leather armor - perfectly suited for an assassin." },
        ["text"] = "Так, Кісткокосе. Розумієш, усе почалося з нашого тенора — сварливого типа на ім'я дон Хуліо. У мандрах Лордероном дон Хуліо опанував чимало цікавих умінь, зокрема навчився брати кістки полеглих воїнів Скверни й виготовляти з них смертоносний комплект шкіряної броні — якраз для вбивці.",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["greeting"] = true },
    },
    [3796237096] = {
        ["english"] = { [1] = "Yep. You never heard of Ironfoe? The legendary orc slaying hammer? Yep, yep, that was ol' Windsor's hammer. He told me that Franclorn Forgewright himself made that hammer for his great, great, grand pappy. THE Franclorn Forgewright: The Dark Iron responsible for stonewrought archimetenc... building stuff. He also said the hammer had a twin that Franclorn kept for himself. Think he called it Ironfel or something." },
        ["text"] = "Авжеж. Ти що, ніколи не чув про Залізного Ворога? Легендарний молот-вбивцю орків? Так-так, це був старий молот Віндзора. Він казав мені, що сам Франклорн Горнмастак викував його для свого пра-пра-прадіда. ТОЙ САМИЙ Франклорн Горнмастак: дворф Темного Заліза, що відповідав за кам'яно... архітектурні... ну, будівельні штуки. А ще він казав, що в молота був близнюк, якого Франклорн залишив собі. Здається, називав його Залізопадом чи якось так.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [2640084441] = {
        ["english"] = { [1] = "You've come a long way, $N. A long way indeed... But I knew you were destined for great things.  We all knew. All hail $N!$B$BAnd thanks again for taking care of our gnome problem..." },
        ["text"] = "Ти пройшов довгий шлях, $N. Дуже довгий... Але я знав, що тобі судилися великі справи. Ми всі знали. Слава $N!$B$BІ ще раз дякую, що розібрався з нашою проблемою з гномами...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [559623664] = {
        ["english"] = { [1] = "You seek passage somewhere, $N?  My bats will get you there in no time." },
        ["text"] = "Шукаєш шлях кудись, $N? Мої кажани доставлять тебе миттю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1503807653] = {
        ["english"] = { [1] = "You've got money and we've got food.  What are you waiting for?!" },
        ["text"] = "У тебе є гроші, а в нас є їжа. Чого ж ти чекаєш?!",
        ["npcs"] = { [1] = 14845 },
        ["roles"] = { ["greeting"] = true },
    },
    [2596197745] = {
        ["english"] = { [1] = "You look lost, $c. Don't make me put you to work on the walls with the other peons." },
        ["text"] = "Схоже, ти заблукав, $c. Не змушуй мене відправити тебе працювати на мури разом з іншими наймитами.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1757354116] = {
        ["english"] = { [1] = "You must defeat your rivals in any of the Battlegrounds. With every victory, there is a chance that a Gold Medallion will be mailed to you." },
        ["text"] = "Треба перемогти своїх суперників на будь-якому Полі бою. Після кожної перемоги є шанс, що тобі поштою надішлють Золотий медальйон.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1848004194] = {
        ["english"] = { [1] = "Your skill exceeds mine, though  I've heard that Old Man Heming in Booty Bay has copies of The Bass and You.  That is sure to help you increase your skill." },
        ["text"] = "Твоя майстерність перевищує мою, але чув, що Старий Гемінґ у Бухті Наживи має примірники «Окунь і ти». Це точно допоможе тобі покращити вміння.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3191733109] = {
        ["english"] = { [1] = "You see, Thorim is not like these harpies.  He's a worthy being of near godlike stature.$B$BHe served the titans as guardian of Ulduar and the Terrace of the Makers.$B$BThat is until his wife, Sif, was cowardly slain by his brother." },
        ["text"] = "Розумієш, Торім не такий, як ці гарпії. Він гідна істота, майже божественної величі.$B$BВін служив титанам як вартовий Ульдуара й Тераси Творців.$B$BАж доки його дружину Сіф підло не вбив його брат.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2384647493] = {
        ["english"] = { [1] = "You lookin' for me?" },
        ["text"] = "Мене шукаєш?",
        ["npcs"] = { [1] = 2785 },
        ["roles"] = { ["greeting"] = true },
    },
    [2992175482] = {
        ["english"] = { [1] = "You look like you may know your way around a beast that runs on land, but if you want to soar, it'll take training and dedication. And gold. You have gold, right?" },
        ["text"] = "Схоже, ти знаєш, як поводитися зі звіром, що бігає землею, але для польоту потрібні тренування, відданість справі й золото. Золото в тебе є, так?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1367450975] = {
        ["english"] = { [1] = "You hear that? You hear that chantin', brother? They're cheerin' for the Rulkster!" },
        ["text"] = "Чуєш? Чуєш, як вони скандують, брате? Вони вболівають за Ралкстера!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1153261377] = {
        ["english"] = { [1] = "You're shaping up nicely, $N. I've heard good things..." },
        ["text"] = "Ти добре набираєш форму, $N. Я чув гарні речі...",
        ["npcs"] = { [1] = 6771 },
        ["roles"] = { ["greeting"] = true },
    },
    [3685172056] = {
        ["english"] = { [1] = "You're working your way up??? higher than me, at this point! You should talk to Springspindle Fizzlegear in Ironforge! He'll show you more than I ever could!" },
        ["text"] = "Ти вже піднявся??? Та вже вище за мене! Поговори зі Спрінґспіндлом Фізлґіром у Залізогарті! Він покаже тобі значно більше, ніж я коли-небудь міг!",
        ["npcs"] = { [1] = 1676 },
        ["roles"] = { ["greeting"] = true },
    },
    [1663683141] = {
        ["english"] = { [1] = "You looking at me, $gladdy:lassy;?" },
        ["text"] = "На мене дивишся, $gхлопче:дівчино;?",
        ["npcs"] = { [1] = 9554, [2] = 10043 },
        ["roles"] = { ["greeting"] = true },
    },
    [1745199881] = {
        ["english"] = { [1] = "You can learn from me in time, but not yet! Why don't you start out by talking to Sprite Jumpsprocket to my right here. You can check in with me after you've gotten your feet wet!" },
        ["text"] = "Згодом ти зможеш учитися в мене, але ще не зараз! Для початку поговори зі Спрайтом Стрибогвинтом, он праворуч від мене. А коли трохи наб'єш руку, повертайся!",
        ["npcs"] = { [1] = 5518 },
        ["roles"] = { ["greeting"] = true },
    },
    [3385632561] = {
        ["english"] = { [1] = "You mean you can't smell the smoke of the Dwarven forges from here?  Well, you will be looking for Therum Deepforge if you want to learn blacksmithing.  He's over in the Dwarven District which is just north of the Cathedral Square." },
        ["text"] = "Ти що, не чуєш звідси диму дворфійських горнів? Якщо хочеш навчитися ковальства, шукай Терума Глибококовача. Він у Дворфівському районі, просто на північ від Соборної площі.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2972793751] = {
        ["english"] = { [1] = "You dare set foot inside Ravenholdt Manor, worm?" },
        ["text"] = "Ти насмілився ступити до маєтку Крука, хробаче?",
        ["npcs"] = { [1] = 6771 },
        ["roles"] = { ["greeting"] = true },
    },
    [2988193999] = {
        ["english"] = { [1] = "Yeah, you know a few things! If you wanna' learn more you're gonna' have to talk to Georgio Bolero in Stormwind." },
        ["text"] = "Еге ж, дещо ти таки знаєш! Якщо хочеш навчитися більшого, доведеться поговорити з Джорджіо Болеро у Штормовії.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1286268802] = {
        ["english"] = { [1] = "You look familiar..." },
        ["text"] = "Ти мені когось нагадуєш...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3619354317] = {
        ["english"] = { [1] = "You best have a seat then, this is gonna be a long one.$B$BWhen we initially arrived in Silithus, Mistress Mar'alith was the first of the night elves from Cenarion Hold to join the expedition. Our routine was nothing out of the ordinary: Form a party to venture into the various hives and search for lost artifacts. " },
        ["text"] = "Краще присядь, бо історія буде довга.$B$BКоли ми вперше прибули до Силітуса, пані Мар'аліт стала першою нічною ельфійкою з Кенарійської цитаделі, що приєдналася до експедиції. Наш звичайний порядок був простий: зібрати групу, вирушити до різних вуликів і шукати втрачені артефакти.",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["greeting"] = true },
    },
    [3422992538] = {
        ["english"] = { [1] = "Your name seems to be on everyone's lips around the outpost.  Don't let it get to your head; I know that you can do better!$B$BI'll be watching you, rookie." },
        ["text"] = "Твоє ім'я, здається, у всіх на устах по всій заставі. Тільки не зазнавайся; я знаю, що ти здатен на більше!$B$BЯ стежитиму за тобою, новобранцю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [950854730] = {
        ["english"] = { [1] = "Yes, Augustus.  I would like to do business." },
        ["text"] = "Так, Августе. Я хочу укласти угоду.",
        ["npcs"] = { [1] = 12384 },
        ["roles"] = { ["reply"] = true },
    },
    [2577336754] = {
        ["english"] = { [1] = "You have nearly reached the pinnacle of your training. To become the greatest enchanter you can possibly be, you have one more instructor to seek out. Her name is Annora, and you may find her in Uldaman." },
        ["text"] = "Ти майже дістався вершини свого навчання. Щоб стати найкращим заклиначем, яким тільки можеш бути, тобі лишилося знайти ще одну наставницю. Її звати Аннора, і знайдеш її в Ульдамані.",
        ["npcs"] = { [1] = 11072 },
        ["roles"] = { ["greeting"] = true },
    },
    [3873721231] = {
        ["english"] = { [1] = "Your voice is hoarse from yelling huh?  Find the Orgrimmar Auction House in the Valley of Strength." },
        ["text"] = "Голос захрип від криків, еге ж? Шукай Аукціонний дім Орґріммара в Долині Сили.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [2626117493] = {
        ["english"] = { [1] = "Yep, you looking for Christopher Drakul in Trade Quarter.  He on eastern platform." },
        ["text"] = "Авжеж, тобі потрібен Крістофер Дракул у Торговому кварталі. Він на східній платформі.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1176383274] = {
        ["english"] = { [1] = "You are gonna want to head over to Old Town and drop by the Protective Hide if you are lookin' to learn skinning." },
        ["text"] = "Якщо хочеш навчитися знімати шкури, прямуй до Старого міста й зазирни до «Захисної Шкури».",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3372610826] = {
        ["english"] = { [1] = "You're going to pull off a stunt on Jack in front of his boys?$B$BThat takes a good amount of... stupidity.  Well, it's going to cost you.  I'm not going to risk my life for anything less than a gold.  And you best wait til I'm out of the way before you make a move." },
        ["text"] = "Ти збираєшся утнути щось із Джеком перед його хлопцями?$B$BДля цього треба чимало... дурості. І це коштуватиме тобі. Я не ризикуватиму життям менше ніж за золотий. І краще дочекайся, поки я відійду, перш ніж починати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2189123613] = {
        ["english"] = { [1] = "Yes, little one?" },
        ["text"] = "Так, малечо?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4219891144] = {
        ["english"] = { [1] = "You aiming to be a taxidermist?  I don't like people who think they can stuff and mount me because they think I'm dead.  No?  Good!  Look for Rand Rhobart at a camp to the southeast of town.  To get to him take the road southeast out of Brill and hang a left at the intersection." },
        ["text"] = "Хочеш стати таксидермістом? Не люблю людей, які думають, що можуть набити мене й поставити на підставку лише тому, що вважають мертвим. Ні? Чудово! Шукай Ренда Робарта в таборі на південний схід від міста. Вийди з Брілля дорогою на південний схід і на перехресті поверни ліворуч.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1155853718] = {
        ["english"] = { [1] = "You big boss now!  You king!  All hail King $N, King of Gordok!$B$BNow that you da boss, all henchmen will give you tribute!  You left some alive, yeah boss?" },
        ["text"] = "Ти тепер великий бос! Ти король! Слава королю $N, королю Ґордока!$B$BТепер ти бос, усі посіпаки платити тобі данину! Ти ж когось лишив живим, га, бос?",
        ["npcs"] = { [1] = 14353 },
        ["roles"] = { ["greeting"] = true },
    },
    [3990641961] = {
        ["english"] = { [1] = "You could at least try to sound a little bit convincing.$B$BLook, Nuaar, I wasn't going to tell you this, but I might as well because it's going to involve you, too.  Maxnar is planning an all-out attack on the druids at Ruuan Weald.  And he intends to wipe them out.$B$BIt's bad enough that we've been fighting with the Boulder'mok ogres, so we can't afford another front to deal with.  I've arranged for a temporary truce with the arakkoa.$B$BWell, what do you think?" },
        ["text"] = "Міг би бодай спробувати звучати переконливіше.$B$BПослухай, Нуаар, я не збирався тобі цього казати, але доведеться, бо це стосуватиметься й тебе. Макснар готує повномасштабний напад на друїдів у Рууанському лісі. І хоче винищити їх усіх.$B$BНам і так вистачає війни з ограми Валун'мока, другого фронту ми не витримаємо. Я домовився про тимчасове перемир'я з араккоа.$B$BНу, що скажеш?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [268427819] = {
        ["english"] = { [1] = "You will find numerous trainers around Dolanaar with ages of experience with which to tutor you.  Which would you have me point you to?" },
        ["text"] = "У Доланаарі чимало наставників із багатовіковим досвідом, готових тебе навчати. До кого саме тебе направити?",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [505109101] = {
        ["english"] = { [1] = "Yes. I do." },
        ["text"] = "Так.",
        ["npcs"] = { [1] = 198, [2] = 328, [3] = 331, [4] = 375, [5] = 376, [6] = 377, [7] = 459, [8] = 460, [9] = 461, [10] = 837, [11] = 895, [12] = 906, [13] = 911, [14] = 912, [15] = 913, [16] = 914, [17] = 915, [18] = 916, [19] = 917, [20] = 918, [21] = 925, [22] = 926, [23] = 927, [24] = 928, [25] = 944, [26] = 985, [27] = 986, [28] = 987, [29] = 988, [30] = 1226, [31] = 1228, [32] = 1229, [33] = 1231, [34] = 1232, [35] = 1234, [36] = 1404, [37] = 1411, [38] = 1901, [39] = 2119, [40] = 2122, [41] = 2123, [42] = 2124, [43] = 2126, [44] = 2127, [45] = 2128, [46] = 2129, [47] = 2130, [48] = 2131, [49] = 3030, [50] = 3031, [51] = 3032, [52] = 3033, [53] = 3034, [54] = 3036, [55] = 3038, [56] = 3039, [57] = 3040, [58] = 3041, [59] = 3042, [60] = 3043, [61] = 3044, [62] = 3045, [63] = 3046, [64] = 3047, [65] = 3048, [66] = 3049, [67] = 3059, [68] = 3060, [69] = 3061, [70] = 3062, [71] = 3063, [72] = 3064, [73] = 3065, [74] = 3066, [75] = 3153, [76] = 3154, [77] = 3155, [78] = 3156, [79] = 3157, [80] = 3169, [81] = 3170, [82] = 3171, [83] = 3172, [84] = 3173, [85] = 3324, [86] = 3325, [87] = 3326, [88] = 3327, [89] = 3328, [90] = 3344, [91] = 3352, [92] = 3353, [93] = 3354, [94] = 3401, [95] = 3403, [96] = 3406, [97] = 3407, [98] = 3408, [99] = 3593, [100] = 3594, [101] = 3595, [102] = 3596, [103] = 3597, [104] = 3598, [105] = 3599, [106] = 3600, [107] = 3601, [108] = 3602, [109] = 3706, [110] = 3707, [111] = 3963, [112] = 4087, [113] = 4089, [114] = 4090, [115] = 4091, [116] = 4092, [117] = 4138, [118] = 4163, [119] = 4205, [120] = 4214, [121] = 4215, [122] = 4217, [123] = 4218, [124] = 4219, [125] = 4563, [126] = 4564, [127] = 4565, [128] = 4566, [129] = 4567, [130] = 4568, [131] = 4582, [132] = 4583, [133] = 4584, [134] = 4593, [135] = 4594, [136] = 4595, [137] = 4606, [138] = 4607, [139] = 4608, [140] = 5113, [141] = 5114, [142] = 5115, [143] = 5116, [144] = 5117, [145] = 5141, [146] = 5142, [147] = 5143, [148] = 5144, [149] = 5145, [150] = 5146, [151] = 5147, [152] = 5148, [153] = 5149, [154] = 5165, [155] = 5166, [156] = 5167, [157] = 5171, [158] = 5172, [159] = 5173, [160] = 5479, [161] = 5480, [162] = 5484, [163] = 5489, [164] = 5491, [165] = 5492, [166] = 5495, [167] = 5496, [168] = 5497, [169] = 5498, [170] = 5501, [171] = 5504, [172] = 5505, [173] = 5506, [174] = 5515, [175] = 5516, [176] = 5517, [177] = 5612, [178] = 5880, [179] = 5882, [180] = 5883, [181] = 5884, [182] = 5885, [183] = 5994, [184] = 6014, [185] = 6018, [186] = 6707, [187] = 7311, [188] = 7312, [189] = 7315, [190] = 8140, [191] = 8141, [192] = 8142, [193] = 8308, [194] = 9465, [195] = 10930, [196] = 11397, [197] = 11401, [198] = 11406, [199] = 12042, [200] = 13283, [201] = 13417 },
        ["roles"] = { ["reply"] = true },
    },
    [108872560] = {
        ["english"] = { [1] = "You work with machines for so long, sometimes you forget about real hearts." },
        ["text"] = "Коли надто довго працюєш із машинами, часом забуваєш про справжні серця.",
        ["npcs"] = { [1] = 4081, [2] = 5100, [3] = 5128, [4] = 5129, [5] = 5132, [6] = 5151, [7] = 5152, [8] = 5158, [9] = 5162, [10] = 5163, [11] = 5169, [12] = 5175, [13] = 5178, [14] = 5519, [15] = 6120, [16] = 6169, [17] = 6569, [18] = 6579, [19] = 6826, [20] = 7950, [21] = 7978, [22] = 8681, [23] = 9099, [24] = 10455, [25] = 10456, [26] = 14440, [27] = 14441, [28] = 14442 },
        ["roles"] = { ["greeting"] = true },
    },
    [2784314238] = {
        ["english"] = { [1] = "You can find Vance Undergloom upstairs in a room at the Gallows' End Tavern on the southeast side of Brill." },
        ["text"] = "Венса Підморока знайдеш нагорі в кімнаті таверни «Кінець Шибеника» на південно-східному боці Брілля.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [2081215546] = {
        ["english"] = { [1] = "You seek further instruction in the manipulation of the naaru's power, $n?" },
        ["text"] = "Ти прагнеш подальших настанов у керуванні силою наару, $n?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3694309576] = {
        ["english"] = { [1] = "You have <snort> aided Mangletooth more than I would have dreamed, $r.$B$BThank you.$B$BAs long as I remain a captive here, you may bring me blood shards from the Bristleback quilboar and I will bless you with Agamaggan's power." },
        ["text"] = "Ти <фиркає> допоміг Кривозубу більше, ніж я міг мріяти, $r.$B$BДякую.$B$BПоки я лишаюся тут у полоні, можеш приносити мені криваві уламки свинобразів Щетиношкурих, і я благословлятиму тебе силою Аґамаґґана.",
        ["npcs"] = { [1] = 3430 },
        ["roles"] = { ["greeting"] = true },
    },
    [2637121941] = {
        ["english"] = { [1] = "Your future is clouded.  Concentrate, and ask again." },
        ["text"] = "Твоє майбутнє оповите туманом. Зосередься й запитай знову.",
        ["npcs"] = { [1] = 10433 },
        ["roles"] = { ["greeting"] = true },
    },
    [847205629] = {
        ["english"] = { [1] = "Zul'jin shall return one day, $r. Mark my words. Until then, we all hold our positions and do what we can to keep the forest troll population intact.$B$BWith that said, as master huntsman of Revantusk Village, it is my responsibility to insure that the world around us is safe for habitation.$B$BThe beasts of this area must be kept in check.$B$BAre you looking for work?\010" },
        ["text"] = "Колись Зул'джин повернеться, $r. Запам'ятай мої слова. А до того часу ми всі тримаємо позиції й робимо все, щоб зберегти чисельність лісових тролів.$B$BЯк головний мисливець селища Сколотий Бивень, я відповідаю за те, щоб навколишні землі були безпечними для життя.$B$BЧисельність місцевих звірів треба тримати під контролем.$B$BШукаєш роботу?",
        ["npcs"] = { [1] = 14741 },
        ["roles"] = { ["greeting"] = true },
    },
    [2431139722] = {
        ["english"] = { [1] = "Zug zug, my friend!  I am Kelm Hargunth, the main supplier for the Warsong Outriders.  As you improve your standing with the Outriders, I will make available to you a fine selection of goods that you can use inside Warsong Gulch.  Should you find yourself in need of item repair, I also provide those services." },
        ["text"] = "Зуґ-зуґ, друже! Я Келм Гарґунт, головний постачальник Вершників Пісні Війни. Що кращою буде твоя репутація серед Вершників, то ширший вибір товарів для використання в Ущелині Пісні Війни я зможу тобі запропонувати. Якщо знадобиться ремонт спорядження, я також цим займаюся.",
        ["npcs"] = { [1] = 14754 },
        ["roles"] = { ["greeting"] = true },
    },
    [2773508305] = {
        ["english"] = { [1] = "Your interruption is costing me valuable time, this had better be good." },
        ["text"] = "Ти відволікаєш мене й забираєш дорогоцінний час. Сподіваюся, справа справді важлива.",
        ["npcs"] = { [1] = 3557 },
        ["roles"] = { ["greeting"] = true },
    },
    [1449716190] = {
        ["english"] = { [1] = "You want my help? You got it. What do you need?" },
        ["text"] = "Хочеш моєї допомоги? Домовились. Що потрібно?",
        ["npcs"] = { [1] = 4900 },
        ["roles"] = { ["greeting"] = true },
    },
    [1575253073] = {
        ["english"] = { [1] = "You may not pass.  You are not our kin, nor have you issued the challenge." },
        ["text"] = "Проходу немає. Ти не з нашого роду й не кинув виклик.",
        ["npcs"] = { [1] = 9038 },
        ["roles"] = { ["greeting"] = true },
    },
    [3297207930] = {
        ["english"] = { [1] = "You tell an incredible tale, Fairbanks. What of the blade? Is it beyond redemption?" },
        ["text"] = "Ти розповідаєш неймовірну історію, Феєрбенксе. А що з клинком? Його вже не врятувати?",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [2977004492] = {
        ["english"] = { [1] = "You should recieve a pack of incendiary bombs from Erozion before I fly you to Durnholde. You wouldn't want to waste time, after all." },
        ["text"] = "Перш ніж я повезу тебе до Дарнгольда, Ерозіон має видати тобі пакунок запалювальних бомб. Не варто марнувати час.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2218291428] = {
        ["english"] = { [1] = "You've got to try some of this beer." },
        ["text"] = "Тобі треба скуштувати цього пива.",
        ["npcs"] = { [1] = 2920 },
        ["roles"] = { ["greeting"] = true },
    },
    [2536310416] = {
        ["english"] = { [1] = "You must... free... my children..." },
        ["text"] = "Ти мусиш... звільнити... моїх дітей...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3648209117] = {
        ["english"] = { [1] = "You must have wondered how it is that I can speak so clearly for an ogre.  It's a side effect of the crystals that grow on the terrace surrounding Ogri'la.  The ogres there gifted me with this staff, and its crystal has in turn gifted me mentally.$B$BIt is through your continued actions, at Ogri'la above, that I hope to one day be able to bring this boon to all of my ogre brethren.  You have my thanks, my $g king : queen;, for all that you have done and will do." },
        ["text"] = "Ти, напевно, дивувався, як це я так чітко говорю як для огра. Це побічний ефект кристалів, що ростуть на терасі навколо Оґріли. Тамтешні огри подарували мені цей посох, а його кристал, своєю чергою, обдарував мій розум.$B$BЯ сподіваюся, що завдяки твоїм подальшим діям в Оґрілі нагорі одного дня зможу принести це благо всім своїм братам-ограм. Дякую тобі, $g мій королю : моя королево;, за все, що ти вже зробив і ще зробиш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3284280608] = {
        ["english"] = { [1] = "Zaldimar could probably teach you some new spells.  He has recently taken a liking to staying at the Lion's Pride Inn, you might want to check one of the rooms and see if he's in." },
        ["text"] = "Залдімар, напевно, зможе навчити тебе нових заклять. Останнім часом йому сподобалося зупинятися в заїзді «Левова Гордість»; перевір кімнати, може, він там.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [11418037] = {
        ["english"] = { [1] = "Zalazane's time be runnin' out. De Echo Isles will belong to de Darkspear Tribe again!" },
        ["text"] = "Час Залазані добігає кінця. Острови Відлуння знову належатимуть племені Темносписа!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3893777371] = {
        ["english"] = { [1] = "You'll need to head to Orgrimmar for that.  Just follow the road heading out of Razor Hill to the north through the canyon and you'll come to it.  When you get there ask one of their grunts for further directions." },
        ["text"] = "Для цього доведеться йти до Орґріммара. Просто йди дорогою від Колючого Пагорба на північ через каньйон — і дістанешся туди. На місці спитай подальшу дорогу в одного з їхніх рубак.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [1217448681] = {
        ["english"] = { [1] = "Your will is strong, and your intent is clear.$B$BPerhaps you are worthy..." },
        ["text"] = "Твоя воля сильна, а намір ясний.$B$BМожливо, ти гідний...",
        ["npcs"] = { [1] = 9037 },
        ["roles"] = { ["greeting"] = true },
    },
    [2130343117] = {
        ["english"] = { [1] = "Your will is not strong enough to manipulate the forces we control $c." },
        ["text"] = "Твоя воля недостатньо сильна, щоб керувати силами, які ми підкорили, $c.",
        ["npcs"] = { [1] = 988, [2] = 3156, [3] = 3172, [4] = 4563 },
        ["roles"] = { ["greeting"] = true },
    },
    [3549524405] = {
        ["english"] = { [1] = "You have not yet earned the right to train with me. See Thund first, over by the table. Come back when he says you're ready!" },
        ["text"] = "Ти ще не заслужив права тренуватися зі мною. Спершу звернися до Тунда, он біля столу. Повернися, коли він скаже, що ти готовий!",
        ["npcs"] = { [1] = 3412 },
        ["roles"] = { ["greeting"] = true },
    },
    [2913627606] = {
        ["english"] = { [1] = "You're always welcome here, $N. Thanks for the laugh -- and don't worry about Daryl, he had one coming!" },
        ["text"] = "Тобі тут завжди раді, $N. Дякую за сміх — і не хвилюйся за Деріла, він сам напросився!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [640264834] = {
        ["english"] = { [1] = "You need to be exalted with the orcs of Orgrimmar before I will teach you a riding skill, $c." },
        ["text"] = "Ти маєш бути звеличеним серед орків Орґріммара, перш ніж я навчу тебе верхової їзди, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2680669025] = {
        ["english"] = { [1] = "You need to be exalted with the night elves of Darnassus before I will teach you a riding skill, $c." },
        ["text"] = "Ти маєш бути звеличеним серед нічних ельфів Дарнаса, перш ніж я навчу тебе верхової їзди, $c.",
        ["npcs"] = { [1] = 4753 },
        ["roles"] = { ["greeting"] = true },
    },
    [3435335353] = {
        ["english"] = { [1] = "Your understanding of leather is deeper than my own. Perhaps you should visit the tauren Krulmoo Fullmoon in Camp Taurajo of the Barrens. He has much knowledge to offer a student of your talents." },
        ["text"] = "Твоє розуміння шкіри глибше за моє. Можливо, тобі варто навідати таурена Крулму Повний Місяць у таборі Таурахо в Степах. Він має чимало знань для учня з такими талантами.",
        ["npcs"] = { [1] = 5784 },
        ["roles"] = { ["greeting"] = true },
    },
    [3433238295] = {
        ["english"] = { [1] = "Your stench will attract every dragon for miles.  Tell me what you want, and quickly." },
        ["text"] = "Твій сморід приманить усіх драконів на багато миль довкола. Кажи, чого хочеш, і швидше.",
        ["npcs"] = { [1] = 7867 },
        ["roles"] = { ["greeting"] = true },
    },
    [1188916851] = {
        ["english"] = { [1] = "Your skills in alchemy aren't yet high enough to benefit from my teachings.  Perhaps if you speak with me later..." },
        ["text"] = "Твої алхімічні навички ще недостатньо високі, щоб мої уроки були корисними. Може, поговориш зі мною пізніше...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1712228688] = {
        ["english"] = { [1] = "You have made our enemies your own.  I will gladly share waters with you." },
        ["text"] = "Ти зробив наших ворогів своїми. Я з радістю поділюся з тобою водою.",
        ["npcs"] = { [1] = 13322 },
        ["roles"] = { ["greeting"] = true },
    },
    [1821948793] = {
        ["english"] = { [1] = "Your skills are truly becoming extraordinary. Now, let us continue your training..." },
        ["text"] = "Твої вміння справді стають надзвичайними. А тепер продовжімо навчання...",
        ["npcs"] = { [1] = 11072 },
        ["roles"] = { ["greeting"] = true },
    },
    [2760787322] = {
        ["english"] = { [1] = "You don't yet have the skill to study with me. Go talk to Doctor Martin Felben over there, or go up the ramp to the southeast and see Doctor Marsh. They are Forsaken who can give you the training you need." },
        ["text"] = "Твоїх умінь ще недостатньо, щоб навчатися в мене. Поговори з доктором Мартіном Фелбеном, он там, або піднімися рампою на південний схід і знайди доктора Марша. Вони Відречені й можуть навчити тебе необхідного.",
        ["npcs"] = { [1] = 4611 },
        ["roles"] = { ["greeting"] = true },
    },
    [3600745102] = {
        ["english"] = { [1] = "Your skills are coming along nicely. Soon you'll be running a leather shop of your own. I'll be glad for the help, $N. My hands are only so fast, you know? There's so much work to do!" },
        ["text"] = "Твої навички добре розвиваються. Скоро й власну шкіряну крамницю відкриєш. Я буду радий допомозі, $N. У мене ж лише дві руки, знаєш? Роботи так багато!",
        ["npcs"] = { [1] = 5127 },
        ["roles"] = { ["greeting"] = true },
    },
    [618031035] = {
        ["english"] = { [1] = "You do not have enough reputation with or have not pledged allegiance to The Aldor." },
        ["text"] = "Твоя репутація серед Алдорів недостатня або ти не присягнув їм на вірність.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4038570533] = {
        ["english"] = { [1] = "Your skill at brewing potions needs to be greater before you can become one of my students. In the meantime, perhaps Sylvanna Forestmoon or Milla Fairancora can help you, just over there." },
        ["text"] = "Твоє вміння варити зілля ще замале, щоб стати моїм учнем. Тим часом, можливо, Сильванна Лісовий Місяць або Мілла Фейранкора зможуть допомогти — вони он там.",
        ["npcs"] = { [1] = 4160 },
        ["roles"] = { ["greeting"] = true },
    },
    [782838288] = {
        ["english"] = { [1] = "Your search is almost completed.  Seek your truth in the entrance room of Thrall's Fortress in the Valley of Wisdom." },
        ["text"] = "Твої пошуки майже завершено. Шукай істину у вхідній залі фортеці Тралла в Долині Мудрості.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1724483212] = {
        ["english"] = { [1] = "You wish to aid The Defilers in their fight against The League of Arathor in Arathi Basin?  Very well, you should ask Martin Lindsey for his assistance then.  Look for him in the Pools of Vision." },
        ["text"] = "Хочеш допомогти Осквернителям у боротьбі проти Ліги Аратора в Низині Араті? Гаразд, тоді звернися по допомогу до Мартіна Ліндсі. Шукай його в Озерах Видіння.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [9124855] = {
        ["english"] = { [1] = "You will listen to this, vile duke!  I am not your Twilight's Hammer lapdog!  I am here to challenge you!  Come!  Come, and meet your death..." },
        ["text"] = "Слухай сюди, мерзенний герцогу! Я не пес на побігеньках Сутінкового Молота! Я прийшов кинути тобі виклик! Виходь! Виходь назустріч своїй смерті...",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3649674075] = {
        ["english"] = { [1] = "Your help was invaluable, my friend.$B$BI can assure you that the Cenarion Expedition will do everything in its power to counter any future tainted crystals dropped from the heavens by Illidan." },
        ["text"] = "Твоя допомога була безцінною, друже.$B$BЗапевняю, Кенарійська експедиція зробить усе можливе, щоб протистояти будь-яким майбутнім оскверненим кристалам, які Іллідан скидатиме з небес.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1222528840] = {
        ["english"] = { [1] = "Your presence here is interfering with very important work. Please leave at once. Where was I, again?" },
        ["text"] = "Твоя присутність заважає дуже важливій роботі. Будь ласка, негайно піди. На чому я зупинився?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4016398359] = {
        ["english"] = { [1] = "Your potion-making skills are beyond mine. Seek out the undead Doctor Herbert Halsey in the Apothecarium of the Undercity. He has the skill to train you further, and you can witness firsthand his people's plight." },
        ["text"] = "Твоє вміння варити зілля перевищило моє. Знайди невмерлого доктора Герберта Галсі в Аптекаріумі Підміста. Його знань вистачить, щоб навчати тебе далі, а заодно на власні очі побачиш становище його народу.",
        ["npcs"] = { [1] = 3009 },
        ["roles"] = { ["greeting"] = true },
    },
    [1186614753] = {
        ["english"] = { [1] = "Your next choice awaits.$B$BYou are the sworn executioner for your liege.  A man has been sent to you for execution as a traitor of the liege and your people.  You know this individual as a close, virtuous friend who mysteriously vanished one day.  You also know that the man's crimes for which he was convicted supposedly caused the deaths of many innocent civilians.  Upon seeing you he begs for his life, claiming he was framed by a higher authority.$B$BMake your choice.\010\010" },
        ["text"] = "На тебе чекає наступний вибір.$B$BТи присягнув бути катом свого сюзерена. До тебе привели чоловіка на страту як зрадника сюзерена й твого народу. Ти знаєш його як близького й чесного друга, який одного дня таємниче зник. Також тобі відомо, що злочини, за які його засудили, нібито спричинили смерть багатьох невинних мирних жителів. Побачивши тебе, він благає про життя й стверджує, що його підставила вища влада.$B$BЗроби свій вибір.\010\010",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["greeting"] = true },
    },
    [3949381095] = {
        ["english"] = { [1] = "Your next choice awaits.$B$BYou are on a diplomatic mission for your liege to a cruel country that is currently at war with yours.  The war has been costly on both sides.  Your mission is to secure a peace that is honorable to both peoples.$B$BAt a diplomatic dinner, you overhear the ruler of the opposing land viciously insult your benevolent liege.  You are fairly certain the ruler meant to say it out of your earshot, but nonetheless he has besmirched your liege's honor.$B$BMake your choice.\010\010\010" },
        ["text"] = "На тебе чекає наступний вибір.$B$BТи виконуєш дипломатичну місію свого сюзерена в жорстокій країні, яка нині воює з твоєю. Війна дорого коштує обом сторонам. Твоя мета — домогтися миру, почесного для обох народів.$B$BПід час дипломатичної вечері ти випадково чуєш, як правитель ворожої країни жорстоко ображає твого доброзичливого сюзерена. Ти майже певен, що він сказав це, думаючи, що ти не почуєш, але честь твого сюзерена все одно заплямована.$B$BЗроби свій вибір.\010\010\010",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["greeting"] = true },
    },
    [3208610321] = {
        ["english"] = { [1] = "Your name is beginning to be revered around here.$B$B<Chu'a'lor's left eye pierces you with its stony gaze.>$B$BKeep up the good work, $N!" },
        ["text"] = "Твоє ім'я тут починають вимовляти з пошаною.$B$B<Ліве око Чу'а'лора пронизує тебе кам'яним поглядом.>$B$BТак тримати, $N!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3367160100] = {
        ["english"] = { [1] = "You're looking for Lau'Tiki.  You'll find him on Darkspear Strand out beyond Sen'jin Village to the south." },
        ["text"] = "Шукаєш Лау'Тікі. Знайдеш його на узбережжі Темносписа, за селищем Сен'джин на південь.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [3241758058] = {
        ["english"] = { [1] = "Your knowledge is great, traveler. You must learn from one who is wiser than I. Many tales have been told of the wisdom of Josef Gregorian. You may find him in Undercity." },
        ["text"] = "Твої знання великі, мандрівнику. Тобі треба вчитися в мудрішого за мене. Про мудрість Йозефа Ґреґоріана ходить багато історій. Знайдеш його в Підмісті.",
        ["npcs"] = { [1] = 3704 },
        ["roles"] = { ["greeting"] = true },
    },
    [610909698] = {
        ["english"] = { [1] = "You're a $T civilian : civilian;?" },
        ["text"] = "Ти $T цивільний : цивільний;?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2055690108] = {
        ["english"] = { [1] = "You learn quickly, that is not a bad thing. Just be sure to do the job right, as long as it takes to do so. Now, I fear I must send you to Snarl to learn more. Learn what he can teach, but do not listen to his angry words. He gets that way when Saru's daughters laugh at him." },
        ["text"] = "Ти швидко вчишся, і це непогано. Лише стеж, щоб робота була зроблена як слід, скільки б часу не знадобилося. А тепер, боюся, доведеться послати тебе до Снарла вчитися далі. Вивчи все, чого він може навчити, але не зважай на його сердиті слова. Він завжди такий, коли доньки Сару з нього сміються.",
        ["npcs"] = { [1] = 10266 },
        ["roles"] = { ["greeting"] = true },
    },
    [3758261443] = {
        ["english"] = { [1] = "You guide the spirits in the steel to protect and defend with far more skill than I ever could. The student has surpassed the teacher and now I must send you to where your education may continue. $N, you must seek out Shayis Steelfury in Orgrimmar. She is the finest Armorsmith I have ever known, and she can teach you much." },
        ["text"] = "Ти направляєш духів у сталі для захисту й оборони значно майстерніше, ніж я коли-небудь міг. Учень перевершив учителя, і тепер я мушу послати тебе туди, де навчання продовжиться. $N, знайди Шайїс Сталелють в Орґріммарі. Вона найкраща бронниця, яку я знав, і може багато чого тебе навчити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [454106480] = {
        ["english"] = { [1] = "You wish to help the Forsaken with their fight against the humans in Arathi Basin?  Then go to the Hall of the Brave and speak with Deze Snowbane." },
        ["text"] = "Хочеш допомогти Відреченим у боротьбі з людьми в Низині Араті? Тоді йди до Зали Хоробрих і поговори з Дезе Снігобійкою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3578948770] = {
        ["english"] = { [1] = "Your education is nearly complete. One final task is all that stands between you and the culmination of all your efforts." },
        ["text"] = "Твоє навчання майже завершене. Лише одне останнє завдання відділяє тебе від вершини всіх твоїх зусиль.",
        ["npcs"] = { [1] = 11073 },
        ["roles"] = { ["greeting"] = true },
    },
    [3351816385] = {
        ["english"] = { [1] = "You've already learned everything I can teach you, $N. Talk to the night elf Lilyssia Nightbreeze in the Mage Quarter of Stormwind if you want to continue your studies. I hear she's a good teacher." },
        ["text"] = "Ти вже вивчив усе, чого я можу навчити, $N. Якщо хочеш продовжити навчання, поговори з нічною ельфійкою Ліліссією Нічним Вітром у Кварталі магів Штормовію. Кажуть, вона добра наставниця.",
        ["npcs"] = { [1] = 1215 },
        ["roles"] = { ["greeting"] = true },
    },
    [3319948578] = {
        ["english"] = { [1] = "Your current aptitude exceeds my instructional capabilities. You should enquire further with my fellow Gnome Trixie Quickswitch in Ironforge!" },
        ["text"] = "Твоя нинішня майстерність перевищує мої можливості як наставника. Звернися до моєї співвітчизниці-гномки Тріксі Швидкоперемикач у Залізогарті!",
        ["npcs"] = { [1] = 3290 },
        ["roles"] = { ["greeting"] = true },
    },
    [1314879208] = {
        ["english"] = { [1] = "Your confidence is well-founded, traveler. Now your true education may begin!" },
        ["text"] = "Твоя впевненість має підстави, мандрівнику. Тепер може початися справжнє навчання!",
        ["npcs"] = { [1] = 1317 },
        ["roles"] = { ["greeting"] = true },
    },
    [2492801181] = {
        ["english"] = { [1] = "Your choice has been made. Whether you live or die by that choice is now up to you." },
        ["text"] = "Свій вибір ти зробив. Чи житимеш, чи помреш через нього — тепер залежить від тебе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [601376543] = {
        ["english"] = { [1] = "You're not bad, but let me show you a few tricks you might find handy. " },
        ["text"] = "Непогано, але дозволь показати кілька прийомів, які можуть стати в пригоді.",
        ["npcs"] = { [1] = 957 },
        ["roles"] = { ["greeting"] = true },
    },
    [2452087972] = {
        ["english"] = { [1] = "Your bondage is at an end, Doom'rel.  I challenge you!", [2] = "Your bondage is at an end, Doom'rel. I challenge you!" },
        ["text"] = "Твоїм кайданам кінець, Дум'рел. Я кидаю тобі виклик!",
        ["npcs"] = { [1] = 9039 },
        ["roles"] = { ["reply"] = true },
    },
    [326768818] = {
        ["english"] = { [1] = "Your body looks worn and your spirit weary. Rest yourself beneath our roof and allow Elune to guide your dreams." },
        ["text"] = "Твоє тіло змучене, а дух виснажений. Відпочинь під нашим дахом і дозволь Елуні вести твої сни.",
        ["npcs"] = { [1] = 6735, [2] = 6736, [3] = 6737, [4] = 6738, [5] = 7736, [6] = 11103, [7] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2101848232] = {
        ["english"] = { [1] = "Your assistance fighting the Burning Legion would be most appreciated. Lady Jaina Proudmoore could use your help on the front lines." },
        ["text"] = "Ми були б дуже вдячні за твою допомогу в боротьбі з Палаючим Легіоном. Пані Джайна Праудмур потребує допомоги на передовій.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1892434260] = {
        ["english"] = { [1] = "You put the piece on a minnow and placed the minnow somewhere in the waters of the sea between here and the Eastern Kingdoms? And this minnow has special powers?" },
        ["text"] = "Ти поклав уламок на малька й випустив малька десь у морі між цим місцем і Східними Королівствами? І цей мальок має особливі сили?",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["reply"] = true },
    },
    [1932048726] = {
        ["english"] = { [1] = "Your armor looks scary.  Are you scary too?" },
        ["text"] = "Твій обладунок лякає. А ти теж страшний?",
        ["npcs"] = { [1] = 14444 },
        ["roles"] = { ["greeting"] = true },
    },
    [994002926] = {
        ["english"] = { [1] = "You look in The Apothecarium.  That where Doctor Herbert Halsey and Doctor Marsh practice." },
        ["text"] = "Шукай в Аптекаріумі. Там працюють доктор Герберт Галсі й доктор Марш.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3531706854] = {
        ["english"] = { [1] = "You know, $N, it's such an honor to work with you!$B$BWhen you're not busy wrangling, maybe we could $g go out some place for dinner? : get together for a girl's night?;$B$BOh, did I mention that we can now get you to our base in the Skethyl Mountains real quick?  If you want, speak with Skyguard Handler Irena about that." },
        ["text"] = "Знаєш, $N, для мене така честь працювати з тобою!$B$BКоли не будеш зайнятий приборканням, може, ми могли б $g сходити кудись повечеряти? : влаштувати дівочі посиденьки?;$B$BОй, я згадувала, що тепер можемо дуже швидко доставити тебе на нашу базу в горах Скеттіс? Якщо хочеш, поговори з наглядачкою Небесної Варти Іреною.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [374631114] = {
        ["english"] = { [1] = "You've started down an honorable path, $N. My ancestors respect your willingness, but you will not have my approval until you have followed through with my tasks.$B$BYou know what you must do if you wish to prove yourself a hunter in spirit." },
        ["text"] = "Ти ступив на шлях честі, $N. Мої предки шанують твою готовність, але мого схвалення не буде, доки ти не завершиш мої завдання.$B$BТи знаєш, що мусиш зробити, якщо хочеш довести, що в душі ти мисливець.",
        ["npcs"] = { [1] = 9619 },
        ["roles"] = { ["greeting"] = true },
    },
    [3193863852] = {
        ["english"] = { [1] = "You've reached an Alliance bonfire! Desecrate this bonfire and stamp it out!" },
        ["text"] = "Ти дістався багаття Альянсу! Оскверни його й затопчи!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1068794460] = {
        ["english"] = { [1] = "You've not had a steed until you've taken the reigns of a finely bred Barak Tor'ol mountain ram, my friend.  Please, feel free to inspect these fine companions to any adventurer.  They'll serve you well, believe me." },
        ["text"] = "Ти ще не знаєш справжнього скакуна, доки не візьмеш повіддя добірного гірського барана Барак Тор'ола, друже. Оглянь цих чудових супутників для будь-якого шукача пригод. Повір, вони служитимуть тобі вірою й правдою.",
        ["npcs"] = { [1] = 1261 },
        ["roles"] = { ["greeting"] = true },
    },
    [4021771939] = {
        ["english"] = { [1] = "You are beyond my limited abilities. Seek out the night elf Ainethil in the Craftsmen's Terrace of Darnassus. She can teach you more. I only wish that I could go with you." },
        ["text"] = "Моїх скромних знань тобі вже замало. Знайди нічну ельфійку Айнетіль на Ремісничій терасі в Дарнасі. Вона навчить тебе більшого. Хотіла б я піти з тобою.",
        ["npcs"] = { [1] = 5499 },
        ["roles"] = { ["greeting"] = true },
    },
    [1203006947] = {
        ["english"] = { [1] = "You can count on me, Hero." },
        ["text"] = "На мене можна покластися, Герою.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["reply"] = true },
    },
    [3942065919] = {
        ["english"] = { [1] = "You can fill a bucket at the water barrel.  It's fun to splash!" },
        ["text"] = "Можеш набрати відро біля бочки з водою. Хлюпатися весело!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3221342059] = {
        ["english"] = { [1] = "You've proven yourself a very capable game hunter, $N.  But there's still one beastie that haunts your dreams... Tusker!" },
        ["text"] = "Ти довів, що чудово полюєш на дичину, $N. Але є ще один звір, який досі приходить тобі в кошмарах... Бивняр!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2219830076] = {
        ["english"] = { [1] = "You have completed Teronis' mission, and I appreciate all you have done, $N." },
        ["text"] = "Ти виконав завдання Тероніса, і я вдячний за все, що ти зробив, $N.",
        ["npcs"] = { [1] = 3691 },
        ["roles"] = { ["greeting"] = true },
    },
    [219935279] = {
        ["english"] = { [1] = "You've made a good start, but you still have a great deal to learn, $N." },
        ["text"] = "Початок добрий, але тобі ще дуже багато чого вчитися, $N.",
        ["npcs"] = { [1] = 1215 },
        ["roles"] = { ["greeting"] = true },
    },
    [1636283139] = {
        ["english"] = { [1] = "You can do this alone, you say? Is this simple foolishness or misplaced confidence I see before me?$B$BNo, I can see it in your eyes. You have to know. You have to prove to yourself that you can do this alone. Very well. I will retreat from the battlefield if you so wish it." },
        ["text"] = "Кажеш, упораєшся самотужки? Це просто дурість чи недоречна самовпевненість, що я бачу перед собою?$B$BНі, я бачу це в твоїх очах. Тобі треба знати. Треба довести самому собі, що ти здатен упоратися один. Гаразд. Якщо так хочеш, я залишу поле бою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1489809239] = {
        ["english"] = { [1] = "You've got the hang of it. I can't teach you any more, but talk to Arthur Moore, a Forsaken who works in the Rogues' Quarter of the Undercity. Tell him I sent you." },
        ["text"] = "Ти вже набив руку. Більше я тебе нічого не навчу, але поговори з Артуром Муром, Відреченим, який працює в Кварталі розбійників Підміста. Скажи, що це я тебе прислав.",
        ["npcs"] = { [1] = 223, [2] = 3549 },
        ["roles"] = { ["greeting"] = true },
    },
    [4159147627] = {
        ["english"] = { [1] = "You've got more guts than brains, coming to me without the proper training. Go talk to somebody closer to your skill level, like the orc Kamari, who lives in the Drag of Orgrimmar." },
        ["text"] = "У тебе більше відваги, ніж розуму, якщо приходиш до мене без належної підготовки. Поговори з кимось ближчим до твого рівня, наприклад з орком Камарі, що живе в Хитрому провулку Орґріммара.",
        ["npcs"] = { [1] = 1385 },
        ["roles"] = { ["greeting"] = true },
    },
    [544830868] = {
        ["english"] = { [1] = "You've done us exemplary service, $N. Between dealing with the gnolls at the Underlight Mines, and the mummified trolls in the Amani Catacombs, you've dealt a mighty blow to our enemies!$B$B$G Good job! : We should get together for drinks sometime, what do you say?;" },
        ["text"] = "Ти служив нам зразково, $N. Між розправою над ґнолами в копальнях Підсвіття та муміфікованими тролями в катакомбах Амані ти завдав нашим ворогам потужного удару!$B$B$G Чудова робота! : Нам варто якось випити разом, що скажеш?;",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [648976990] = {
        ["english"] = { [1] = "You've done all that I've asked you to do, $N. There's really nothing more here for you. If you are interested in continuing your career as an agent of the Thorium Brotherhood, speak with Lokhtos Darkbargainer at the Grim Guzzler in Blackrock Depths.$B$BFarewell!" },
        ["text"] = "Ти виконав усе, про що я просив, $N. Тут для тебе більше нічого немає. Якщо хочеш продовжити кар'єру агента Братства Торію, поговори з Локтосом Темним Торгівцем у «Похмурому Пияку» в Глибинах Чорнокамінної гори.$B$BПрощавай!",
        ["npcs"] = { [1] = 14624 },
        ["roles"] = { ["greeting"] = true },
    },
    [4135143516] = {
        ["english"] = { [1] = "You've come for training in order to pass it on to your pets?" },
        ["text"] = "Ти прийшов на навчання, щоб потім передати знання своїм вихованцям?",
        ["npcs"] = { [1] = 543, [2] = 2878, [3] = 2879, [4] = 3306, [5] = 3545, [6] = 3620, [7] = 3622, [8] = 3624, [9] = 3688, [10] = 3698, [11] = 4320, [12] = 10086, [13] = 10088, [14] = 10089, [15] = 10090 },
        ["roles"] = { ["greeting"] = true },
    },
    [4085163459] = {
        ["english"] = { [1] = "You've been summoned by Lago Blackwrench, warlock master of Ironforge. You'd do yourself well to report to him immediately. You'll find him in the Forlorn Cavern district of the city." },
        ["text"] = "Тебе викликає Лаґо Чорний Ключ, майстер чорнокнижників Залізогарта. Раджу негайно з'явитися до нього. Знайдеш його в районі Закинутої печери.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [85257722] = {
        ["english"] = { [1] = "You are not known to my people.  A kodo is a mighty steed, and it is the product of love and care by my people; such is not given onto strangers.  Until the elders of Thunder Bluff consider you to be exalted, I cannot offer you the sale of a kodo." },
        ["text"] = "Мій народ тебе не знає. Кодо — могутній скакун, вирощений любов'ю та турботою мого народу; чужинцям таких не дають. Поки старійшини Громового Бескиду не вважатимуть тебе звеличеним, я не зможу продати тобі кодо.",
        ["npcs"] = { [1] = 3685 },
        ["roles"] = { ["greeting"] = true },
    },
    [1286224282] = {
        ["english"] = { [1] = "You got the look of someone wantin' adventure. Me, I had enough of that by the time we trolls came here. Now I take each day as it comes, an' I train other folks to handle adventures for me." },
        ["text"] = "Виглядаєш як той, хто шукає пригод. Я ж ними наситився ще коли ми, тролі, прибули сюди. Тепер живу одним днем та навчаю інших розбиратися з пригодами замість мене.",
        ["npcs"] = { [1] = 3184 },
        ["roles"] = { ["greeting"] = true },
    },
    [2440563005] = {
        ["english"] = { [1] = "You not a real mon til you killed a dragon... mon." },
        ["text"] = "Ти не справжній чолов'яга, доки не вбив дракона... чолов'яга.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1206475955] = {
        ["english"] = { [1] = "You need to heed the guidance of the spirits a little better young one. Your path lies with another, Thrag Stonehoof in Thunder Bluff. Perhaps you can learn something from one another." },
        ["text"] = "Тобі варто уважніше дослухатися до настанов духів, юначе. Твій шлях веде до іншого — Траґа Кам'яного Копита в Громовому Бескиді. Можливо, ви зможете чогось навчитися один від одного.",
        ["npcs"] = { [1] = 3478 },
        ["roles"] = { ["greeting"] = true },
    },
    [826484112] = {
        ["english"] = { [1] = "You're telling me! It's even stranger considering between Brann, Rutgar, me and the monkey, we know 38 different languages including a touch of Titan - both Vanir and Aesir.$B$BSo anyway, whatever she was click clacking about, it definitely wasn't with anyone \"present.\" She then nodded and went on the offensive! Attacked us outright!" },
        ["text"] = "Ще й як! І це ще дивніше, якщо врахувати, що Бранн, Рутґар, я та мавпа разом знаємо 38 різних мов, навіть трохи титанської — і ванірської, і асірської.$B$BОтже, що б вона там не клацала, це точно було не до когось із «присутніх». Потім вона кивнула й пішла в наступ! Напала на нас без попередження!",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["greeting"] = true },
    },
    [2277464304] = {
        ["english"] = { [1] = "You're sweet for asking, $c, but we have all of the light leather that we need. May be that one of the others in charge of collecting around here is in need of your assistance though?" },
        ["text"] = "Мило, що питаєш, $c, але легкої шкіри нам уже вистачає. Можливо, комусь іншому з тих, хто тут займається збором, ще потрібна твоя допомога?",
        ["npcs"] = { [1] = 15446 },
        ["roles"] = { ["greeting"] = true },
    },
    [1296661420] = {
        ["english"] = { [1] = "You're selling cologne and perfume?" },
        ["text"] = "Ти продаєш одеколон і парфуми?",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [3815012406] = {
        ["english"] = { [1] = "You mean..." },
        ["text"] = "Ти хочеш сказати...",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [3341802274] = {
        ["english"] = { [1] = "You mess with Silas, you mess with me.  Have a nice day." },
        ["text"] = "Зачепиш Сайласа — матимеш справу зі мною. Гарного дня.",
        ["npcs"] = { [1] = 14827 },
        ["roles"] = { ["greeting"] = true },
    },
    [1649340608] = {
        ["english"] = { [1] = "You look like the type I should watch my coin purse around. Something I can help you with?" },
        ["text"] = "У тебе такий вигляд, що біля тебе варто триматися за гаманець. Чимось допомогти?",
        ["npcs"] = { [1] = 915, [2] = 916, [3] = 918, [4] = 1411, [5] = 13283 },
        ["roles"] = { ["greeting"] = true },
    },
    [1251979949] = {
        ["english"] = { [1] = "You're no Scourge. What you doin' here, mon?" },
        ["text"] = "Ти не Скверна. Чого ти тут, чолов'яга?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [999753059] = {
        ["english"] = { [1] = "You're looking for Urtrun Clanbringer in the Horde Embassy.  Find it on the west side of the Valley of Strength." },
        ["text"] = "Шукаєш Уртруна Кланоносця в Посольстві Орди. Воно на західному боці Долини Сили.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [290736595] = {
        ["english"] = { [1] = "You're looking for Tai'jin.  Find her in the barracks on the east side of town." },
        ["text"] = "Шукаєш Тай'джин. Знайди її в казармах на східному боці міста.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [2863485330] = {
        ["english"] = { [1] = "Your mind is unfocused.  Are you hiding something from me?" },
        ["text"] = "Твій розум не зосереджений. Ти щось від мене приховуєш?",
        ["npcs"] = { [1] = 10433 },
        ["roles"] = { ["greeting"] = true },
    },
    [961374465] = {
        ["english"] = { [1] = "You're just in time, $c.  Do you feel the ground shaking beneath you?$B$BSomething approaches from the hive.  Take a place near the grunts, $N.  I'm counting on you!" },
        ["text"] = "Ти саме вчасно, $c. Відчуваєш, як під ногами тремтить земля?$B$BЩось наближається з вулика. Стань біля рубак, $N. Я на тебе розраховую!",
        ["npcs"] = { [1] = 15612 },
        ["roles"] = { ["greeting"] = true },
    },
    [4098689291] = {
        ["english"] = { [1] = "You clearly lack the capacity to grasp the intricacies of the arcane, $c. Off with you." },
        ["text"] = "Тобі явно бракує здібностей, щоб осягнути тонкощі аркани, $c. Іди геть.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [320703085] = {
        ["english"] = { [1] = "You're joking, right? I believe you're looking for the OTHER short fellow, Thonys Pillarstone. He's downstairs. Now skedaddle!" },
        ["text"] = "Ти жартуєш, так? Думаю, тобі потрібен ІНШИЙ низенький чоловік — Тоніс Кам'яний Стовп. Він унизу. А тепер гайда!",
        ["npcs"] = { [1] = 5157 },
        ["roles"] = { ["greeting"] = true },
    },
    [2625481684] = {
        ["english"] = { [1] = "You're into leather, eh?  Sounds like you should talk to Simon Tanner over in Old Town.  He runs a shop there called the Protective Hide." },
        ["text"] = "Працюєш зі шкірою, еге ж? Тоді тобі варто поговорити із Саймоном Дубильником у Старому місті. Він тримає там крамницю «Захисна Шкура».",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2679457223] = {
        ["english"] = { [1] = "You're good for nothing, Ribbly.  It's time to pay for your wickedness!" },
        ["text"] = "Ти ні на що не годишся, Рібблі. Час відповісти за свою підлість!",
        ["npcs"] = { [1] = 9543 },
        ["roles"] = { ["reply"] = true },
    },
    [2989376308] = {
        ["english"] = { [1] = "You're back already!  What can I do for you now?" },
        ["text"] = "Уже повернувся! Чим допомогти цього разу?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3755733661] = {
        ["english"] = { [1] = "You can usually find Brother Wilhelm in back of the smithy trading stories with Lyria.  He's always up for teaching fellow paladins new skills." },
        ["text"] = "Брата Вільгельма зазвичай знайдеш позаду кузні, де він перекидається байками з Лірією. Він завжди радий навчити інших паладинів нових умінь.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [2051810720] = {
        ["english"] = { [1] = "You're a young hatchling aren't you?  My eyes fail me.$B$BI assume you're here to purchase one of my exotic texts?" },
        ["text"] = "Ти ще зовсім юний пташеня, еге ж? Очі вже підводять.$B$BПрипускаю, ти прийшов придбати один із моїх екзотичних текстів?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [381530179] = {
        ["english"] = { [1] = "You're a sight for sore eyes! I'm too weak to break the links on this rusty ball and chain.$B$BWell, don't just stand there! Get me loose!" },
        ["text"] = "Яке полегшення тебе бачити! Я надто слабкий, щоб розірвати ланки цього іржавого ядра з ланцюгом.$B$BНу не стій стовпом! Звільни мене!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1077001662] = {
        ["english"] = { [1] = "You'll find that goblin and his toy shop in the Valley of Honor." },
        ["text"] = "Того гобліна й його крамницю іграшок знайдеш у Долині Честі.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [727942151] = {
        ["english"] = { [1] = "Your fortune is cast, $c.  For the next few hours, you will find your spirit in tune with your true nature.  Be careful, as your fortune - and your fate - are never as clear as you might think them to be.$B$BIf you would like a small glimpse of something to ponder in your future, by all means let me know.  I'd be happy to give you a written fortune, provided you have room in your inventory.  It is one drawn from the insight you have shown in answering my questions." },
        ["text"] = "Твою долю визначено, $c. Наступні кілька годин твій дух буде в гармонії з твоєю справжньою природою. Будь обережним: твоє передбачення — і твоя доля — ніколи не такі ясні, як може здаватися.$B$BЯкщо хочеш невеличкий натяк, над яким можна поміркувати про майбутнє, просто скажи. Я із задоволенням дам тобі письмове пророцтво, якщо в наплічнику є місце. Воно ґрунтується на проникливості, яку ти виявив у відповідях на мої запитання.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["greeting"] = true },
    },
    [1515281826] = {
        ["english"] = { [1] = "Ysida lives thanks to your courage, $N.  I am deeply in your debt and shall assist you as much as it is in my power." },
        ["text"] = "Ісіда живе завдяки твоїй відвазі, $N. Я глибоко перед тобою в боргу й допомагатиму настільки, наскільки стане моїх сил.",
        ["npcs"] = { [1] = 16016 },
        ["roles"] = { ["greeting"] = true },
    },
    [1886983044] = {
        ["english"] = { [1] = "You'll need more training before I can share my knowledge with you, I'm afraid." },
        ["text"] = "Боюся, тобі потрібно ще потренуватися, перш ніж я зможу поділитися своїми знаннями.",
        ["npcs"] = { [1] = 1346 },
        ["roles"] = { ["greeting"] = true },
    },
    [4189999465] = {
        ["english"] = { [1] = "You'll have to be patient with me, $N. I've got my Spybot inside working on a very delicate matter. I'll be with ya in a second.$B$BOh, and do me a favor, try not to let Lescovar see you... we're about to ambush him." },
        ["text"] = "Доведеться трохи зачекати, $N. Мій Шпигобот усередині працює над дуже делікатною справою. Я буду за мить.$B$BІ зроби мені послугу: постарайся, щоб Лесковар тебе не побачив... ми якраз збираємося влаштувати йому засідку.",
        ["npcs"] = { [1] = 7766 },
        ["roles"] = { ["greeting"] = true },
    },
    [3925145538] = {
        ["english"] = { [1] = "Yer skill is not without merit, but I need to put one last test to ye before I take ye on." },
        ["text"] = "Твоя вправність не позбавлена гідності, але перш ніж я візьмуся тебе навчати, треба пройти ще одне випробування.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [263712772] = {
        ["english"] = { [1] = "You feel a strange presence as you stand before this ancient idol." },
        ["text"] = "Стоячи перед цим стародавнім ідолом, ти відчуваєш дивну присутність.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2412120078] = {
        ["english"] = { [1] = "You'll find the battlemasters in the war room of Stormwind Keep." },
        ["text"] = "Розпорядників бою знайдеш у військовій кімнаті фортеці Штормовію.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [4197586809] = {
        ["english"] = { [1] = "Yes I am." },
        ["text"] = "Так, це я.",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["reply"] = true },
    },
    [3503134513] = {
        ["english"] = { [1] = "You're a leatherworker by trade, aren't you?  It's that faint smell of cured hides, I'd recognize it anywhere.$B$BMy father used to talk about a famous artisan who lived in Southwind Village centuries ago.  It's a shame the place is in ruins now." },
        ["text"] = "Ти ж шкіряник за ремеслом, правда? Цей легкий запах вичинених шкур я впізнаю будь-де.$B$BМій батько розповідав про славетного майстра, який століття тому жив у селищі Південного Вітру. Шкода, що тепер від нього лишилися руїни.",
        ["npcs"] = { [1] = 15174 },
        ["roles"] = { ["greeting"] = true },
    },
    [3851282584] = {
        ["english"] = { [1] = "You'll be purchasing no hawkstrider here until you've proven your worth and dedication to our people.$bDo not return until you are considered exalted among the blood elves. Away with you!" },
        ["text"] = "Ніякого яструбодоліта ти тут не купиш, доки не доведеш свою цінність і відданість нашому народові.$bНе повертайся, доки не станеш звеличеним серед ельфів крові. Геть!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1001114739] = {
        ["english"] = { [1] = "You'll be after Benik Boltshear, then. He's located in the heart of the Dwarven District by the blacksmiths." },
        ["text"] = "Тоді тобі потрібен Бенік Болтозріз. Він у самому серці Дворфівського району, біля ковалів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [282346034] = {
        ["english"] = { [1] = "You'd better get outta here unless you want to find yourself in one of these cages...." },
        ["text"] = "Краще забирайся звідси, якщо не хочеш сам опинитися в одній із цих кліток...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2930310645] = {
        ["english"] = { [1] = "You! Yes, you!$b$bGaze upon me and treasure this moment of meeting, for soon the world will come to know and fear the name and stern visage of Wilfred Fizzlebang! Once my magnificent summoning is complete, no one will doubt my ability!" },
        ["text"] = "Ти! Так, ти!$b$bДивись на мене й бережи цю мить нашої зустрічі, бо незабаром увесь світ знатиме й боятиметься імені та суворого обличчя Вілфреда Фізлбенґа! Коли моє величне викликання завершиться, ніхто більше не сумніватиметься в моїх здібностях!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1648744832] = {
        ["english"] = { [1] = "You would certainly be looking for Me'Lynn if you have any hope of learning to be a tailor.  She resides at the Craftsmen's Terrace in northeastern Darnassus." },
        ["text"] = "Якщо сподіваєшся навчитися кравецтва, тобі точно потрібна Ме'Лінн. Вона живе на Ремісничій терасі в північно-східній частині Дарнаса.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3518525554] = {
        ["english"] = { [1] = "You wish to speak to me, $r?" },
        ["text"] = "Хочеш поговорити зі мною, $r?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1393730626] = {
        ["english"] = { [1] = "You won't learn anything new from me; you know too much already. If you want more training, talk to the tauren Una in the northwestern shops of Thunder Bluff's central plateau. Send her my regards, eh?" },
        ["text"] = "Від мене ти вже нічого нового не навчишся — знаєш надто багато. Якщо хочеш продовжити навчання, поговори з тауренкою Уною в північно-західних крамницях центрального плато Громового Бескиду. Передай їй від мене вітання, гаразд?",
        ["npcs"] = { [1] = 3365 },
        ["roles"] = { ["greeting"] = true },
    },
    [3899651367] = {
        ["english"] = { [1] = "Yes, $t citizen : citizen;, what matter of import do you have to bring to my attention?" },
        ["text"] = "Так, $t громадянине : громадянине;, яку важливу справу маєш донести до моєї уваги?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2955526866] = {
        ["english"] = { [1] = "You won't find a finer firearm anywhere else in Orgrimmar." },
        ["text"] = "Кращої вогнепальної зброї в усьому Орґріммарі не знайдеш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1232499531] = {
        ["english"] = { [1] = "You won't find a better brew in Azeroth." },
        ["text"] = "Кращого пива в Азероті не знайдеш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [189751418] = {
        ["english"] = { [1] = "You will stage a series of events that will lead the Kil'sorrow orcs of Kil'sorrow Fortress to believe that the Warmaul ogres have attacked their base and then another series of events to make the Warmaul ogres believe the Kil'sorrow orcs are attacking their base.$B$BDo this and you solve both of our problems.$B$BThe Boulderfist will have their territory back and your people will be free from attack from Boulderfist, Warmaul and Shadow Council." },
        ["text"] = "Ти влаштуєш низку подій, після яких орки Кіл'сorrow із фортеці Кіл'сorrow повірять, що на їхню базу напали огри Бойового Молота, а потім іншу низку подій, щоб огри Бойового Молота повірили, ніби на їхню базу напали орки Кіл'сorrow.$B$BЗроби це — і розв'яжеш обидві наші проблеми.$B$BКулаки Валунів повернуть свою територію, а твій народ позбудеться нападів Кулаків Валунів, Бойового Молота й Ради Тіней.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1120362868] = {
        ["english"] = { [1] = "You will need more than bravery to defeat the Lich King. Good luck." },
        ["text"] = "Щоб перемогти Короля-ліча, самої відваги замало. Удачі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1111416791] = {
        ["english"] = { [1] = "You are fortunate to have come to Darnassus where you can find such an accomplished Hunter as Jocaste among our trainers.  I encourage you to visit her over in the Cenarion Enclave and seek her tutelage." },
        ["text"] = "Тобі пощастило опинитися в Дарнасі, де серед наших наставників є така досвідчена мисливиця, як Йокаста. Раджу навідатися до неї в Кенарійський анклав і попросити про навчання.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [1837321224] = {
        ["english"] = { [1] = "Your quest to learn Draconic is futile, mortal. And why would you ever want to learn to speak in the ancient tongue? Baffling really..." },
        ["text"] = "Твої спроби вивчити драконячу мову марні, смертний. І навіщо взагалі тобі говорити прадавньою мовою? Справді незбагненно...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3164876322] = {
        ["english"] = { [1] = "You were. The Eye is never wrong.$B$BYou are a $g priest:priestess;, after all. A powerful $g priest:priestess;, if the Eye showed you this horrible memory.$B$BYou have come for redemption, yet you yourself do not even realize this... Do you?" },
        ["text"] = "Так. Око ніколи не помиляється.$B$BЗрештою, ти $g жерцю:жрице;. І могутній $g жерцю:жрице;, якщо Око показало тобі цей жахливий спогад.$B$BТи прийшов по спокуту, але сам цього ще навіть не усвідомлюєш... правда?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [271660613] = {
        ["english"] = { [1] = "You were telling me about The Veiled Blade and how you took the wrong mission." },
        ["text"] = "Ти розповідав мені про Завуальований Клинок і про те, як узяв не те завдання.",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["reply"] = true },
    },
    [3464688395] = {
        ["english"] = { [1] = "You want to learn to be a tailor?  Hmmm... I believe there's a tailor over in the Eastvale Logging Camp that may be able to get you started.  " },
        ["text"] = "Хочеш стати кравцем? Гм... здається, у Лісозаготівельному таборі Східнодолу є кравець, який допоможе тобі почати.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [2343795294] = {
        ["english"] = { [1] = "You want to know about ration collections? Very well. Last I was told, the Horde had prepared $2095w out of $2096w lean wolf steaks. We've also packed away $2102w of $2103w spotted yellowtail and $2105w out of $2106w baked salmon needed." },
        ["text"] = "Хочеш знати про збір пайків? Гаразд. Наскільки мені відомо, Орда підготувала $2095w із $2096w пісних вовчих стейків. Також ми запакували $2102w із $2103w плямистих жовтохвостів і $2105w із потрібних $2106w запечених лососів.",
        ["npcs"] = { [1] = 15539 },
        ["roles"] = { ["greeting"] = true },
    },
    [1128649232] = {
        ["english"] = { [1] = "Zayus and his priests are in the Spirit Lodge, which is in the Valley of Spirits.  Look for it on the lake up above and to west of the Valley of Strength." },
        ["text"] = "Заюс і його жерці перебувають у Обителі Духів у Долині Духів. Шукай її біля озера, вище й на захід від Долини Сили.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1637819211] = {
        ["english"] = { [1] = "You turn the body over and see the marks from blades and spells upon the deceased orc--her armor all but destroyed, her hair matted to her face.$B$BBased on Mankrik's description of her, there is no doubt in your mind that this was his wife.$B$BHe will be upset by the news, but you are sure he should know the truth." },
        ["text"] = "Ти перевертаєш тіло й бачиш сліди клинків і заклять на мертвій орчині — її обладунок майже знищений, волосся прилипло до обличчя.$B$BЗа описом Манкріка сумнівів немає: це була його дружина.$B$BНовина його засмутить, але ти певен, що він має знати правду.",
        ["npcs"] = { [1] = 10668 },
        ["roles"] = { ["greeting"] = true },
    },
    [707467858] = {
        ["english"] = { [1] = "Yes, yes, all of the Horde's and Alliance's war materiel is being shipped over to Silithus and should be there within a day. Do you know what happens then, $c? We hurry up and wait. Hopefully someone is gathering the pieces of the Scepter of the Shifting Sands, because in order to open the gates of Ahn'Qiraj it needs to be rung against the gong on the Scarab Dais." },
        ["text"] = "Так-так, усі військові припаси Орди й Альянсу вже везуть до Силітуса, і вони мають прибути туди за день. Знаєш, що буде потім, $c? Будемо поспішати... щоб чекати. Сподіваюся, хтось уже збирає уламки Скіпетра Мінливих Пісків, бо щоб відкрити брами Ан'Кіражу, ним треба вдарити в гонг на Помості Скарабея.",
        ["npcs"] = { [1] = 15533 },
        ["roles"] = { ["greeting"] = true },
    },
    [1426900513] = {
        ["english"] = { [1] = "You think I'm being cruel to this worm?$B$BThey've killed two of my men this month!  We're too kind to this Wretched scum." },
        ["text"] = "Думаєш, я жорстокий із цим хробаком?$B$BЗа цей місяць вони вбили двох моїх людей! Ми надто добрі до цього покидька з Жалюгідних.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2306273353] = {
        ["english"] = { [1] = "You can find Tannysa standing outside Alchemy Needs in the Mage Quarter." },
        ["text"] = "Таннісу знайдеш біля крамниці «Алхімічні потреби» в Кварталі магів.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2838976339] = {
        ["english"] = { [1] = "You need to be exalted with the humans of Stormwind before I will teach you a riding skill, $c." },
        ["text"] = "Ти маєш бути звеличеним серед людей Штормовію, перш ніж я навчу тебе верхової їзди, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1575606122] = {
        ["english"] = { [1] = "You have certainly come a long way in your training. There is only one instructor who can train you further. Find Buzzek Bracketswing in Gadgetzan! " },
        ["text"] = "Ти й справді далеко просунувся у навчанні. Лише один наставник може навчити тебе більшого. Знайди Буззека Кронштейнокрила в Пристробляску!",
        ["npcs"] = { [1] = 5174 },
        ["roles"] = { ["greeting"] = true },
    },
    [612225540] = {
        ["english"] = { [1] = "Zando'zan of the Shattered Hand. How can Zando'zan help you? He can't! He won't!\010" },
        ["text"] = "Зандо'зан із Розтрощеної Долоні. Як Зандо'зан може допомогти? Ніяк! І не буде!\010",
        ["npcs"] = { [1] = 3402 },
        ["roles"] = { ["greeting"] = true },
    },
    [1217327995] = {
        ["english"] = { [1] = "You - come here. Are these blades not the finest quality? Surely you wish to purchase from me. You will not find such workmanship and care wrought into such weapons anywhere else, $r." },
        ["text"] = "Ти — сюди. Хіба ці клинки не найкращої якості? Авжеж, ти хочеш купувати саме в мене. Такої майстерності й турботи, вкладених у зброю, більше ніде не знайдеш, $r.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3590845955] = {
        ["english"] = { [1] = "You should talk to Winstone. I hear he's looking for thieves with your skill." },
        ["text"] = "Поговори з Вінстоном. Чув, він шукає злодіїв із такими вміннями, як у тебе.",
        ["npcs"] = { [1] = 6771 },
        ["roles"] = { ["greeting"] = true },
    },
    [1280583368] = {
        ["english"] = { [1] = "You seek the aid of a Druid?  Then you should go see Kal at the Moonwell just south of the Inn in Dolanaar." },
        ["text"] = "Шукаєш допомоги друїда? Тоді навідай Кала біля місячного колодязя просто на південь від заїзду в Доланаарі.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [4213300120] = {
        ["english"] = { [1] = "You've become quite the hunter, $N! Not only have you proven your skills, you also bested Daryl, which gets you extra points in my book!$B$BYou're welcome here any time." },
        ["text"] = "Ти став чудовим мисливцем, $N! Ти не лише довів свою майстерність, а й перевершив Деріла — за це від мене додаткові бали!$B$BТобі тут завжди раді.",
        ["npcs"] = { [1] = 1154 },
        ["roles"] = { ["greeting"] = true },
    },
    [2559652984] = {
        ["english"] = { [1] = "You seek a higher knowledge. Tepa is blessed with such knowledge. She should be standing somewhere nearby..." },
        ["text"] = "Ти прагнеш вищого знання. Тепа благословенна таким знанням. Вона має бути десь неподалік...",
        ["npcs"] = { [1] = 11051 },
        ["roles"] = { ["greeting"] = true },
    },
    [1027433625] = {
        ["english"] = { [1] = "You have learned much, more than I can teach. Go to James Van Brunt, he will teach you what I cannot." },
        ["text"] = "Ти багато чого навчився — більше, ніж я можу дати. Іди до Джеймса Ван Бранта, він навчить того, чого не можу я.",
        ["npcs"] = { [1] = 4605 },
        ["roles"] = { ["greeting"] = true },
    },
    [993829362] = {
        ["english"] = { [1] = "You see large cavernous tunnels and corridors reflected inside the crystal. You recognize the area as the Molten Core." },
        ["text"] = "У кристалі відбиваються величезні печерні тунелі й коридори. Ти впізнаєш це місце — Вогняні Надра.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3401289532] = {
        ["english"] = { [1] = "You Scourge not welcome in Zul'Drak!" },
        ["text"] = "Скверні не раді в Зул'Драку!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4264659840] = {
        ["english"] = { [1] = "Yes I do." },
        ["text"] = "Так.",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["reply"] = true },
    },
    [1094972089] = {
        ["english"] = { [1] = "You've heard about the Tram have you?  What a ride that thing is!  You'll find it in the Dwarven District towards the back.  Oh, and be sure to keep your arms and legs inside the tram while the tram is in motion." },
        ["text"] = "То ти чув про трамвай? Оце поїздка! Знайдеш його в глибині Дворфівського району. І не забувай тримати руки й ноги всередині вагона, поки трамвай рухається.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [292808652] = {
        ["english"] = { [1] = "You scared the fish away!  What do you want?" },
        ["text"] = "Ти розполохав рибу! Чого тобі?",
        ["npcs"] = { [1] = 4314 },
        ["roles"] = { ["greeting"] = true },
    },
    [473133512] = {
        ["english"] = { [1] = "You read wanted poster to Grek?$B$BGrek want to help!" },
        ["text"] = "Ти прочитати Ґреку плакат «Розшукується»?$B$BҐрек хоче допомогти!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3097737638] = {
        ["english"] = { [1] = "You not miss Armand Cromwell in Magic Quarter.  He stand on dock." },
        ["text"] = "Арманда Кромвелла в Кварталі магів не пропустиш. Він стоїть на причалі.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2283020867] = {
        ["english"] = { [1] = "You're welcome to stay at the Farstrider Enclave for as long as you'd like, $c.  We welcome any who would aid us in our endeavors in the Ghostlands." },
        ["text"] = "Можеш залишатися в анклаві Далекоходців стільки, скільки захочеш, $c. Ми раді кожному, хто допомагає нам у Примарнокраї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3997210620] = {
        ["english"] = { [1] = "You need to make your stitches smaller, $N. Fewer items will slip out of your quivers and ammo pouches. Besides, no one likes a lumpy tunic." },
        ["text"] = "Тобі треба робити менші стібки, $N. Тоді з твоїх сагайдаків і сумок для боєприпасів випадатиме менше речей. Та й горбата туніка нікому не подобається.",
        ["npcs"] = { [1] = 3605 },
        ["roles"] = { ["greeting"] = true },
    },
    [1430234770] = {
        ["english"] = { [1] = "You don't see too many apprentices around these parts, do you?  I'm beginning to think it's because the magisters give us all the dangerous work they'd rather not do themselves." },
        ["text"] = "Не надто багато учнів бачиш у цих краях, еге ж? Починаю думати, це тому, що магістри скидають на нас усю небезпечну роботу, яку самі не хочуть робити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2974545341] = {
        ["english"] = { [1] = "You know who's really smart? Nogg! Smarter than me, even. You go tell Nogg Thund sent you! You can find him by the control panel over there." },
        ["text"] = "Знаєш, хто справді розумний? Ноґґ! Навіть розумніший за мене. Скажи Ноґґу, що тебе прислав Тунд! Знайдеш його біля панелі керування, он там.",
        ["npcs"] = { [1] = 2857 },
        ["roles"] = { ["greeting"] = true },
    },
    [596102055] = {
        ["english"] = { [1] = "Yeah? Of course I'm a smith. What, you think Dwarves are the only ones worth their weight in anvils? Fine, be that way. Go get a dwarf to help you!" },
        ["text"] = "Так? Авжеж, я коваль. Що, думаєш, лише дворфи варті свого ковадла? Ну й гаразд. Іди тоді, нехай тобі допомагає дворф!",
        ["npcs"] = { [1] = 2836 },
        ["roles"] = { ["greeting"] = true },
    },
    [677670961] = {
        ["english"] = { [1] = "You can find Aldwin Laughlin at the Stormwind Vistor's Center in the Trade District." },
        ["text"] = "Олдвіна Лафліна знайдеш у Центрі відвідувачів Штормовію в Торговому районі.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [637197923] = {
        ["english"] = { [1] = "You need to find Swart.  Look for him inside the barracks on the east side of Razor Hill." },
        ["text"] = "Тобі потрібен Сварт. Шукай його в казармах на східному боці Колючого Пагорба.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [1662523701] = {
        ["english"] = { [1] = "You need only face your rivals in any of the Battlegrounds. Win or lose, if you stay for the duration of the battle, you will be mailed a Competitor's Tabard." },
        ["text"] = "Тобі достатньо битися зі своїми суперниками на будь-якому Полі бою. Переможеш чи програєш — якщо пробудеш там до кінця битви, тобі поштою надішлють Гербову накидку учасника.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4255919060] = {
        ["english"] = { [1] = "You must find one amongst the wretch in the lower portion of this citadel that has attained an Unadorned Seal of Ascension. It is a great honor for one of the lesser beings to obtain this item, as it is the first step in gaining access to the upper citadel and becoming one of Nefarian's elite guardsmen - the Blackhand legion. Find such an item and return it to me so that I may examine its properties. I will know how to proceed once my inspection of the seal is complete." },
        ["text"] = "Ти мусиш знайти серед жалюгідних істот у нижній частині цієї цитаделі того, хто здобув Неприкрашену Печатку Вознесіння. Для нижчих істот це велика честь, адже цей предмет — перший крок до доступу у верхню цитадель і вступу до елітної варти Нефаріана — легіону Чорнорука. Знайди такий предмет і принеси мені, щоб я дослідив його властивості. Після огляду печатки я знатиму, що робити далі.",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["greeting"] = true },
    },
    [2144238271] = {
        ["english"] = { [1] = "You haven't lived until you've looked down on the world from the back of a wind rider." },
        ["text"] = "Ти не жив по-справжньому, доки не дивився на світ із сідла вітрокрила.",
        ["npcs"] = { [1] = 3310 },
        ["roles"] = { ["greeting"] = true },
    },
    [1499777991] = {
        ["english"] = { [1] = "You must be looking for Smith Argus.  He's usually overseeing the forge in Goldshire if you need some training." },
        ["text"] = "Мабуть, ти шукаєш коваля Арґуса. Зазвичай він наглядає за горном у Златозем'ї, якщо тобі потрібне навчання.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [623406947] = {
        ["english"] = { [1] = "You must be hard up to be wandering these Badlands, $c. Hard up like me.$B$BOr maybe you're here because you're crazy. Crazy, like me." },
        ["text"] = "Мабуть, тебе добре притисло, якщо блукаєш Безплідними краями, $c. Так само, як мене.$B$BА може, ти тут, бо божевільний. Божевільний, як я.",
        ["npcs"] = { [1] = 2817 },
        ["roles"] = { ["greeting"] = true },
    },
    [2662796330] = {
        ["english"] = { [1] = "Zarrin seems to have a good knowledge of the cooking trade.  Why don't you go see if he will show you some recipes?  He is usually cooking over by the Inn in Dolanaar." },
        ["text"] = "Заррін, схоже, добре знається на кулінарії. Чому б не попросити його показати кілька рецептів? Зазвичай він готує біля заїзду в Доланаарі.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [4289985418] = {
        ["english"] = { [1] = "You made it! Outstanding! Marshal Windsor has been expecting you. Would you like me to signal him now?" },
        ["text"] = "Ти дістався! Чудово! Маршал Віндзор чекає на тебе. Подати йому сигнал?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [399225715] = {
        ["english"] = { [1] = "Yeah? Ye interrupted me, so ye better have a blasted good reason to do so." },
        ["text"] = "Га? Ти мене перервав, тож краще май до біса вагому причину.",
        ["npcs"] = { [1] = 5513 },
        ["roles"] = { ["greeting"] = true },
    },
    [924948443] = {
        ["english"] = { [1] = "You made it this far, grunt. There is no turning back now." },
        ["text"] = "Ти зайшов так далеко, рубако. Назад дороги вже немає.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3332383593] = {
        ["english"] = { [1] = "You're no warlock and I've no time for you.  Begone!" },
        ["text"] = "Ти не чорнокнижник, і в мене немає на тебе часу. Геть!",
        ["npcs"] = { [1] = 6376, [2] = 12807 },
        ["roles"] = { ["greeting"] = true },
    },
    [1419893278] = {
        ["english"] = { [1] = "You have learned well my child. Go to the Undercity, find a smith named James Van Brunt. He will be able to teach you much that I cannot. I understand he spends his time near the Warriors training hall, forging their weapons and armor." },
        ["text"] = "Ти добре навчився, дитя моє. Іди до Підміста й знайди коваля на ім'я Джеймс Ван Брант. Він навчить тебе багатьох речей, яких я не можу. Кажуть, він проводить час біля зали тренувань воїнів, куючи їм зброю та обладунки.",
        ["npcs"] = { [1] = 3557 },
        ["roles"] = { ["greeting"] = true },
    },
    [1823593631] = {
        ["english"] = { [1] = "Your family says hello, Ribbly.  And they want your head!" },
        ["text"] = "Твоя родина передає вітання, Рібблі. І вони хочуть твою голову!",
        ["npcs"] = { [1] = 9543 },
        ["roles"] = { ["reply"] = true },
    },
    [1572926198] = {
        ["english"] = { [1] = "You know I do, mortal; I am abandoning a fair number of pretenses here, and I recommend you do the same.$B$BYou have come here clearly because you know that what you possess, garnered from your actions within the Sunken Temple of the Atal'al, has brought you to me for a purpose.  This purpose is to put my associate... my brother, to rest.  He is trapped within a nightmare within the Dream itself.  He cannot break free alone." },
        ["text"] = "Ти ж знаєш, що так, смертний; я відкидаю чимало удаваності й раджу тобі зробити так само.$B$BТи явно прийшов сюди, бо розумієш: те, що маєш завдяки своїм діям у Затонулому храмі Атал'ай, привело тебе до мене не випадково. Мета — дати спокій моєму союзнику... моєму братові. Він ув'язнений у кошмарі всередині самого Сну. Сам він не вирветься.",
        ["npcs"] = { [1] = 5353 },
        ["roles"] = { ["greeting"] = true },
    },
    [3071774347] = {
        ["english"] = { [1] = "You can find passage to Theramore from this dock.  Heed my words, those lands are rarely safe to travel for people of the Alliance.  Watch your step and your back.", [2] = "You can find passage to Theramore from this dock. Heed my words, those lands are rarely safe to travel for people of the Alliance. Watch your step and your back." },
        ["text"] = "З цього причалу можна дістатися до Терамора. Запам'ятай мої слова: ті землі рідко бувають безпечними для людей Альянсу. Дивись і під ноги, і за спину.",
        ["npcs"] = { [1] = 12658 },
        ["roles"] = { ["greeting"] = true },
    },
    [1516122104] = {
        ["english"] = { [1] = "You know enough to be dangerous, but you still look like you need training to me $N." },
        ["text"] = "Ти знаєш достатньо, щоб бути небезпечним, але, як на мене, тобі ще не завадило б навчання, $N.",
        ["npcs"] = { [1] = 988, [2] = 3156, [3] = 3172, [4] = 4563 },
        ["roles"] = { ["greeting"] = true },
    },
    [409230663] = {
        ["english"] = { [1] = "Yonn Deepcut can be found inside the great tent at the northwest corner of Bloodhoof Village." },
        ["text"] = "Йонн Глибокий Різ знайдеться у великому наметі в північно-західному кутку селища Криваве Копито.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [757275015] = {
        ["english"] = { [1] = "You killed Ghost Howl.  You're a stud!" },
        ["text"] = "Ти вбив Примарне Виття. Та ти жеребець!",
        ["npcs"] = { [1] = 3052 },
        ["roles"] = { ["greeting"] = true },
    },
    [3207656938] = {
        ["english"] = { [1] = "You honor us with your presence, my lord." },
        ["text"] = "Ти вшановуєш нас своєю присутністю, мій володарю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1681273878] = {
        ["english"] = { [1] = "You must defeat our rivals in any of the Battlegrounds. With every victory, there is a chance that a Gold Medallion will be mailed to you." },
        ["text"] = "Треба перемогти наших суперників на будь-якому Полі бою. Після кожної перемоги є шанс, що тобі поштою надішлють Золотий медальйон.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2823434965] = {
        ["english"] = { [1] = "Yes $gsir:ma'am;, this is quite a drink!  Quite a drink indeed!" },
        ["text"] = "Так, $gпане:пані;, оце напій! Ще й який напій!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1284189590] = {
        ["english"] = { [1] = "You have reached new heights in your path to mastery. Let us see if we can take you even further..." },
        ["text"] = "Ти піднявся на нову висоту на шляху до майстерності. Подивімося, чи зможемо піти ще далі...",
        ["npcs"] = { [1] = 11074 },
        ["roles"] = { ["greeting"] = true },
    },
    [1274244888] = {
        ["english"] = { [1] = "You have not yet proven yourself worthy enough to issue a challenge within Valhalas, $N.$B$BReturn when you have earned a name for yourself." },
        ["text"] = "Ти ще не довів, що гідний кинути виклик у Валгаласі, $N.$B$BПовернися, коли здобудеш собі ім'я.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1166666300] = {
        ["english"] = { [1] = "You have no business with me, little one." },
        ["text"] = "Тобі нема до мене діла, малечо.",
        ["npcs"] = { [1] = 13322 },
        ["roles"] = { ["greeting"] = true },
    },
    [2077282906] = {
        ["english"] = { [1] = "You have learned much, but I sense that there is more left for the spirits to teach you. I can place your foot on the path but cannot guide your steps. Go and find Saru Steelfury in Orgrimmar, the next stretch of your journey begins there." },
        ["text"] = "Ти багато чого навчився, але відчуваю, духи ще мають чого тебе навчити. Я можу вказати стежку, але не пройти її за тебе. Знайди Сару Сталелють в Орґріммарі — там почнеться наступний відрізок твоєї подорожі.",
        ["npcs"] = { [1] = 2998 },
        ["roles"] = { ["greeting"] = true },
    },
    [1160709775] = {
        ["english"] = { [1] = "You have earned the privilege of training with a higher instructor. Go see my pal Roxxik there." },
        ["text"] = "Ти заслужив право навчатися в досвідченішого наставника. Іди до мого приятеля Рокссіка.",
        ["npcs"] = { [1] = 3412 },
        ["roles"] = { ["greeting"] = true },
    },
    [1313104359] = {
        ["english"] = { [1] = "You have done much for our cause, $N, but you may go no further until you have mastered flight. Only the most stalwart riders are able to assist the Netherwing." },
        ["text"] = "Ти багато зробив для нашої справи, $N, але далі не підеш, доки не опануєш польоти. Лише найстійкіші вершники здатні допомагати Крилам Пустоти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1233335948] = {
        ["english"] = { [1] = "You have chosen wisely $N.  Seek out Kergul Bloodaxe on the Hunter Rise.  He will assist you on your journey to Warsong Gulch." },
        ["text"] = "Ти мудро обрав, $N. Знайди Керґула Криваву Сокиру на Мисливському узвишші. Він допоможе тобі на шляху до Ущелини Пісні Війни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [735965622] = {
        ["english"] = { [1] = "You seek someone who cares for animals?  Then you should look for Seriadne outside the Inn in Dolanaar.  She is the one that you seek." },
        ["text"] = "Шукаєш когось, хто дбає про тварин? Тоді тобі до Серіадни біля заїзду в Доланаарі. Саме вона тобі потрібна.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [3353801945] = {
        ["english"] = { [1] = "You found a key?  Well, is it THE key?  I mean, is it the key to unlock these shackles?  Well $G sir : ma'am;, there is only one way to find out!" },
        ["text"] = "Ти знайшов ключ? Ну то це ТОЙ ключ? Я маю на увазі, він відімкне ці кайдани? Що ж, $G пане : пані;, є лише один спосіб дізнатися!",
        ["npcs"] = { [1] = 14338 },
        ["roles"] = { ["greeting"] = true },
    },
    [4046239151] = {
        ["english"] = { [1] = "You can't study my techniques until you've learned the basics. Speak with Kamari if you are interested in training." },
        ["text"] = "Ти не зможеш вивчати мої прийоми, доки не опануєш основи. Якщо хочеш тренуватися, поговори з Камарі.",
        ["npcs"] = { [1] = 3365 },
        ["roles"] = { ["greeting"] = true },
    },
    [3001356136] = {
        ["english"] = { [1] = "You figure out yet why our brothers and sisters over in the village have gone insane?" },
        ["text"] = "Уже з'ясував, чому наші брати й сестри в селищі збожеволіли?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2574342661] = {
        ["english"] = { [1] = "You'll find the Wind Rider Master in Orgrimmar.  Go north up the road to get there and ask an Orgrimmar Grunt for further directions." },
        ["text"] = "Майстра вітрокрилів знайдеш в Орґріммарі. Іди дорогою на північ, а коли дістанешся міста — спитай дорогу в орґріммарського рубаки.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [358276138] = {
        ["english"] = { [1] = "You don't look like much to me, but who knows, maybe there's an enchanter hidden in there somewhere!" },
        ["text"] = "На вигляд у тобі нічого особливого, але хто знає — може, десь усередині ховається заклинач!",
        ["npcs"] = { [1] = 11067 },
        ["roles"] = { ["greeting"] = true },
    },
    [1861311663] = {
        ["english"] = { [1] = "Your skill in blacksmithing is exceptional, $N. The time has come to make a decision. There are two paths you may choose: The way of the weaponsmith or the art of the armorsmith.$B$BBe warned, when you have chosen to dedicate yourself to a path, there is no going back. The discipline each path requires leaves no room for hybrids." },
        ["text"] = "Твої ковальські вміння виняткові, $N. Настав час зробити вибір. Перед тобою два шляхи: шлях зброяра або мистецтво бронника.$B$BЗнай: коли присвятиш себе одному шляху, вороття не буде. Дисципліна кожного з них не залишає місця для поєднання.",
        ["npcs"] = { [1] = 11145 },
        ["roles"] = { ["greeting"] = true },
    },
    [2799698795] = {
        ["english"] = { [1] = "You come to us with title and so we will listen, but do not try our patience, $c.  The council has no time for idle gossip from one such as you." },
        ["text"] = "Ти прийшов до нас із титулом, тож ми вислухаємо. Але не випробовуй наше терпіння, $c. Рада не має часу на пусті балачки з такими, як ти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [187297580] = {
        ["english"] = { [1] = "You can trust any pets you have to be well taken care of by Alassin.  He resides in the Cenarion Enclave where the hunters gather." },
        ["text"] = "Можеш не хвилюватися за своїх вихованців — Алассін добре про них подбає. Він живе в Кенарійському анклаві, де збираються мисливці.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [4166966457] = {
        ["english"] = { [1] = "You there... it is in your best interest to aid the Forsaken during these dire times.  Listen closely, as I dislike repeating myself.$B$BWe currently find ourselves in a dire shortage of cloth.  Bandages and simple textiles are running low, and donations are being accepted to bolster sagging inventories.  While you'll not receive financial compensation - hence what donation means - your aid will not go unnoticed." },
        ["text"] = "Ти там... у твоїх же інтересах допомогти Відреченим у ці скрутні часи. Слухай уважно, я не люблю повторюватися.$B$BМи зараз маємо гостру нестачу тканини. Запаси бинтів і простих тканин тануть, тож приймаємо пожертви, щоб поповнити комори. Грошової винагороди не буде — на те воно й пожертва, — але твоя допомога не лишиться непоміченою.",
        ["npcs"] = { [1] = 14729 },
        ["roles"] = { ["greeting"] = true },
    },
    [965033746] = {
        ["english"] = { [1] = "You Scourge gunna fail here, mon." },
        ["text"] = "Ви, Скверна, тут програєте, чолов'яга.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3125029163] = {
        ["english"] = { [1] = "You can cook?  So can I!  Is there a recipe you can teach me?" },
        ["text"] = "Ти вмієш готувати? Я теж! Може, навчиш мене якогось рецепта?",
        ["npcs"] = { [1] = 8696 },
        ["roles"] = { ["reply"] = true },
    },
    [3682573987] = {
        ["english"] = { [1] = "You better believe it! You're going to face two of Arthas' most powerful Val'kyr lieutenants!" },
        ["text"] = "Ще б пак! Тобі доведеться зійтися з двома наймогутнішими валь'кірами-лейтенантами Артаса!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3012402271] = {
        ["english"] = { [1] = "You are here to assist the Aldor?" },
        ["text"] = "Ти тут, щоб допомогти Алдорам?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3815531232] = {
        ["english"] = { [1] = "Yes?  What do you want?" },
        ["text"] = "Так? Чого тобі?",
        ["npcs"] = { [1] = 15165 },
        ["roles"] = { ["greeting"] = true },
    },
    [3089656688] = {
        ["english"] = { [1] = "Yes, well, listen here, $c. I'm older than I look and wise beyond my years. You'd do well not to question me so much.\010\010Look, you don't need to take my word for it. Read the postings on any local bulletin board for yourself. I'm everywhere!$b$bJust do yourself a favor and ignore the ones with 'WANTED' in the title. Simple misunderstandings, I assure you." },
        ["text"] = "Так-так, слухай сюди, $c. Я старший, ніж здаюся, і мудріший за свої роки. Не варто так багато мене розпитувати.\010\010Не мусиш вірити мені на слово. Сам прочитай оголошення на будь-якій місцевій дошці. Я всюди!$b$bТільки зроби собі послугу й не зважай на ті, де в заголовку написано «РОЗШУКУЄТЬСЯ». Звичайні непорозуміння, запевняю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
}
for key, row in pairs(rows) do addonTable.gossip_hashed.rows[key] = row end
